window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0239", [{"word":"by means of","ipa_uk":"/baɪ ˈmiːnz ɒv/","ipa_us":"/baɪ ˈmiːnz ɑːv/","definition_zh":"凭借、通过；用某种工具、手段或方法达到目的（后接名词或动名词）","definition_en":"by using something as an instrument, method or mechanism; through the agency of something","core_image":"一双手把一把钥匙插进锁孔，门从里面被打开","scene":"仓库大门从里面锁死，管理员没有备用钥匙，只能靠一根长铁钩从门缝把插销拨开。By means of a long iron hook, he slid the bolt back from the outside.","sceneCN":"这里取「凭借、用……作为工具」（第 1 个义项：后接具体名词，指出所借助的器械）；句意为他用一根长铁钩从外面把插销拨回。","pos":[{"tag":"prep. phr.","zh":"介词短语：凭借、通过；以……为手段"}],"collocations":[{"phrase":"by means of which","zh":"凭借它；通过该手段"},{"phrase":"by means of a device","zh":"借助某种装置"},{"phrase":"by means of force","zh":"凭借武力"},{"phrase":"by means of translation","zh":"通过翻译"},{"phrase":"by means of electronic mail","zh":"通过电子邮件"},{"phrase":"solely by means of","zh":"仅靠……"}],"forms":[{"label":"原形","form":"by means of"},{"label":"定语从句形式","form":"by means of which"},{"label":"强调形式","form":"solely by means of"},{"label":"否定形式","form":"not by means of"}],"derivatives":[{"word":"mean","pos":"adj.","zh":"中间的；平均的"},{"word":"means","pos":"n.","zh":"手段；财力；工具"},{"word":"meantime","pos":"adv.","zh":"其间；与此同时"},{"word":"meanwhile","pos":"adv.","zh":"同时；在此期间"},{"word":"median","pos":"adj./n.","zh":"中位数的；中线"}],"senses":[{"no":"01","title":"The instrument in hand","titleCN":"工具义：凭借某件器械","definition":"used before a noun naming a tool or device, to say that this is the thing used to do something","definitionCN":"用在指工具或装置的名词前，表示做某事所借助的就是它","example":"The window was forced open by means of a steel bar.","exampleCN":"窗子是用一根钢条撬开的。","why":"Means began as the middle or intermediate thing, and an instrument stands between a person and a result.","whyCN":"这个词最早指处于中间的事物，工具正介于人与结果之间。"},{"no":"02","title":"The method, not the object","titleCN":"方法义：通过某种做法","definition":"used before a noun or gerund naming a procedure, so the phrase points to how rather than to what","definitionCN":"用在指做法或动名词前，指出的是怎么做，而不是做什么","example":"They settled the dispute by means of direct negotiation.","exampleCN":"他们通过直接谈判解决了争端。","why":"A procedure is also an intermediate step, so the same phrase takes abstract nouns of method.","whyCN":"程序同样是中间步骤，因此这个短语也接表示方法的抽象名词。"},{"no":"03","title":"Formal replacement for a plain preposition","titleCN":"语域义：正式书面语的替换说法","definition":"in formal or academic prose it replaces the plainer with or through without changing the meaning","definitionCN":"在正式或学术文字中替代更朴素的用、通过说法，意义不变","example":"The data were gathered by means of structured interviews.","exampleCN":"数据是通过结构化访谈收集的。","why":"English keeps a longer phrase for registers where a bare preposition would sound too casual.","whyCN":"英语为需要更庄重语体的场合保留了这个较长的短语，以免单个介词显得随意。"},{"no":"04","title":"Agency in passive clauses","titleCN":"施动义：被动句中指明手段而非施动者","definition":"in a passive clause it names the instrument, while a bare by-phrase would name the person or force that acted","definitionCN":"在被动句中它指出所用的手段，而单用由字类介词则指施动的个人或力量","example":"The lock was opened by means of a duplicate key.","exampleCN":"那把锁是用一把配好的钥匙打开的。","why":"The phrase keeps the instrument apart from the agent, which is why a passive clause can carry both.","whyCN":"这个短语把手段与施动者分开，因此被动句里两者可以同时出现。"},{"no":"05","title":"The relative clause it introduces","titleCN":"从句义：后接定语从句","definition":"followed by which, it turns the instrument into the subject of a relative clause","definitionCN":"后接关系代词时，它把手段变成定语从句的主语","example":"They used a crane, by means of which the beam was lifted.","exampleCN":"他们用了一台起重机，横梁就是靠它吊起的。","why":"The phrase plus the relative pronoun lets the sentence continue with the instrument as its subject.","whyCN":"短语加关系代词后，句子可以接着让手段本身当主语。"},{"no":"06","title":"What is not a means","titleCN":"辨义：手段不等于路线或途径","definition":"it does not describe a route travelled, so it cannot take the name of a road or a stopover","definitionCN":"它不描述行经的路线，因此不能接道路或中途停留地的名称","example":"The goods went north by means of rail freight, not along the coastal road.","exampleCN":"货物是靠铁路货运北上的，不是沿滨海公路走。","why":"Route phrases answer which way a thing passes, while this phrase answers what carried or did the work.","whyCN":"路线说法回答经由哪条路过去，这个短语回答用什么来完成。"},{"no":"07","title":"Means of communication","titleCN":"媒介义：借助某种通道或媒介","definition":"with names of media it states the channel through which a signal or message arrives","definitionCN":"与媒介名称连用时，表示信号或消息通过哪条通道抵达","example":"The warning reached the villages by means of radio broadcasts.","exampleCN":"警报通过无线电广播传到各村。","why":"A channel is the middle element between sender and receiver, exactly what the noun means denotes.","whyCN":"通道正是发送者与接收者之间的中间环节，恰是这个名词所表示的东西。"},{"no":"08","title":"A definition device","titleCN":"定义义：用于界定术语的手段","definition":"in definitions it introduces the operation that produces the thing being defined","definitionCN":"在定义句中，它引出产生该术语所指结果的操作","example":"A hybrid is defined by means of the two sources it combines.","exampleCN":"混合体是通过它所结合的两个来源来定义的。","why":"Definitions need a stated operation, and the phrase supplies the instrument by which the term is produced.","whyCN":"定义需要一个明确的操作，这个短语正好提供产生该术语的手段。"}],"etymology":{"intro":{"en":"Means is the plural of mean, a noun for the middle point, from Latin medianus. The modern phrase is fixed; the Latin adjective itself is secure.","cn":"手段一词是「中间」名词的复数，来自拉丁语 medianus。这个现代短语已经定型；拉丁语形容词的来源清楚。"},"items":[{"era":"LATIN MEDIANUS","en":"Medianus meant middle or central, and English took it through Old French as the adjective mean.","cn":"medianus 意为中间、居中的，英语经古法语借入，成为形容词 mean。"},{"era":"MIDDLE AS INTERMEDIARY","en":"What sits in the middle between a person and a goal came to be called a means; the verb meaning to intend is a different, native word.","cn":"位于人与目标之间的事物逐渐被称作手段；另有表意为、打算的动词，属古英语本族词，与此无关。"},{"era":"PLURAL FOR RESOURCES","en":"The plural widened from one device to money, tools and abilities, as in a person of means.","cn":"复数形式从单件工具扩展到钱财、器械与能力，如有财力的人这种说法。"},{"era":"THE FIXED PHRASE","en":"The phrase with this preposition and of is a modern written formula for instrument and method; first dates are approximate.","cn":"这个介词加 of 的短语是近代书面语中表示工具与方法的固定格式，首见年代为约数。"},{"era":"REGISTER SPLIT","en":"Speech prefers with or through, and the longer phrase survives in legal, scientific and official writing.","cn":"口语更常用用、通过，较长的短语则留存在法律、科技与公文里。"}]},"similar":{"note":{"en":"The first group marks route, function or legal ground rather than an instrument; the second group gives plain instrument and agency phrases.","cn":"第一组说的是路线、用途或法律依据，而非工具；第二组是朴素的工具与施动说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"by way of","ipa":"/baɪ weɪ əv/","tag":"route, not tool","definition":"It names the road or the stage passed through, not the tool used.","definitionCN":"它说的是经过哪条路或哪个阶段，而不是用什么工具。"},{"word":"in the way of","ipa":"/ɪn ðə weɪ əv/","tag":"thing available","definition":"It means as a kind of, often of something offered or available.","definitionCN":"意为作为某种，常指提供或具备的事物。"},{"word":"by virtue of","ipa":"/baɪ ˈvɜːtʃuː əv/","tag":"because of a quality","definition":"It points to a right, quality or legal power rather than a tool.","definitionCN":"它指凭某种权利、品质或法律效力，而非工具。"},{"word":"on the strength of","ipa":"/ɒn ðə ˈstreŋθ əv/","tag":"relying on support","definition":"It rests a claim on evidence or a recommendation.","definitionCN":"它把主张建立在证据或推荐之上。"}]},{"heading":"NEAR MEANING","entries":[{"word":"through","ipa":"/θruː/","tag":"plain instrument","definition":"A single preposition that covers means and route alike.","definitionCN":"单个介词，兼指手段与经由。"},{"word":"with","ipa":"/wɪð/","tag":"tool or material","definition":"It names the thing used, usually short and spoken.","definitionCN":"点出所用的东西，通常简短且偏口语。"},{"word":"using","ipa":"/ˈjuːzɪŋ/","tag":"gerund","definition":"A participle that states the tool before the main clause.","definitionCN":"分词形式，在主句前说明所用工具。"},{"word":"by","ipa":"/baɪ/","tag":"agent or means","definition":"It may name either the doer or the instrument, so context decides.","definitionCN":"它既可指施动者也可指手段，须靠语境判断。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real middle root, the plural of resources, and the real grammar of instrument and agent.","cn":"正常联想用真实的中间词根、复数的资源义与真实的工具、施动者语法。"},"normal":[{"en":"Middle gives the idea: a means stands between the doer and the finished act.","cn":"中间给出思路：手段位于施动者与完成的动作之间。"},{"en":"The plural matters: the noun covers money, tools and abilities at once.","cn":"复数很关键：这个名词同时涵盖钱财、器械与能力。"},{"en":"In a passive clause it keeps the instrument apart from the person.","cn":"在被动句里它把工具与施动的人分开。"},{"en":"The same frame takes a relative pronoun to build a clause.","cn":"同一框架加关系代词可构成定语从句。"},{"en":"A route phrase cannot stand here, because a road does not act.","cn":"路线说法不能放在这里，因为道路本身不施动。"}],"abstract":[{"en":"Like a bridge plank laid between two banks: not the destination, only the crossing.","cn":"像搭在两岸之间的一块桥板：不是终点，只是跨越的凭借。"},{"en":"Like a middleman in a deal, who never owns the goods but makes the exchange happen.","cn":"像交易里的中间人，从不拥有货物，却让交换得以发生。"},{"en":"Like the middle rung of a ladder, useless alone but decisive for reaching the top.","cn":"像梯子中间的一根横档，单看无用，却是登顶的关键。"}]},"examples":[{"en":"The door was opened by means of a thin metal strip.","cn":"门是用一片薄金属条打开的。"},{"en":"Researchers mapped the valley by means of aerial photographs.","cn":"研究人员通过航空照片绘制了山谷地图。"},{"en":"The message was passed on by means of a hand signal.","cn":"消息是通过一个手势传递的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「拜 敏兹 奥夫」——钥匙插在人与门之间：凭借、通过","word":"by means of"},"root":"核心名词意为手段，本指中间点，来自拉丁语 medianus「居中的」，复数形式引申为手段与财力；该短语在近代书面语中定型，首见年代不确定。","sensesIntro":{"en":"Eight senses separate the tool, the method, the register, the passive instrument, the relative clause, the contrast with route phrases, the channel of communication and the definition device.","cn":"八个义项分别区分：器械、方法、语域、被动句中的手段、定语从句、与路线说法的对照、传播通道、定义手段。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand inserting a key into a lock, the key standing between the person and the opened door.","cn":"核心意象：一只手把钥匙插进锁孔，钥匙正位于人与被打开的门之间。"},"chain":["MIDDLE POINT","INTERMEDIARY","INSTRUMENT","METHOD","CHANNEL","DEFINITION"],"branches":[{"senses":"01 · 04","en":"THE TOOL: a device or key stands between the actor and the act.","cn":"工具：器械或钥匙位于施动者与动作之间。"},{"senses":"02 · 05","en":"THE PROCEDURE: a method or a relative clause states how the result is reached.","cn":"程序：方法或定语从句说明结果如何达成。"},{"senses":"03","en":"THE REGISTER: formal prose prefers this longer formula to a bare preposition.","cn":"语域：正式文字偏好这个较长格式而非单个介词。"},{"senses":"06","en":"THE BOUNDARY: a route answer is excluded, because this phrase names what acts.","cn":"边界：排除经由哪条路线的答案，因为本短语说的是用什么起作用。"},{"senses":"07 · 08","en":"THE CHANNEL AND THE LABEL: media carry messages, and definitions name the operation.","cn":"通道与标签：媒介传递消息，定义则点明操作。"}]},"affixes":{"intro":{"en":"The phrase joins two prepositions to the plural noun for a middle thing, whose root is the Latin adjective for middle.","cn":"这个短语由两个介词加表中间之物的复数名词构成，其词根是拉丁语中表中间的形容词。"},"latinIntro":{"en":"Latin medianus, middle, passed through Old French into English; the noun sense of resources is English.","cn":"拉丁语 medianus「中间的」经古法语进入英语；表资源的名词义是英语自身的发展。"},"items":[{"word":"medianus","structure":"Latin adjective","meaning":"middle; central","meaningCN":"中间的；居中的","example":"The adjective underlies the English noun for a middle point.","exampleCN":"这个形容词是英语中间点名词的来源。"},{"word":"mean","structure":"English adjective","meaning":"middle; average","meaningCN":"中间的；平均的","example":"The adjective keeps the Latin sense of what lies in the centre.","exampleCN":"形容词保留了拉丁语位于中央的意思。"},{"word":"means","structure":"English plural noun","meaning":"resources; instruments","meaningCN":"手段；财力","example":"The plural shifted from one middle thing to a set of resources.","exampleCN":"复数从单个中间物转指一组资源。"},{"word":"meantime","structure":"mean + time","meaning":"the period between two events","meaningCN":"其间；两事之间的时间","example":"The compound keeps the middle sense of the first element.","exampleCN":"这个复合词保留了第一个成分的中间义。"},{"word":"meanwhile","structure":"mean + while","meaning":"at the same time","meaningCN":"与此同时","example":"The adverb uses the same middle element with a time word.","exampleCN":"这个副词用同一个中间成分搭配时间词。"},{"word":"median","structure":"Latin medianus","meaning":"the middle value","meaningCN":"中位数；中间值","example":"The statistical term returns to the Latin adjective directly.","exampleCN":"这个统计术语直接回到拉丁语形容词。"},{"word":"by means of","structure":"preposition + plural noun + preposition","meaning":"through the use of","meaningCN":"凭借；通过","example":"The phrase is standard in formal description.","exampleCN":"这个短语是正式说明文中的标准用法。"},{"word":"by no means","structure":"fixed negative phrase","meaning":"not at all","meaningCN":"绝不；一点也不","example":"The same noun in a negative frame means in no way.","exampleCN":"同一个名词放进否定框架，表示绝不。"}],"latinEntries":[{"word":"medianus","structure":"medianus, -a, -um (adjective, first and second declension)","meaning":"middle; central","meaningCN":"中间的；居中的"}],"derivatives":[{"word":"mean","pos":"adj.","zh":"中间的；平均的"},{"word":"means","pos":"n.","zh":"手段；财力"},{"word":"meantime","pos":"adv.","zh":"其间"},{"word":"meanwhile","pos":"adv.","zh":"与此同时"},{"word":"median","pos":"adj./n.","zh":"中位数的；中线"}]}},{"word":"for the purpose of","ipa_uk":"/fɔː ðə ˈpɜːpəs ɒv/","ipa_us":"/fɔːr ðə ˈpɜːrpəs ɑːv/","definition_zh":"为了……目的；为……之用（后接名词或动名词，说明行为所要达到的目标）","definition_en":"in order to achieve a stated aim; for the use or function of something","core_image":"一张便签贴在文件夹上，写明这份材料要办的是哪一件事","scene":"审计员把一摞票据按用途分装，每一袋外面都写着要办的事项。The clerk sorted the receipts into bags for the purpose of a year-end audit.","sceneCN":"这里取「为了……目的」（第 1 个义项：后接名词短语，点明行为的目标）；句意为职员把票据分袋，为的是年终审计。","pos":[{"tag":"prep. phr.","zh":"介词短语：为了……目的；为……之用"}],"collocations":[{"phrase":"for the purpose of discussion","zh":"为了讨论"},{"phrase":"for the purpose of comparison","zh":"为了比较"},{"phrase":"for the purpose of taxation","zh":"为征税之目的"},{"phrase":"for the purpose of this clause","zh":"为本条款之目的"},{"phrase":"for the purpose of identification","zh":"为辨认身份"},{"phrase":"for the purpose of study","zh":"为了研究"}],"forms":[{"label":"原形","form":"for the purpose of"},{"label":"后接动名词","form":"for the purpose of doing"},{"label":"法律复数变体","form":"for the purposes of"},{"label":"否定形式","form":"not for the purpose of"}],"derivatives":[{"word":"purpose","pos":"n.","zh":"目的；用途；意图"},{"word":"purposeful","pos":"adj.","zh":"有目的的；坚定的"},{"word":"purposely","pos":"adv.","zh":"故意地"},{"word":"purposeless","pos":"adj.","zh":"无目的的"},{"word":"propose","pos":"v.","zh":"提议（同拉丁词根，语义已分化）"}],"senses":[{"no":"01","title":"Aim before a noun","titleCN":"目的状语：后接名词说明目标","definition":"used before a noun to state the aim that an action is meant to serve","definitionCN":"用在名词前，说明某一行为所要服务的目标","example":"The samples were stored for the purpose of later analysis.","exampleCN":"样品被存放起来，是为了日后分析。","why":"Purpose is what is put before the mind, so the phrase takes the aim as a noun rather than as an act.","whyCN":"目的是被放到心前的东西，因此这个短语把目标写成名词，而非写成动作。"},{"no":"02","title":"Aim before a gerund","titleCN":"动名词义：后接动作说明目标","definition":"used before a gerund when the aim is itself an activity","definitionCN":"当目标本身是一个活动时，用在动名词前","example":"The team met for the purpose of choosing a site.","exampleCN":"团队开会是为了选定一处场地。","why":"The gerund names an activity, and the frame keeps it in noun position, where the aim belongs.","whyCN":"动名词指一项活动，而这个框架把它留在名词位置，正是目标该在的位置。"},{"no":"03","title":"The legal formula","titleCN":"法律义：条款中的目的表述","definition":"in contracts and statutes it defines why a power is granted or a step is required","definitionCN":"在合同与法规中，用以说明某项权力或某个步骤为何被设定","example":"For the purpose of this agreement, the date of delivery is the date of the stamp.","exampleCN":"就本协议而言，交付日期即盖章之日。","why":"Legal drafting needs every term pinned down, so the aim of a clause is stated in a fixed frame.","whyCN":"法律起草要求每个词都有确指，因此条款的目的要用固定框架写明。"},{"no":"04","title":"Designed use of a thing","titleCN":"用途义：某物被造来做什么","definition":"used before a noun naming the function that an object, room or sum of money is intended to serve","definitionCN":"用在名词前，指出某件物品、某个房间或某笔款项预定的用途","example":"This room was built for the purpose of storing grain.","exampleCN":"这个房间是为储粮而建的。","why":"Here the aim belongs to the object rather than to a person, so purpose slides from intention to function.","whyCN":"这里的目标属于物品而非人，于是目的从意图滑向用途。"},{"no":"05","title":"Why it is not the infinitive frame","titleCN":"语法边界：不能接动词不定式","definition":"it takes a noun or a gerund, so a bare infinitive cannot follow it, unlike the shorter purpose markers","definitionCN":"它后接名词或动名词，因此不能接光秃秃的不定式，这与更短的目的标记不同","example":"They left early for the purpose of catching the first ferry.","exampleCN":"他们早早出发，是为了赶上头一班渡船。","why":"The of in the phrase already governs a nominal element, which is why the verb must be turned into a gerund.","whyCN":"短语中的介词已经支配一个名词性成分，所以动词必须改成动名词。"},{"no":"06","title":"Registration and official use","titleCN":"登记义：官方用途的固定搭配","definition":"in registration, taxation and licensing it states the official use that justifies a status","definitionCN":"在登记、税务与许可事务中，说明使某一状态成立的正当事由","example":"The vehicle is registered for the purpose of business use.","exampleCN":"这辆车是按营业用途登记的。","why":"Official categories are uses, not motives, so the same frame labels a status rather than a feeling.","whyCN":"官方分类看的是用途而非动机，因此同一框架标注的是一种身份，而非一种心情。"},{"no":"07","title":"Intention, not result","titleCN":"辨义：说的是意图，不是结果","definition":"it states what someone meant to achieve and says nothing about whether it was achieved","definitionCN":"它只说明某人打算达成什么，并不涉及是否真的达成","example":"He spoke for the purpose of warning, not of blaming.","exampleCN":"他发言是为了提醒，而不是为了责备。","why":"The noun names a projected aim, so a sentence with this phrase can be true even when the aim fails.","whyCN":"这个名词指预先设想的目标，因此即使用途落空，句子仍然成立。"},{"no":"08","title":"The formal register","titleCN":"语域义：比口语说法更庄重","definition":"in official and academic prose it replaces the plainer shorter purpose markers and sounds more deliberate","definitionCN":"在公文与学术文字中替代更简短的目的说法，语气更审慎","example":"The commission was set up for the purpose of reviewing the law.","exampleCN":"该委员会之设立，是为了审查这项法律。","why":"A longer frame signals deliberateness, which is why statutes and reports favour it over everyday wording.","whyCN":"较长的框架显出审慎，这正是法规与报告偏爱它的原因。"}],"etymology":{"intro":{"en":"Purpose comes from Old French porpos, an intention, from the verb porposer, to put forth, which continues Latin proponere, to place before. The Latin verb is secure; the phrase is modern.","cn":"目的一词来自古法语 porpos「意图」，出自动词 porposer「放到前面」，后者延续拉丁语 proponere「置于前」。拉丁语动词来源清楚；短语属近代。"},"items":[{"era":"LATIN PONERE","en":"Ponere meant to place or set down, and it underlies a large family of English words through its compounds.","cn":"ponere 意为放置、安置，通过其复合形式构成一大批英语词。"},{"era":"PROPONERE","en":"Proponere added the prefix for forward and meant to put something before someone, hence to propose.","cn":"proponere 加上表向前的前缀，意为把某物摆到人前，由此有提议之义。"},{"era":"OLD FRENCH PORPOS","en":"French kept the sense of a plan held in mind, and English borrowed it as purpose.","cn":"法语保留了心中所持计划的意思，英语借入后成为目的。"},{"era":"FROM AIM TO USE","en":"The noun widened from a person's intention to the function built into an object.","cn":"这个名词从人的意图扩展到物品本身被赋予的用途。"},{"era":"THE FIXED PHRASE","en":"The frame with this preposition and of settles in legal and official drafting; first dates are approximate.","cn":"这个介词加 of 的框架在法律与公文中定型，首见年代为约数。"}]},"similar":{"note":{"en":"The first group looks like a purpose marker but takes a verb or carries another sense; the second group holds genuine purpose frames.","cn":"第一组外形接近目的标记，但后接动词或另有他义；第二组才是真正的目的框架。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in order to","ipa":"/ɪn ˈɔːdə tuː/","tag":"infinitive, not noun","definition":"It takes a verb, so a noun cannot follow it.","definitionCN":"它后接动词，因此不能接名词。"},{"word":"so as to","ipa":"/səʊ æz tuː/","tag":"purpose with a verb","definition":"It also takes a verb and usually follows the main clause.","definitionCN":"它同样接动词，通常放在主句之后。"},{"word":"for purposes of","ipa":"/fɔː ˈpɜːpəsɪz əv/","tag":"plural legal variant","definition":"The plural form is the standard variant in contracts.","definitionCN":"复数形式是合同中的标准变体。"},{"word":"on purpose","ipa":"/ɒn ˈpɜːpəs/","tag":"deliberately","definition":"It describes doing something intentionally, not an aim.","definitionCN":"它指故意去做，而非说明目标。"}]},{"heading":"NEAR MEANING","entries":[{"word":"in order that","ipa":"/ɪn ˈɔːdə ðæt/","tag":"clause of purpose","definition":"It introduces a full clause with a modal verb.","definitionCN":"它引出带动情态动词的完整从句。"},{"word":"with a view to","ipa":"/wɪð ə vjuː tuː/","tag":"formal aim","definition":"It takes a noun or gerund and sounds formal.","definitionCN":"后接名词或动名词，语体正式。"},{"word":"aimed at","ipa":"/ˈeɪmd æt/","tag":"participial","definition":"It attaches the aim to the subject as a participle.","definitionCN":"以分词形式把目标挂在主语上。"},{"word":"designed to","ipa":"/dɪˈzaɪnd tuː/","tag":"object function","definition":"It states what an object is made to do.","definitionCN":"说明某物被造来做什么。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin verb for placing before, the legal plural, and the real grammar of noun and gerund.","cn":"正常联想用真实的拉丁语置前动词、法律复数形式，以及真实的名词与动名词语法。"},"normal":[{"en":"To put something before the mind is to hold it as an aim.","cn":"把某物摆到心前，就是把它当作目标。"},{"en":"The noun follows at once, because the aim is treated as a thing.","cn":"名词紧跟其后，因为目标被当作一件东西。"},{"en":"An activity must become a gerund before it can stand there.","cn":"活动必须先变动名词，才能放在那个位置。"},{"en":"Contracts use the plural variant to cover several aims at once.","cn":"合同用复数变体，以便同时涵盖多个目的。"},{"en":"The frame states intention only, never success.","cn":"这个框架只陈述意图，从不保证成功。"}],"abstract":[{"en":"Like a label on a box that says what the box is for, not what it contains.","cn":"像箱外的标签，写明箱子做什么用，而不写里面装了什么。"},{"en":"Like an arrow drawn before the shot: it fixes the target, not the hit.","cn":"像射击前画下的箭头：定的是靶，不是命中。"},{"en":"Like a clause heading in a contract that tells the reader why the rule exists.","cn":"像合同里的小标题，告诉读者这条规则为何存在。"}]},"examples":[{"en":"The survey was conducted for the purpose of testing the new design.","cn":"这项调查是为了检验新设计而进行的。"},{"en":"The fund was created for the purpose of helping small farmers.","cn":"该基金是为帮助小农而设立的。"},{"en":"Records are kept for the purpose of audit and control.","cn":"保存记录是为了审计与监管。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「佛 则 破波斯 奥夫」——便签上写明这袋材料要办的事：为了……目的","word":"for the purpose of"},"root":"核心名词意为目的，出自拉丁语 proponere「放到前面」，经古法语 porpos「意图」进入英语；该短语为近代公文定型，首见年代不确定。","sensesIntro":{"en":"Eight senses run from a noun aim to a gerund aim, then to the legal formula, the designed use, the ban on the infinitive, official registration, intention without result, and the formal register.","cn":"八个义项从名词目标到动名词目标，再到法律条款、物品用途、不能接不定式的语法边界、官方登记、只表意图不表结果，最后是正式语域。"},"semanticMap":{"core":{"en":"CORE IMAGE: a note stuck on a folder, stating the one thing this folder is meant to accomplish.","cn":"核心意象：一张便签贴在文件夹上，写明这份材料要办的一件事。"},"chain":["PLACE FORTH","INTENTION","AIM","USE","LEGAL FORMULA","REGISTER"],"branches":[{"senses":"01 · 03","en":"THE AIM: a noun states the goal that an act is meant to serve.","cn":"目标：名词说明行为所要服务的目标。"},{"senses":"02","en":"THE GERUND: an activity is placed in the noun slot, not as an infinitive.","cn":"动名词：活动被放进名词位置，而不是写成不定式。"},{"senses":"04 · 06","en":"THE USE: rooms and vehicles are labelled by the function they were made for.","cn":"用途：房间与车辆按被造来的用途标注。"},{"senses":"05 · 07","en":"THE BOUNDARY: the frame takes no infinitive and claims no result.","cn":"边界：这个框架不接不定式，也不声称结果。"},{"senses":"08","en":"THE REGISTER: statutes and reports prefer this fuller, more deliberate wording.","cn":"语域：法规与报告偏爱这种更完整、更审慎的措辞。"}]},"affixes":{"intro":{"en":"The phrase is built on a French noun of intention whose Latin base means to place or put.","cn":"这个短语建在一个表意图的法语名词上，其拉丁词根意为放置、安置。"},"latinIntro":{"en":"The Latin verb is ponere, to place, with its prefixed form proponere, to set before; the noun propositum supplied the French sense of intention.","cn":"拉丁语动词为 ponere「放置」，其加前缀形式 proponere 意为置于前；名词 propositum 给出法语中的意图义。"},"items":[{"word":"ponere","structure":"Latin verb","meaning":"to place; to set","meaningCN":"放置；安置","example":"The verb is the base of a whole family of placement words.","exampleCN":"这个词是一整族表放置词语的根。"},{"word":"proponere","structure":"pro- + ponere","meaning":"to put forward","meaningCN":"放到前面；提出","example":"The prefix adds forward movement to placing.","exampleCN":"前缀为放置加上向前的方向。"},{"word":"propositum","structure":"Latin noun from proponere","meaning":"a plan; a stated aim","meaningCN":"计划；既定目标","example":"The noun names what has been put before the mind.","exampleCN":"这个名词指被摆到心前的东西。"},{"word":"purpose","structure":"Old French porpos","meaning":"aim; intended use","meaningCN":"目的；用途","example":"English keeps both the intention and the function.","exampleCN":"英语兼指意图与用途。"},{"word":"purposeful","structure":"purpose + -ful","meaning":"having a clear aim","meaningCN":"有明确目标的","example":"The suffix marks the presence of the quality.","exampleCN":"后缀表示具备这种性质。"},{"word":"purposely","structure":"purpose + -ly","meaning":"on purpose","meaningCN":"故意地","example":"The adverb turns the aim into a manner of acting.","exampleCN":"副词把目标转为行动方式。"},{"word":"propose","structure":"proponere through French","meaning":"to suggest; to put forward","meaningCN":"提议；提出","example":"The verb keeps the original placing-before image.","exampleCN":"这个动词保留了原本的置前意象。"},{"word":"proposal","structure":"propose + -al","meaning":"a formal suggestion","meaningCN":"提议；方案","example":"The noun names the thing put forward.","exampleCN":"名词指被提出的东西。"},{"word":"for the purpose of","structure":"preposition + noun + preposition","meaning":"with the aim of","meaningCN":"为了……目的","example":"The frame is fixed in official prose.","exampleCN":"这个框架在公文中已经定型。"}],"latinEntries":[{"word":"ponere","structure":"ponere, posui, positum (verb, third conjugation)","meaning":"to place; to set","meaningCN":"放置；安置"},{"word":"proponere","structure":"proponere, proposui, propositum (verb)","meaning":"to put forward; to propose","meaningCN":"放到前面；提出"},{"word":"propositum","structure":"propositum, -i (noun, second declension)","meaning":"a plan; a purpose","meaningCN":"计划；目的"}],"derivatives":[{"word":"purpose","pos":"n.","zh":"目的；用途"},{"word":"purposeful","pos":"adj.","zh":"有目的的"},{"word":"purposely","pos":"adv.","zh":"故意地"},{"word":"purposeless","pos":"adj.","zh":"无目的的"},{"word":"propose","pos":"v.","zh":"提议"}]}},{"word":"in the course of","ipa_uk":"/ɪn ðə ˈkɔːs ɒv/","ipa_us":"/ɪn ðə ˈkɔːrs ɑːv/","definition_zh":"在……期间；在……过程中（强调事件展开的时间跨度，而非某一时点）","definition_en":"during the progress or development of an event; over the span in which something unfolds","core_image":"一条河道从上游蜿蜒到下游，两岸景物随水流依次变化","scene":"修堤工程从春汛后开工，入冬前完工，其间挖土、砌石、验收依次进行。Three design changes were made in the course of the dike project.","sceneCN":"这里取「在……过程中」（第 2 个义项：事件推进期间发生）；句意为堤坝工程进行期间做了三次设计变更。","pos":[{"tag":"prep. phr.","zh":"介词短语：在……期间；在……过程中"}],"collocations":[{"phrase":"in the course of time","zh":"随着时间的推移"},{"phrase":"in the course of history","zh":"在历史进程中"},{"phrase":"in the course of events","zh":"在事态发展过程中"},{"phrase":"in the course of the trial","zh":"在审判过程中"},{"phrase":"in the course of development","zh":"在开发过程中"},{"phrase":"in the course of a year","zh":"在一年之内"}],"forms":[{"label":"原形","form":"in the course of"},{"label":"时间变体","form":"in the course of time"},{"label":"事件变体","form":"in the course of events"},{"label":"名词化","form":"the course of"}],"derivatives":[{"word":"course","pos":"n.","zh":"进程；课程；航向"},{"word":"current","pos":"adj./n.","zh":"当前的；水流"},{"word":"currently","pos":"adv.","zh":"目前；当前"},{"word":"currency","pos":"n.","zh":"货币；流通"},{"word":"curriculum","pos":"n.","zh":"课程体系"}],"senses":[{"no":"01","title":"Across a period","titleCN":"时间义：在……期间","definition":"used before a noun of time to say that something happens somewhere inside that span","definitionCN":"用在表时间的名词前，表示某事在该时段之内发生","example":"Two repairs were carried out in the course of the decade.","exampleCN":"这十年间进行了两次维修。","why":"Course is a running, and a run has length, so the phrase measures the span rather than a point.","whyCN":"进程本是一次奔跑，而奔跑有长度，因此这个短语量的是时段，不是一个点。"},{"no":"02","title":"Inside a developing event","titleCN":"过程义：在某事推进期间","definition":"used before the name of an event to say that something happens while that event unfolds","definitionCN":"用在事件名称前，表示某事在该事件展开期间发生","example":"The plan was revised in the course of the survey.","exampleCN":"调查进行期间，方案作了修订。","why":"An event has stages, and the phrase places the action somewhere along them.","whyCN":"事件有阶段，这个短语把动作放在其中某处。"},{"no":"03","title":"As events unfold","titleCN":"事态义：在事态发展中","definition":"in the fixed phrase with events it means as matters develop naturally, without a plan","definitionCN":"在与事态一词的固定搭配中，表示随事情自然发展，并无预先安排","example":"It will become clear in the course of events.","exampleCN":"随着事态发展，事情自会清楚。","why":"The plural of event suggests an open series, so the phrase sounds like the future revealing itself.","whyCN":"事件的复数是开放序列，因此这个短语听起来像未来自行显现。"},{"no":"04","title":"Unlike a plain during","titleCN":"辨义：与单个时间介词不同","definition":"it stresses the unfolding process, while a bare time preposition only marks the period","definitionCN":"它强调展开的过程，而单个时间介词只标出时段","example":"In the course of the talks, the tone changed from hostile to calm.","exampleCN":"会谈过程中，语气由敌对转为平和。","why":"The noun course adds movement, so the phrase suits change over time better than a neutral preposition.","whyCN":"进程一词加了动感，所以这个短语比中性介词更适合描述随时间的变化。"},{"no":"05","title":"Legal and official proceedings","titleCN":"程序义：在正式程序进行期间","definition":"in legal usage it covers steps taken while a case, hearing or inquiry is running","definitionCN":"在法律用法中，指案件、听证或调查进行期间采取的步骤","example":"The document was filed in the course of the proceedings.","exampleCN":"该文件是在诉讼进行期间提交的。","why":"Proceedings are a sequence of formal steps, which is why course fits the legal frame exactly.","whyCN":"诉讼程序是一连串正式步骤，因此进程一词与这一法律框架严丝合缝。"},{"no":"06","title":"Across history","titleCN":"历史义：在历史进程中","definition":"with history or a long era it means over the slow span in which large changes occur","definitionCN":"与历史或漫长时期连用，指大变化在其中缓慢发生的长时段","example":"Trade routes shifted in the course of history.","exampleCN":"贸易路线在历史进程中发生了转移。","why":"The phrase scales up: any span with internal development can be called a course.","whyCN":"这个短语可以放大使用：任何内部有发展的时段都可称为一个进程。"},{"no":"07","title":"Within a short span","titleCN":"短时段义：在……之内完成","definition":"with a short unit of time it means the whole thing happened before that unit ended","definitionCN":"与短时间单位连用，表示整件事在该单位结束前已经发生","example":"The whole procedure was completed in the course of a single morning.","exampleCN":"整个程序在一个上午之内就完成了。","why":"Even a morning has parts, so the phrase still suggests a span with something happening inside it.","whyCN":"即便一个上午也有若干部分，因此这个短语仍暗示时段内部发生了事情。"},{"no":"08","title":"Not a ship's route","titleCN":"辨义：不表航向或路线","definition":"although the noun can mean a direction taken, the phrase itself marks time rather than the path followed","definitionCN":"尽管这个名词可指所取的方向，短语本身标的是时间，而非行经的路径","example":"In the course of the voyage marks the period, not the route the ship followed.","exampleCN":"航行过程一语标出的是时段，不是船只走过的路线。","why":"With this preposition the noun loses its directional sense and keeps only duration.","whyCN":"与这个介词连用时，名词失去方向义，只保留持续义。"}],"etymology":{"intro":{"en":"Course comes from Latin cursus, a running or a passage, from the verb currere, to run. The noun is secure; the English fixed phrase is modern.","cn":"课程、进程一词来自拉丁语 cursus「奔跑、行程」，出自动词 currere「跑」。名词来源清楚；英语固定短语属近代。"},"items":[{"era":"LATIN CURRERE","en":"Currere meant to run, and its participle and nouns spread across movement, flow and speed.","cn":"currere 意为跑，其分词与名词形式扩展到运动、流动与速度。"},{"era":"CURSUS","en":"Cursus named a run, a race or a passage across water, hence a route with length.","cn":"cursus 指奔跑、赛程或渡水行程，因此是一条有长度的路线。"},{"era":"OLD FRENCH COURS","en":"French kept the running and the path, and added the sense of a series of lessons.","cn":"法语保留了奔跑与路径，又发展出一系列课业的意思。"},{"era":"COURSE IN ENGLISH","en":"English holds direction, progression and a programme of study in one noun.","cn":"英语用同一个名词兼指方向、进展与课程体系。"},{"era":"THE FIXED PHRASE","en":"The time-span frame settles in modern narrative and legal prose; first dates are approximate.","cn":"表时段的框架在近代叙事与法律文字中定型，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the noun but means something else; the second group also marks time, with different force.","cn":"第一组共用这个名词却另有他义；第二组同样标时间，但力量不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in due course","ipa":"/ɪn djuː ˈkɔːs/","tag":"no complement","definition":"It means at the proper time and takes no noun after it.","definitionCN":"意为在适当时候，后面不带名词。"},{"word":"of course","ipa":"/əv ˈkɔːs/","tag":"certainly","definition":"In speech it marks agreement or the obvious.","definitionCN":"口语中表同意或显而易见。"},{"word":"course of study","ipa":"/ˈkɔːs əv ˈstʌdi/","tag":"curriculum","definition":"Here the noun means a programme of lessons.","definitionCN":"此处名词指课程体系。"},{"word":"in the course of events","ipa":"/ɪn ðə ˈkɔːs əv ɪˈvents/","tag":"fixed variant","definition":"The same frame with the noun events means as matters unfold.","definitionCN":"同一框架配上事态一词，表示随事态展开。"}]},{"heading":"NEAR MEANING","entries":[{"word":"during","ipa":"/ˈdjʊərɪŋ/","tag":"plain time","definition":"A single preposition for a period, with no sense of development.","definitionCN":"单个介词表时段，不含进展意味。"},{"word":"throughout","ipa":"/θruːˈaʊt/","tag":"whole period","definition":"It stresses the entire span rather than events inside it.","definitionCN":"强调整个时段，而非期间发生的事。"},{"word":"while","ipa":"/waɪl/","tag":"simultaneous","definition":"It links two actions happening at the same time.","definitionCN":"连接同时发生的两件事。"},{"word":"in the middle of","ipa":"/ɪn ðə ˈmɪdl əv/","tag":"midpoint","definition":"It locates one moment inside an action.","definitionCN":"把某一时刻定位在动作中间。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real running root, the real path and lesson senses, and the real time-span grammar.","cn":"正常联想用真实的奔跑词根、路径与课业的真实义项，以及真实的时段语法。"},"normal":[{"en":"A course is a run, and a run has length, so the phrase measures a span.","cn":"进程是一次奔跑，奔跑有长度，所以这个短语量的是时段。"},{"en":"The same noun also gives direction and a series of lessons.","cn":"同一名词还给出方向与一系列课业。"},{"en":"With events in the plural it means as matters unfold.","cn":"与复数的世事连用，意为随事态展开。"},{"en":"It suits change better than a bare time preposition.","cn":"它比光秃秃的时间介词更适合描述变化。"},{"en":"The ship's direction is not what the phrase marks.","cn":"船行的方向并不是这个短语所标的东西。"}],"abstract":[{"en":"Like a river seen from source to mouth: the water is always the same, the banks keep changing.","cn":"像从源头看到河口的整条河：水是同一股，两岸不断变化。"},{"en":"Like the middle pages of a book, where the story happens between opening and end.","cn":"像书的中间几页，故事在开头与结尾之间展开。"},{"en":"Like a season rather than a date: a stretch with weather inside it.","cn":"像一个季节而非一个日期：一段里面装着天气的日子。"}]},"examples":[{"en":"Several errors were found in the course of the inspection.","cn":"检查过程中发现了若干错误。"},{"en":"The site changed hands twice in the course of a year.","cn":"该场地在一年之内两次易主。"},{"en":"Attitudes to the practice shifted in the course of the century.","cn":"对这种做法的态度在这一百年间发生了变化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 则 科斯 奥夫」——从上游到下游的一整条河：在……过程中","word":"in the course of"},"root":"核心名词意为进程，来自拉丁语 cursus「奔跑、行程」，出自动词 currere「跑」；该短语为近代定型，首见年代不确定。","sensesIntro":{"en":"Eight senses split by what fills the span: a period, a developing event, unfolding events, a contrast with plain during, legal proceedings, history, a short unit, and the exclusion of a ship's route.","cn":"八个义项按填入时段的内容区分：时段、展开中的事件、事态、与单个时间介词的对照、法律程序、历史、短时间单位，以及排除航向。"},"semanticMap":{"core":{"en":"CORE IMAGE: a river winding from source to mouth, the same water passing banks that keep changing.","cn":"核心意象：一条河从源头蜿蜒到河口，同一股水流过不断变化的岸。"},"chain":["RUN","PASSAGE","PATH","PROGRESS","TIME SPAN","PROCEEDING"],"branches":[{"senses":"01 · 07","en":"THE SPAN: a decade, a morning or a century supplies the length that contains the event.","cn":"时段：十年、一个上午或一个世纪提供容纳事件的长度。"},{"senses":"02 · 03","en":"THE PROGRESS: an event or an open series of events carries the action along its stages.","cn":"进程：一个事件或开放的事态序列把动作带到各个阶段。"},{"senses":"04","en":"THE CONTRAST: the noun adds movement that a plain time preposition lacks.","cn":"对照：名词带来的动感是单个时间介词所没有的。"},{"senses":"05","en":"THE PROCEEDING: a case or a hearing is a formal run of steps.","cn":"程序：案件或听证是一连串正式的步骤。"},{"senses":"06 · 08","en":"THE SCALE AND THE LIMIT: history stretches the span wide, while a ship's route is excluded.","cn":"尺度与边界：历史把时段拉得很宽，而船只路线被排除。"}]},"affixes":{"intro":{"en":"The phrase rests on a Latin noun of running, so every use keeps a trace of movement through time.","cn":"这个短语建在一个表奔跑的拉丁语名词上，因此每种用法都留着随时间推移的动感。"},"latinIntro":{"en":"The Latin verb is currere, to run, and its noun cursus, a running or a passage; English added the lesson sense later.","cn":"拉丁语动词是 currere「跑」，名词 cursus 意为奔跑、行程；英语后来加了课业义。"},"items":[{"word":"currere","structure":"Latin verb","meaning":"to run","meaningCN":"跑；奔流","example":"The verb supplies every member of this family.","exampleCN":"这个词提供了这一族所有成员。"},{"word":"cursus","structure":"Latin noun, fourth declension","meaning":"a running; a passage","meaningCN":"奔跑；行程","example":"The noun gives length and direction at once.","exampleCN":"这个名词同时给出长度与方向。"},{"word":"course","structure":"English noun from French","meaning":"progress; route; programme","meaningCN":"进程；路线；课程","example":"English holds three senses in one form.","exampleCN":"英语用一个形式兼指三种意思。"},{"word":"current","structure":"currere through French","meaning":"flowing; the present","meaningCN":"流动的；当前的","example":"The participle sense survives in water and in time.","exampleCN":"分词义既留在水里，也留在时间上。"},{"word":"currency","structure":"Latin currens","meaning":"money in circulation","meaningCN":"流通货币","example":"The idea of circulation keeps the running image.","exampleCN":"流通的观念保留了奔跑意象。"},{"word":"curriculum","structure":"Latin curriculum","meaning":"a course of study","meaningCN":"课程体系","example":"The Latin noun meant a running track, then a course.","exampleCN":"拉丁名词本指跑道，后指课程。"},{"word":"in due course","structure":"fixed adverbial phrase","meaning":"at the proper time","meaningCN":"在适当时候","example":"The phrase drops the complement and keeps the timing.","exampleCN":"这个短语省掉补语，只留时机。"},{"word":"in the course of","structure":"preposition + noun + preposition","meaning":"during","meaningCN":"在……期间","example":"The frame is standard in narrative and legal prose.","exampleCN":"这个框架在叙事与法律文字中是标准用法。"}],"latinEntries":[{"word":"currere","structure":"currere, cucurri, cursum (verb, third conjugation)","meaning":"to run","meaningCN":"跑"},{"word":"cursus","structure":"cursus, -us (noun, fourth declension)","meaning":"a running; a passage","meaningCN":"奔跑；行程"},{"word":"curriculum","structure":"curriculum, -i (noun, second declension)","meaning":"a race course; a course of study","meaningCN":"跑道；课程"}],"derivatives":[{"word":"course","pos":"n.","zh":"进程；课程；航向"},{"word":"current","pos":"adj./n.","zh":"当前的；水流"},{"word":"currently","pos":"adv.","zh":"目前"},{"word":"currency","pos":"n.","zh":"货币"},{"word":"curriculum","pos":"n.","zh":"课程体系"}]}},{"word":"in the process of","ipa_uk":"/ɪn ðə ˈprəʊses ɒv/","ipa_us":"/ɪn ðə ˈprɑːses ɑːv/","definition_zh":"在……的过程中；正在……（强调动作尚未完成，仍在进行）","definition_en":"while something is being done and is not yet finished; during a series of operations","core_image":"面包在烤炉里，表皮已经定形，内里还没有熟透","scene":"窑工不停添柴，砖坯在火里慢慢由青转红，还没到出窑的时候。The tiles were still hardening in the process of firing.","sceneCN":"这里取「正在……的过程中」（第 1 个义项：动作尚未完成）；句意为瓦片在烧制过程中仍在硬化。","pos":[{"tag":"prep. phr.","zh":"介词短语：在……的过程中；正在……"}],"collocations":[{"phrase":"in the process of development","zh":"在开发过程中"},{"phrase":"in the process of change","zh":"在变化之中"},{"phrase":"in the process of being built","zh":"正在建造之中"},{"phrase":"in the process of learning","zh":"在学习过程中"},{"phrase":"in the process of negotiation","zh":"在谈判过程中"},{"phrase":"in the process of construction","zh":"在施工过程中"}],"forms":[{"label":"原形","form":"in the process of"},{"label":"被动进行形式","form":"in the process of being done"},{"label":"名词化","form":"the process of"},{"label":"北美简式","form":"in process of"}],"derivatives":[{"word":"process","pos":"n./v.","zh":"过程；加工；处理"},{"word":"proceed","pos":"v.","zh":"继续进行；前进"},{"word":"procedure","pos":"n.","zh":"程序；手续"},{"word":"procedural","pos":"adj.","zh":"程序性的"},{"word":"proceedings","pos":"n.","zh":"诉讼程序；会议记录"},{"word":"procession","pos":"n.","zh":"行列；队伍"}],"senses":[{"no":"01","title":"Work still under way","titleCN":"进行义：动作尚未完成","definition":"used to say that something is being done and has not yet reached its end","definitionCN":"表示某事正在被做、尚未到达终点","example":"The road is in the process of being widened.","exampleCN":"这条路正在拓宽之中。","why":"Process is a forward course, and the phrase locates the action inside that course rather than at its end.","whyCN":"过程是一段向前的行程，这个短语把动作放在行程之内，而不是终点。"},{"no":"02","title":"Before a gerund","titleCN":"动名词义：正在做某事","definition":"followed by a gerund, it states the activity that the subject is currently carrying out","definitionCN":"后接动名词，说明主语当前正在从事的活动","example":"She is in the process of writing her report.","exampleCN":"她正在写报告。","why":"The gerund names the very activity whose middle the phrase points to.","whyCN":"动名词命名的正是短语所指的处于中段的活动。"},{"no":"03","title":"Something incidental","titleCN":"附带义：在此过程中顺带发生","definition":"used before a noun of action to say that something else happens along the way","definitionCN":"用在表动作的名词前，表示另有一事在这个过程中发生","example":"The old roof leaked in the process of repair.","exampleCN":"屋顶在修理过程中漏了。","why":"A process has side effects as well as steps, so the phrase can carry what happened meanwhile.","whyCN":"过程除步骤之外还有副作用，因此这个短语也能承载其间发生的事。"},{"no":"04","title":"Unlike in the course of","titleCN":"辨义：强调进行而非时段","definition":"it stresses that work is under way, while the course phrase stresses the span in which events occur","definitionCN":"它强调工作正在进行，而过程一词的短语强调事件发生的时段","example":"In the process of translation, two lines were lost.","exampleCN":"翻译过程中丢了两行。","why":"Process names a series of operations with a direction, so the emphasis falls on the work, not on the calendar.","whyCN":"过程指有方向的一连串操作，因此重心落在工作，而不在日历。"},{"no":"05","title":"Industrial processing","titleCN":"工业义：加工处理的具体过程","definition":"in manufacturing and chemistry it refers to the treatments a material undergoes","definitionCN":"在制造与化学语境中，指材料所经历的各道处理","example":"The ore is crushed in the process of extraction.","exampleCN":"矿石在提取过程中被粉碎。","why":"The industrial sense is the noun's most concrete one, and the phrase borrows its physicality.","whyCN":"工业义是这个名词最具体的一义，短语借用了它的实体感。"},{"no":"06","title":"A chain of reasoning","titleCN":"推理义：在推演过程中","definition":"with reasoning or calculation it marks the steps through which a conclusion is reached","definitionCN":"与推理或计算连用时，标出得出结论所经过的步骤","example":"Two assumptions were dropped in the process of reasoning.","exampleCN":"推理过程中舍弃了两个假设。","why":"Thought also runs through steps, so the same frame works for argument as for manufacture.","whyCN":"思维同样要经过步骤，因此同一框架既适用于论证，也适用于制造。"},{"no":"07","title":"A change of course midway","titleCN":"转折义：中途发生变化","definition":"it can mark a point at which a plan or a design alters while still unfinished","definitionCN":"可标出计划或设计在尚未完成时发生改变的那一刻","example":"The design changed twice in the process of approval.","exampleCN":"审批过程中设计改了两次。","why":"Because the end has not arrived, there is still room for revision, and the phrase points to that room.","whyCN":"因为终点未到，仍有修改余地，这个短语指的就是那段余地。"},{"no":"08","title":"Not the rulebook","titleCN":"辨义：不指成文程序","definition":"the phrase describes work in motion, while the related noun for rules is a different word","definitionCN":"这个短语描述正在进行的工作，而表规则的相关名词是另一个词","example":"In the process of appeal marks time, not the written code that governs it.","exampleCN":"上诉过程中一语标的是时间，不是管束它的成文规程。","why":"English keeps process for what happens and procedure for the rules, a split worth holding onto.","whyCN":"英语用前者指发生的事、后者指规则，这一分工值得记住。"}],"etymology":{"intro":{"en":"Process comes from Latin processus, a going forward, from procedere, to go forward, built on cedere, to go or yield. The Latin chain is secure; the fixed phrase is modern.","cn":"过程一词来自拉丁语 processus「前行、进程」，出自 procedere「向前走」，其下是 cedere「行、让」。拉丁语链条清楚；固定短语属近代。"},"items":[{"era":"LATIN CEDERE","en":"Cedere meant to go, to withdraw or to yield, and it feeds many English verbs of movement.","cn":"cedere 意为行走、退让、屈服，构成许多英语表运动的动词。"},{"era":"PROCEDERE","en":"The prefix for forward turned going into going ahead, and English took proceed from it.","cn":"表向前的前缀把行走变成前行，英语由此借入 proceed。"},{"era":"PROCESSUS","en":"The noun named a forward course and later a series of operations performed in order.","cn":"这个名词本指向前的行程，后来指按次序进行的一连串操作。"},{"era":"INDUSTRIAL SENSE","en":"Manufacturing gave the noun its concrete sense of treating raw material step by step; the dating is approximate.","cn":"制造业赋予这个名词逐道处理原料的具体义，年代为约数。"},{"era":"THE FIXED PHRASE","en":"The progressive frame with this preposition and of becomes common in modern technical prose.","cn":"这个介词加 of 的进行框架在近代技术文字中通行。"}]},"similar":{"note":{"en":"The first group looks close in form or meaning but differs in grammar or force; the second group also places an action inside time.","cn":"第一组外形或意义接近，但语法或力度不同；第二组同样把动作放进时间之中。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in process of","ipa":"/ɪn ˈprəʊses əv/","tag":"short variant","definition":"North American usage often drops the article before a gerund.","definitionCN":"北美用法在动名词前常省略冠词。"},{"word":"in progress","ipa":"/ɪn ˈprəʊɡres/","tag":"state, no object","definition":"It describes work under way without taking a complement.","definitionCN":"描述工作进行中，不接补语。"},{"word":"under way","ipa":"/ˈʌndə weɪ/","tag":"idiomatic state","definition":"It says an activity has started and is moving forward.","definitionCN":"表示活动已启动并在推进。"},{"word":"on the way","ipa":"/ɒn ðə weɪ/","tag":"travelling","definition":"It refers to moving or arriving, not to work in progress.","definitionCN":"指在路途上或即将到达，而非工作进程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"in the middle of","ipa":"/ɪn ðə ˈmɪdl əv/","tag":"at a point","definition":"It locates one moment inside an activity.","definitionCN":"把某一时刻定位在活动中间。"},{"word":"halfway through","ipa":"/ˈhɑːfweɪ θruː/","tag":"position in sequence","definition":"It marks the midpoint of a counted series.","definitionCN":"标出可数序列的中点。"},{"word":"while doing","ipa":"/waɪl ˈduːɪŋ/","tag":"simultaneous action","definition":"It joins two actions of the same subject.","definitionCN":"连接同一主体的两个动作。"},{"word":"during","ipa":"/ˈdjʊərɪŋ/","tag":"plain period","definition":"It gives a period without any sense of work under way.","definitionCN":"只给时段，不含正在进行之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real going-forward root, the real industrial sense and the real split between process and procedure.","cn":"正常联想用真实的向前词根、真实的工业义，以及过程与程序的真实分工。"},"normal":[{"en":"A process goes forward: the phrase puts the action on that road, not at its end.","cn":"过程向前走：这个短语把动作放在路上，而不在终点。"},{"en":"A gerund follows, because the activity itself is what is under way.","cn":"后面接动名词，因为正在进行的正是这个活动。"},{"en":"Manufacturing gave the noun its concrete, step-by-step sense.","cn":"制造业给了这个名词具体的、逐道的义。"},{"en":"The related noun for rules is a different word and must not be swapped in.","cn":"表规则的相关名词是另一个词，不能混用。"},{"en":"Because the work is unfinished, revision is still possible.","cn":"因为工作未完，修改仍有可能。"}],"abstract":[{"en":"Like bread in an oven: the crust has set, but the inside is not yet done.","cn":"像炉里的面包：皮已定形，里面还没熟。"},{"en":"Like a relay race in which each runner hands over the baton before the finish.","cn":"像接力赛，每一棒在终点前交出接力棒。"},{"en":"Like a page half written, with lines still open to correction.","cn":"像写到一半的稿页，字句仍可改动。"}]},"examples":[{"en":"The bridge is in the process of being repaired.","cn":"这座桥正在维修之中。"},{"en":"The company is in the process of moving its offices.","cn":"这家公司正在搬迁办公室。"},{"en":"New rules are in the process of being drafted.","cn":"新规则正在起草之中。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 则 普若塞斯 奥夫」——炉里的面包皮定了、心还没熟：正在进行","word":"in the process of"},"root":"核心名词意为过程，来自拉丁语 processus「前行、进程」，出自 procedere「向前走」，其词根 cedere 意为行、让；该短语为近代定型，首见年代不确定。","sensesIntro":{"en":"Eight senses separate work under way, the gerund frame, incidental events, the contrast with the course phrase, industrial processing, reasoning, a mid-course change and the exclusion of written procedure.","cn":"八个义项区分：进行中的工作、动名词框架、附带发生的事、与过程时段说的对照、工业加工、推理、中途变化，以及排除成文程序。"},"semanticMap":{"core":{"en":"CORE IMAGE: bread in an oven, the crust firm but the inside still soft, the baking unfinished.","cn":"核心意象：炉中的面包，外皮已硬，内里仍软，烘烤尚未完成。"},"chain":["GO FORWARD","COURSE","SERIES OF STEPS","OPERATION","UNFINISHED STATE","TURNING POINT"],"branches":[{"senses":"01 · 02","en":"THE WORK: an activity is caught in the middle, still running towards its end.","cn":"工作：活动被捕捉在中段，仍朝着终点运行。"},{"senses":"03 · 04","en":"THE SIDE EFFECT: something else happens along the way, and the emphasis stays on the work.","cn":"副作用：另有事情在途中发生，重心仍在工作本身。"},{"senses":"05","en":"THE MATERIAL: ore and chemicals undergo ordered treatment in manufacture.","cn":"材料：矿石与化学品在制造中经受有序处理。"},{"senses":"06","en":"THE ARGUMENT: reasoning also runs through steps towards a conclusion.","cn":"论证：推理同样经过步骤走向结论。"},{"senses":"07 · 08","en":"THE REVISION AND THE LIMIT: an unfinished plan can still change, and written rules are excluded.","cn":"修改与边界：未完成的计划仍可改变，成文规则被排除。"}]},"affixes":{"intro":{"en":"The phrase is built on a Latin noun of going forward, so it always implies motion towards an end that has not yet arrived.","cn":"这个短语建在一个表向前的拉丁语名词上，因此总含有朝尚未抵达的终点运动之意。"},"latinIntro":{"en":"The base verb is cedere, to go or yield, with the prefixed procedere, to go forward, and the noun processus.","cn":"基础动词是 cedere「行走、退让」，加前缀的 procedere 意为向前走，名词为 processus。"},"items":[{"word":"cedere","structure":"Latin verb","meaning":"to go; to yield","meaningCN":"行走；退让","example":"The verb underlies movement and concession alike.","exampleCN":"这个词既构成运动，也构成让步。"},{"word":"procedere","structure":"pro- + cedere","meaning":"to go forward","meaningCN":"向前走","example":"The prefix turns going into advance.","exampleCN":"前缀把行走变成推进。"},{"word":"processus","structure":"Latin noun, fourth declension","meaning":"a going forward; a course","meaningCN":"前行；进程","example":"The noun gives the frame its direction.","exampleCN":"这个名词给框架以方向。"},{"word":"process","structure":"English noun and verb","meaning":"a series of steps; to treat","meaningCN":"过程；加工","example":"English uses it for both the sequence and the action.","exampleCN":"英语用它兼指序列与动作。"},{"word":"proceed","structure":"procedere through French","meaning":"to continue; to go on","meaningCN":"继续进行","example":"The verb keeps the sense of moving ahead.","exampleCN":"这个动词保留向前推进的意思。"},{"word":"procedure","structure":"procedere + -ure","meaning":"an established way of doing","meaningCN":"程序；手续","example":"The suffix makes a noun of the manner, not the motion.","exampleCN":"后缀造出表方式而非运动的名词。"},{"word":"proceedings","structure":"proceed + -ings","meaning":"formal steps in a case","meaningCN":"诉讼程序；记录","example":"The plural names the recorded steps of an inquiry.","exampleCN":"复数指调查的各个记录步骤。"},{"word":"procession","structure":"procedere + -ion","meaning":"an ordered line of movers","meaningCN":"行列；队伍","example":"The noun turns forward movement into a visible line.","exampleCN":"这个名词把前行变成可见的队列。"},{"word":"in the process of","structure":"preposition + noun + preposition","meaning":"while being done","meaningCN":"正在……的过程中","example":"The frame is standard in technical description.","exampleCN":"这个框架在技术说明中是标准用法。"}],"latinEntries":[{"word":"cedere","structure":"cedere, cessi, cessum (verb, third conjugation)","meaning":"to go; to yield","meaningCN":"行走；退让"},{"word":"procedere","structure":"procedere, processi, processum (verb)","meaning":"to go forward","meaningCN":"向前走"},{"word":"processus","structure":"processus, -us (noun, fourth declension)","meaning":"a going forward; a course","meaningCN":"前行；进程"}],"derivatives":[{"word":"process","pos":"n./v.","zh":"过程；加工"},{"word":"proceed","pos":"v.","zh":"继续进行"},{"word":"procedure","pos":"n.","zh":"程序"},{"word":"procedural","pos":"adj.","zh":"程序性的"},{"word":"proceedings","pos":"n.","zh":"诉讼程序"},{"word":"procession","pos":"n.","zh":"行列"}]}},{"word":"on the basis of","ipa_uk":"/ɒn ðə ˈbeɪsɪs ɒv/","ipa_us":"/ɑːn ðə ˈbeɪsɪs ɑːv/","definition_zh":"基于、根据；以……为基础或依据（后接名词，说明判断、计算或行为的根据）","definition_en":"using something as the foundation, standard or evidence for a judgement, calculation or action","core_image":"一台天平，砝码先摆好，指针才停在中线","scene":"招聘委员会先定好评分条目，再逐份核对简历，最后按总分排序。Candidates were ranked on the basis of scored interviews.","sceneCN":"这里取「根据、以……为依据」（第 3 个义项：以评分结果作为排序依据）；句意为应聘者按面试得分排序。","pos":[{"tag":"prep. phr.","zh":"介词短语：基于；根据；以……为基础"}],"collocations":[{"phrase":"on the basis of evidence","zh":"根据证据"},{"phrase":"on the basis of merit","zh":"按能力与功绩"},{"phrase":"on the basis of cost","zh":"根据成本"},{"phrase":"on the basis of equality","zh":"在平等基础上"},{"phrase":"on the basis of a sample","zh":"根据样本"},{"phrase":"on the basis of the data","zh":"根据数据"}],"forms":[{"label":"原形","form":"on the basis of"},{"label":"比例变体","form":"on a regular basis"},{"label":"否定形式","form":"not on the basis of"},{"label":"名词化","form":"the basis for"}],"derivatives":[{"word":"base","pos":"n./v.","zh":"底部；基础；以……为基础"},{"word":"basic","pos":"adj.","zh":"基本的；基础的"},{"word":"basically","pos":"adv.","zh":"基本上；大体上"},{"word":"basal","pos":"adj.","zh":"基部的；基础的"},{"word":"basement","pos":"n.","zh":"地下室"}],"senses":[{"no":"01","title":"Grounds for a decision","titleCN":"决定依据义：判断所凭的基础","definition":"used before a noun to name the ground on which a decision or judgement rests","definitionCN":"用在名词前，指出决定或判断所依托的依据","example":"The decision was made on the basis of the final report.","exampleCN":"这个决定是根据最终报告作出的。","why":"A basis is a pedestal, and a decision needs something to stand on before it can be announced.","whyCN":"基础本指底座，决定也要有立足之处才能宣布。"},{"no":"02","title":"The base of a calculation","titleCN":"计算基础义：数额所按的口径","definition":"used before a noun to name the figure, rate or unit that a calculation starts from","definitionCN":"用在名词前，指出计算所起算的数字、比率或单位","example":"Fees are set on the basis of floor area.","exampleCN":"费用按建筑面积计算。","why":"A calculation must begin somewhere, and the phrase marks the starting surface rather than the result.","whyCN":"计算总得从某处开始，这个短语标出起算的平面，而非结果。"},{"no":"03","title":"Grounds in evidence","titleCN":"证据义：以证据为根据","definition":"used before names of records or findings to say what supports an assertion or a charge","definitionCN":"用在记录或结果的名词前，说明某项主张或指控有何支撑","example":"He was charged on the basis of recorded calls.","exampleCN":"他是根据通话录音被起诉的。","why":"Evidence is the floor a claim stands on, so the phrase turns proof into a base.","whyCN":"证据是主张所立的地面，因此这个短语把证明变成基础。"},{"no":"04","title":"A basis for relations","titleCN":"关系基础义：平等或互惠的立足点","definition":"with nouns such as equality or trust it names the condition on which a relationship is built","definitionCN":"与平等、信任一类名词连用，指出关系所建立的条件","example":"The two firms cooperate on the basis of equal shares.","exampleCN":"两家公司以均分为基础合作。","why":"A basis can also be a footing between parties, not only a ground under a claim.","whyCN":"基础也可以是各方之间的立足点，而不只是主张下面的地面。"},{"no":"05","title":"Unlike the participial form","titleCN":"语法边界：与分词形式的分工","definition":"it forms an adverbial phrase, while the participial form modifies a noun directly","definitionCN":"它构成状语短语，而分词形式直接修饰名词","example":"On the basis of the raw scores, the ranking was fixed.","exampleCN":"名次是依据原始得分定下的。","why":"The prepositional frame belongs to the clause, and the participle belongs to the noun, so the two cannot swap places.","whyCN":"介词框架属于句子，分词属于名词，两者不能互换位置。"},{"no":"06","title":"Grounds versus reasons","titleCN":"辨义：依据不同于理由","definition":"it names the foundation or evidence, while the similar phrase with grounds names the reasons offered","definitionCN":"它点出基础或证据，而形近短语点出所提出的理由","example":"Leave was granted on the basis of medical certificates.","exampleCN":"准假是依据医疗证明作出的。","why":"A certificate is a foundation to stand on; a reason is an explanation offered, which is a slightly different move.","whyCN":"证明是可站立的基础；理由是给出的解释，两者的动作略有不同。"},{"no":"07","title":"A repeated rate","titleCN":"比例义：按某一频次或比率","definition":"in the pattern with a rate word it states how often or in what proportion something is done","definitionCN":"在与比率词搭配的句式中，说明做某事的频次或比例","example":"Staff are reviewed on the basis of output, twice a year.","exampleCN":"员工按产出接受考评，每年两次。","why":"The same noun supplies the footing for a regular measure, which is why the phrase extends to rates.","whyCN":"同一名词也为定期衡量的口径提供立足点，因此这个短语可扩展到比率。"},{"no":"08","title":"Not the physical bottom","titleCN":"辨义：不表具体底部或基地","definition":"in this phrase the noun means an abstract foundation, not a physical base or a military site","definitionCN":"在这个短语里名词指抽象基础，而非具体底座或军事基地","example":"The argument stands on the basis of two accepted facts.","exampleCN":"这个论证建立在两条公认事实之上。","why":"English borrowed the noun twice, once for a concrete base and once for an abstract foundation.","whyCN":"英语两次借入这个名词，一次指具体底座，一次指抽象基础。"}],"etymology":{"intro":{"en":"Basis is Latin for a base or pedestal, itself borrowed from Greek basis, a step or a stand. The direct source is clear; the deeper root of the Greek word is debated.","cn":"basis 在拉丁语中意为基座，本身借自希腊语 basis「台阶、立足处」。直接来源清楚；这个希腊词更早的词根仍有争议。"},"items":[{"era":"GREEK BASIS","en":"Greek basis named a step or the thing one stands on, and it passed into Latin unchanged in form.","cn":"希腊语 basis 指台阶或所立之物，其形式原样进入拉丁语。"},{"era":"DEEPER ROOT DISPUTED","en":"The further origin of the Greek noun is usually connected with a verb for stepping, but the source is uncertain.","cn":"这个希腊名词的更早来源一般与表迈步的动词相联系，但来源不确定。"},{"era":"LATIN BASIS","en":"Latin used basis for the foot of a column and, figuratively, for any foundation.","cn":"拉丁语用 basis 指柱脚，并引申为一切基础。"},{"era":"TWO ENGLISH WORDS","en":"English borrowed base through French for the physical bottom and basis directly for the abstract support.","cn":"英语经法语借入 base 指具体底部，又直接借入 basis 指抽象支撑。"},{"era":"THE FIXED PHRASE","en":"The frame with this preposition and of settles in scholarly and legal prose; first dates are approximate.","cn":"这个介词加 of 的框架在学术与法律文字中定型，首见年代为约数。"}]},"similar":{"note":{"en":"The first group also states grounds but differs in register or takes a clause; the second group names foundation, source or premise.","cn":"第一组同样表依据，但语体不同或后接从句；第二组点出基础、来源或前提。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"on the grounds of","ipa":"/ɒn ðə ˈɡraʊndz əv/","tag":"reasons offered","definition":"It gives the reasons advanced for an official decision.","definitionCN":"它给出为某项正式决定提出的理由。"},{"word":"on the basis that","ipa":"/ɒn ðə ˈbeɪsɪs ðæt/","tag":"clause variant","definition":"It introduces a premise with a full clause.","definitionCN":"它引出带完整从句的前提。"},{"word":"on account of","ipa":"/ɒn əˈkaʊnt əv/","tag":"because of","definition":"It gives a cause, not a foundation for a judgement.","definitionCN":"它给出原因，而非判断所依据的基础。"},{"word":"by reference to","ipa":"/baɪ ˈrefrəns tuː/","tag":"formal standard","definition":"It names the standard consulted, in legal style.","definitionCN":"以法律文体点出所参照的标准。"}]},{"heading":"NEAR MEANING","entries":[{"word":"based on","ipa":"/ˈbeɪst ɒn/","tag":"participial","definition":"It modifies a noun instead of framing an adverbial.","definitionCN":"它修饰名词，而非构成状语。"},{"word":"according to","ipa":"/əˈkɔːdɪŋ tuː/","tag":"source of a claim","definition":"It attributes a statement to a source.","definitionCN":"把说法归于某个来源。"},{"word":"grounded in","ipa":"/ˈɡraʊndɪd ɪn/","tag":"firm footing","definition":"It stresses that a claim has a firm root.","definitionCN":"强调主张有牢固根基。"},{"word":"given","ipa":"/ˈɡɪvn/","tag":"premise marker","definition":"It means considering a stated fact, in compressed prose.","definitionCN":"压缩文风中表示考虑到某既定事实。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real pedestal image, the Greek origin, the split between base and basis, and the real grammar of adverb and participle.","cn":"正常联想用真实的基座意象、希腊语来源、具体底部与抽象基础的分工，以及状语与分词的真实语法。"},"normal":[{"en":"A basis is a pedestal: a claim must stand on something before it can be made.","cn":"基础是基座：主张先有立足处才能提出。"},{"en":"A calculation needs a starting surface, and the phrase names that surface.","cn":"计算需要起算平面，这个短语就点出那个平面。"},{"en":"Evidence is the floor under a charge, so the same frame fits proof.","cn":"证据是指控所立的地面，因此同一框架适用于证明。"},{"en":"The physical bottom and the abstract support are two separate borrowings.","cn":"具体底部与抽象支撑是两次独立的借入。"},{"en":"A participle attaches to a noun, while this frame attaches to the clause.","cn":"分词挂在名词上，而这个框架挂在句子上。"}],"abstract":[{"en":"Like a pair of scales levelled before the goods are put in.","cn":"像称货之前先把天平调平。"},{"en":"Like a plinth under a statue: invisible, yet everything depends on it.","cn":"像雕像下的底座：看不见，却全靠它。"},{"en":"Like the first line of a ledger, which fixes every figure below it.","cn":"像账本的第一行，下面每个数字都由它定基。"}]},"examples":[{"en":"Selection is made on the basis of written tests.","cn":"选拔依据笔试成绩进行。"},{"en":"The two sides agreed on the basis of mutual benefit.","cn":"双方在互利的基础上达成了协议。"},{"en":"Pay is calculated on the basis of hours worked.","cn":"报酬按工作小时数计算。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「昂 则 贝西斯 奥夫」——砝码先摆好，指针才停中线：基于、根据","word":"on the basis of"},"root":"核心名词意为基础，直接借自拉丁语 basis「基座」，更早出自希腊语 basis「台阶、立足处」；其更深词源一般认为与迈步有关，但来源不确定。该短语为近代学术与法律文字定型，首见年代不确定。","sensesIntro":{"en":"Eight senses organise the grounds of a decision, the base of a calculation, the support of evidence, the footing of a relationship, the grammatical boundary, the difference from reasons, the rate pattern and the exclusion of the physical bottom.","cn":"八个义项区分：决定依据、计算口径、证据支撑、关系立足点、语法边界、与理由的差别、频次比率，以及排除具体底部。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pair of scales levelled by weights before anything is weighed.","cn":"核心意象：一台天平在称物之前先由砝码摆平。"},"chain":["STEP","STAND","FOUNDATION","STANDARD","EVIDENCE","CALCULATION"],"branches":[{"senses":"01 · 04","en":"THE GROUND: a decision or a partnership stands on something before it holds.","cn":"依据：决定或合作先有立足处才成立。"},{"senses":"02 · 07","en":"THE MEASURE: a unit or a rate supplies the surface that figures are counted from.","cn":"口径：单位或比率提供数字起算的平面。"},{"senses":"03","en":"THE EVIDENCE: records and findings become the floor under a charge.","cn":"证据：记录与结果成为指控所立的地面。"},{"senses":"05","en":"THE GRAMMAR: an adverbial frame and a participle belong to different hosts.","cn":"语法：状语框架与分词挂在不同的宿主上。"},{"senses":"06 · 08","en":"THE CONTRAST AND THE LIMIT: reasons are not foundations, and no physical base is meant.","cn":"对照与边界：理由不等于基础，也不指具体底座。"}]},"affixes":{"intro":{"en":"The phrase stands on a noun borrowed twice into English, once as a concrete bottom and once as an abstract support.","cn":"这个短语建在一个两次借入英语的名词上，一次指具体底部，一次指抽象支撑。"},"latinIntro":{"en":"Latin basis, from Greek basis, meant a step or a pedestal; English base came through French, while basis was taken directly.","cn":"拉丁语 basis 源自希腊语 basis，意为台阶或基座；英语 base 经法语而来，basis 则直接借入。"},"items":[{"word":"basis","structure":"Greek and Latin noun, third declension","meaning":"a step; a pedestal","meaningCN":"台阶；基座","example":"The word names what a thing stands on.","exampleCN":"这个词指事物所立之物。"},{"word":"base","structure":"French and Latin","meaning":"the bottom; a centre","meaningCN":"底部；基地","example":"English uses it for the physical and the military.","exampleCN":"英语用它指具体底部与军事基地。"},{"word":"basic","structure":"base + -ic","meaning":"forming the foundation","meaningCN":"基本的","example":"The adjective marks what everything else depends on.","exampleCN":"形容词标出其余一切所依赖的东西。"},{"word":"basically","structure":"basic + -ally","meaning":"in the main","meaningCN":"基本上","example":"The adverb reduces a matter to its foundation.","exampleCN":"副词把事情还原到基础层面。"},{"word":"basal","structure":"base + -al","meaning":"of the bottom layer","meaningCN":"基部的","example":"The technical adjective stays close to the physical sense.","exampleCN":"这个技术形容词贴近具体底部的义。"},{"word":"basement","structure":"base + -ment","meaning":"the lower floor","meaningCN":"地下室","example":"The noun keeps the concrete sense of the base.","exampleCN":"这个名词保留基础的具体义。"},{"word":"on a regular basis","structure":"preposition + article + adjective + noun","meaning":"regularly","meaningCN":"定期地","example":"The rate pattern drops of and keeps the footing sense.","exampleCN":"比率句式省去该介词，保留立足点义。"},{"word":"on the basis of","structure":"preposition + noun + preposition","meaning":"founded on","meaningCN":"基于；根据","example":"The frame is standard in academic and legal writing.","exampleCN":"这个框架在学术与法律文字中是标准用法。"}],"latinEntries":[{"word":"basis","structure":"basis, -is (noun, third declension, from Greek)","meaning":"a step; a pedestal; a base","meaningCN":"台阶；基座；基础"}],"derivatives":[{"word":"base","pos":"n./v.","zh":"底部；以……为基础"},{"word":"basic","pos":"adj.","zh":"基本的"},{"word":"basically","pos":"adv.","zh":"基本上"},{"word":"basal","pos":"adj.","zh":"基部的"},{"word":"basement","pos":"n.","zh":"地下室"}]}},{"word":"with regard to","ipa_uk":"/wɪð rɪˈɡɑːd tuː/","ipa_us":"/wɪð rɪˈɡɑːrd tuː/","definition_zh":"关于、就……而言；在……方面（正式用语，引出论述或处理的对象）","definition_en":"concerning; in connection with a particular subject or matter","core_image":"一束目光落在文件上某一栏，其余部分暂被搁在一旁","scene":"会议开到最后，主持人把散落的议题逐项归位，先点出需要表决的那一条。With regard to the budget, the committee asked for a second review.","sceneCN":"这里取「关于、就……而言」（第 1 个义项：正式引出论述对象）；句意为关于预算，委员会要求再审议一次。","pos":[{"tag":"prep. phr.","zh":"介词短语：关于；就……而言"}],"collocations":[{"phrase":"with regard to your letter","zh":"关于您的来信"},{"phrase":"with regard to the question","zh":"就这个问题而言"},{"phrase":"with regard to safety","zh":"在安全方面"},{"phrase":"with regard to costs","zh":"就成本而言"},{"phrase":"with regard to the above","zh":"关于上述内容"},{"phrase":"with regard to this matter","zh":"关于此事"}],"forms":[{"label":"原形","form":"with regard to"},{"label":"变体","form":"in regard to"},{"label":"变体","form":"as regards"},{"label":"带从句形式","form":"with regard to whether"}],"derivatives":[{"word":"regard","pos":"n./v.","zh":"注视；看待；关心"},{"word":"regarding","pos":"prep.","zh":"关于"},{"word":"regardless","pos":"adv.","zh":"不管怎样；不顾"},{"word":"disregard","pos":"v./n.","zh":"漠视；不理会"},{"word":"regards","pos":"n.","zh":"问候；致意"}],"senses":[{"no":"01","title":"A formal topic marker","titleCN":"话题义：正式引出论述对象","definition":"used at the start of a statement to name the matter that the statement deals with","definitionCN":"用在陈述开头，点出该陈述所要处理的事项","example":"With regard to the schedule, no change has been made.","exampleCN":"关于日程，目前没有任何变动。","why":"Regard began as a look, and looking at a matter is the first step in discussing it.","whyCN":"这个词本指注视，把目光落到一件事上，正是讨论它的第一步。"},{"no":"02","title":"The letter and the memo","titleCN":"公文义：书信与备忘录用语","definition":"in correspondence it opens a paragraph that answers or raises one specific point","definitionCN":"在书信往来中，用于开启答复或提出某一具体问题的段落","example":"With regard to your enquiry of the fifth, we reply as follows.","exampleCN":"关于您五日来函的询问，我方答复如下。","why":"Written office language needs a dignified opener, and this phrase supplies one without bluntness.","whyCN":"书面办公语言需要得体的起句，这个短语提供了不生硬的起句。"},{"no":"03","title":"Unlike the participle","titleCN":"语法边界：与现在分词形式不同","definition":"the phrase is a prepositional frame, while the participial form works as a preposition on its own","definitionCN":"这个短语是介词框架，而与之形近的分词形式本身就是一个介词","example":"With regard to the invoice, please see the attached note.","exampleCN":"关于发票，请见所附说明。","why":"A frame needs its noun after of, whereas the single participle takes its object directly.","whyCN":"框架要在介词后接名词，而单个分词直接带宾语。"},{"no":"04","title":"Register beside as regards","titleCN":"语域义：与另一变体的分工","definition":"the frame is neutral formal, while the shorter variant sounds older and more legal","definitionCN":"这个框架属中性正式，较短的变体显得更古旧、更偏法律","example":"With regard to staffing, the board will decide in June.","exampleCN":"关于人员配置，董事会将在六月决定。","why":"Both forms say the same thing, but one is plainly modern and the other carries a legal flavour.","whyCN":"两种形式意思相同，但一种明显现代，另一种带法律气味。"},{"no":"05","title":"The in-regard variant","titleCN":"变体义：介词换成另一介词的近义形式","definition":"a variant with a different preposition carries the same topic-marking function in formal prose","definitionCN":"换用另一个介词的变体，在正式文字中承担同样的话题标记功能","example":"With regard to the lease, the tenant raised three points.","exampleCN":"关于租约，租户提出了三点意见。","why":"Preposition choice here is a matter of idiom rather than meaning, so the two variants can replace each other.","whyCN":"这里介词的选择是习惯问题而非意义问题，因此两个变体可以互换。"},{"no":"06","title":"A stance on a matter","titleCN":"立场义：就某事表态","definition":"it can introduce the matter about which a person or body expresses an opinion or a concern","definitionCN":"可引出某人或某机构表达意见、关切所针对的事项","example":"The ministry was cautious with regard to the findings.","exampleCN":"该部对这些发现持谨慎态度。","why":"Once a matter is looked at, a judgement may follow, and the phrase can carry that stance as well.","whyCN":"一件事被注视之后可能引出判断，这个短语也能承载那种态度。"},{"no":"07","title":"Scope of a rule","titleCN":"适用范围义：条款所针对的对象","definition":"in regulations it identifies the persons or goods that a provision applies to","definitionCN":"在规章中，指出某项条款所适用的对象或货物","example":"With regard to imported goods, the tariff applies from July.","exampleCN":"关于进口货物，该关税自七月起适用。","why":"A rule must say what it looks at, and the phrase marks exactly that scope.","whyCN":"规则必须说明它看向什么，这个短语标的正是那个范围。"},{"no":"08","title":"Not the sense of esteem","titleCN":"辨义：不表尊敬或问候","definition":"although the noun can mean esteem, the phrase marks a topic and carries no flattery","definitionCN":"尽管这个名词可表尊敬，短语只标话题，不含恭维之意","example":"With regard to the witness, the phrase shows a topic, not respect.","exampleCN":"就证人一词而言，这个短语标的是话题，不是敬意。","why":"The esteem sense lives in other patterns, and mixing the two produces a unintended compliment.","whyCN":"尊敬义活在其他句式中，两者混用会意外变成恭维。"}],"etymology":{"intro":{"en":"Regard comes from Old French regarder, to look at, formed with the Latin prefix re- and a Germanic stem meaning to guard or watch. The Latin prefix is secure; the stem is reconstructed.","cn":"regard 来自古法语 regarder「注视」，由拉丁语前缀 re- 与表看守的日耳曼语词干构成。拉丁语前缀清楚；词干为重构形式。"},"items":[{"era":"GERMANIC GUARD","en":"The stem behind the French verb meant to watch or guard and is reconstructed rather than recorded.","cn":"法语动词背后的词干意为看守、警戒，属重构形式而非有记录的形式。"},{"era":"RE- AS A PREFIX","en":"The Latin prefix added a sense of back or again, so the verb pictured a repeated look.","cn":"拉丁语前缀加上回、再的意思，因此动词描绘的是一再投去的目光。"},{"era":"OLD FRENCH REGARDER","en":"The French verb meant to look at or to heed, and the noun named a look or attention.","cn":"法语动词意为注视、留意，其名词指目光或注意。"},{"era":"ESTEEM LATER","en":"Attention to a person's worth produced the sense of esteem, which is why the plural can mean greetings.","cn":"对人价值的关注产生尊敬义，因此复数形式可指问候。"},{"era":"THE FIXED PHRASE","en":"The topic frame belongs to modern official and academic prose; first dates are approximate.","cn":"这个话题框架属于近代公文与学术文字，首见年代为约数。"}]},"similar":{"note":{"en":"The first group marks a topic in a different form; the second group are plain prepositions of subject matter.","cn":"第一组以不同形式标出话题；第二组是朴素的关涉介词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"regarding","ipa":"/rɪˈɡɑːdɪŋ/","tag":"one-word preposition","definition":"The participle works alone and takes its object directly.","definitionCN":"分词单独作介词，直接带宾语。"},{"word":"as regards","ipa":"/æz rɪˈɡɑːdz/","tag":"older legal tone","definition":"The variant sounds dated and formal.","definitionCN":"这个变体显得古旧而正式。"},{"word":"in regard to","ipa":"/ɪn rɪˈɡɑːd tuː/","tag":"preposition variant","definition":"A different preposition carries the same topic function.","definitionCN":"换一个介词，承担同样的话题功能。"},{"word":"in relation to","ipa":"/ɪn rɪˈleɪʃn tuː/","tag":"relation, wider","definition":"It links two matters rather than merely naming one topic.","definitionCN":"它连接两件事，而不只是点出一个话题。"}]},{"heading":"NEAR MEANING","entries":[{"word":"concerning","ipa":"/kənˈsɜːnɪŋ/","tag":"formal about","definition":"A single word with the same formal subject marker.","definitionCN":"单个词，同样正式地点出主题。"},{"word":"about","ipa":"/əˈbaʊt/","tag":"everyday","definition":"The ordinary spoken equivalent with no official tone.","definitionCN":"日常口语的对应说法，没有公文语气。"},{"word":"as to","ipa":"/æz tuː/","tag":"neutral formal","definition":"It introduces a matter under discussion, often after a verb.","definitionCN":"引出讨论中的事项，常置于动词后。"},{"word":"on","ipa":"/ɒn/","tag":"very general","definition":"A bare preposition for the subject of a book or a talk.","definitionCN":"单个介词，指书或谈话的主题。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real look-root, the Germanic guard stem, the later esteem sense and the real preposition frame.","cn":"正常联想用真实的注视词根、日耳曼语看守词干、后来的尊敬义，以及真实的介词框架。"},"normal":[{"en":"To regard is to look, so the phrase first directs the reader's eyes to one matter.","cn":"看待就是看，因此这个短语先把读者的目光引到一件事上。"},{"en":"A look can harden into esteem, but the topic frame carries no praise.","cn":"注视会沉淀为尊敬，但话题框架不含褒扬。"},{"en":"One frame takes a noun after of; the participle takes its object alone.","cn":"一个框架在介词后接名词；分词则直接带宾语。"},{"en":"The shorter variants are older and more legal in flavour.","cn":"较短的变体更古旧，法律气味更重。"},{"en":"Regulations use it to state what a provision applies to.","cn":"规章用它说明条款适用于什么。"}],"abstract":[{"en":"Like a spotlight aimed at one column of a page while the rest stays dim.","cn":"像一束光打在一页纸的某一栏，其余部分仍暗着。"},{"en":"Like a bookmark placed at a chapter: it says where to read, not what to think.","cn":"像夹在某一章的书签：说明读哪里，不说怎么想。"},{"en":"Like a clerk turning a file so the relevant page faces the reader.","cn":"像职员把卷宗转到相关那一页朝向读者。"}]},"examples":[{"en":"With regard to your question, the answer is in the appendix.","cn":"关于您的问题，答案在附录里。"},{"en":"No decision has been taken with regard to the site.","cn":"关于选址尚未作出决定。"},{"en":"With regard to cost, the two plans are close.","cn":"就成本而言，两个方案相近。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「威兹 瑞嘎德 图」——目光只落在文件的一栏：关于、就……而言","word":"with regard to"},"root":"核心名词意为关注，来自古法语 regarder「注视」，由拉丁语前缀 re- 与日耳曼语系表看守的词干构成，后者为重构形式；该短语为近代公文定型，首见年代不确定。","sensesIntro":{"en":"Eight senses cover the formal topic marker, correspondence openings, the grammatical boundary against the participle, register beside the older variant, the preposition variant, a stated stance, the scope of a rule and the exclusion of the esteem sense.","cn":"八个义项涵盖：正式话题标记、书信起句、与分词形式的语法边界、与古旧变体的语域分工、介词变体、表态、条款适用范围，以及排除尊敬义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a beam of attention falling on one column of a document while the rest stays in shadow.","cn":"核心意象：一束注意力落在文件的一栏上，其余部分留在阴影里。"},"chain":["LOOK","ATTENTION","CONSIDERATION","TOPIC","FORMAL ADDRESS","APPLICABILITY"],"branches":[{"senses":"01 · 05","en":"THE TOPIC: one matter is singled out for the reader, whatever preposition is chosen.","cn":"话题：无论选哪个介词，都是把一件事单独提给读者。"},{"senses":"02","en":"THE LETTER: office correspondence needs a dignified opening for a single point.","cn":"书信：公文往来需要得体的起句来引出单一问题。"},{"senses":"03 · 04","en":"THE FORM AND THE TONE: a frame differs from a participle, and one variant sounds older.","cn":"形式与语气：框架不同于分词，一个变体也更古旧。"},{"senses":"06","en":"THE STANCE: a body may look at a finding and then say how it views it.","cn":"立场：机构先看向某项发现，再表明如何看待它。"},{"senses":"07 · 08","en":"THE SCOPE AND THE LIMIT: rules say what they cover, and no esteem is implied.","cn":"范围与边界：规则说明覆盖什么，且不含敬意。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin prefix and a Germanic stem inside a French verb, then adds a modern topic frame.","cn":"这个短语的动词在法语中由拉丁语前缀与日耳曼语词干合成，后来又加上近代话题框架。"},"latinIntro":{"en":"The only Latin element is the prefix re-, meaning back or again; the stem that means guard is Germanic and reconstructed.","cn":"其中唯一的拉丁成分是前缀 re-，意为回、再；表看守的词干属日耳曼语，为重构形式。"},"items":[{"word":"re-","structure":"Latin prefix","meaning":"back; again","meaningCN":"回；再","example":"The prefix adds a repeated or returned action.","exampleCN":"这个前缀加上重复或返回的动作。"},{"word":"regard","structure":"Old French regarder","meaning":"to look at; to heed","meaningCN":"注视；留意","example":"English keeps both the look and the heed.","exampleCN":"英语兼留注视与留意两义。"},{"word":"regarding","structure":"regard + -ing","meaning":"concerning","meaningCN":"关于","example":"The participle became a preposition in its own right.","exampleCN":"分词独立成为介词。"},{"word":"regardless","structure":"regard + -less","meaning":"without heed","meaningCN":"不顾；不管怎样","example":"The suffix removes the looking entirely.","exampleCN":"后缀把「看」整个去掉。"},{"word":"disregard","structure":"dis- + regard","meaning":"to pay no attention","meaningCN":"漠视；不理会","example":"The negative prefix reverses the attention.","exampleCN":"否定前缀把注意力反转。"},{"word":"regards","structure":"plural noun","meaning":"greetings","meaningCN":"问候；致意","example":"The plural turns attention into a courtesy.","exampleCN":"复数把关注变成礼节。"},{"word":"in regard to","structure":"preposition + noun + preposition","meaning":"concerning","meaningCN":"关于","example":"A variant preposition marks the same topic.","exampleCN":"换一个介词标出同一话题。"},{"word":"as regards","structure":"conjunction + plural noun","meaning":"concerning","meaningCN":"关于","example":"The older variant survives in legal prose.","exampleCN":"较古旧的变体留在法律文字里。"},{"word":"with regard to","structure":"preposition + noun + preposition","meaning":"concerning","meaningCN":"关于","example":"The frame is standard in official writing.","exampleCN":"这个框架在公文中是标准用法。"}],"latinEntries":[{"word":"re-","structure":"prefix","meaning":"back; again","meaningCN":"回；再"}],"derivatives":[{"word":"regard","pos":"n./v.","zh":"注视；看待"},{"word":"regarding","pos":"prep.","zh":"关于"},{"word":"regardless","pos":"adv.","zh":"不管怎样"},{"word":"disregard","pos":"v./n.","zh":"漠视"},{"word":"regards","pos":"n.","zh":"问候"}]}},{"word":"to a certain extent","ipa_uk":"/tuː ə ˈsɜːtn ɪkˈstent/","ipa_us":"/tuː ə ˈsɜːrtn ɪkˈstent/","definition_zh":"在一定程度上；部分地（表示某说法只部分成立，留有保留）","definition_en":"partly; in some measure, but not completely","core_image":"一杯水只倒到杯身一半，杯口还空着一截","scene":"老师看完两份实验记录，指出其中一份的结论只说对了一半。The first explanation holds to a certain extent, but it ignores the second cause.","sceneCN":"这里取「在一定程度上」（第 1 个义项：限定说法成立的比例）；句意为第一种解释在一定程度上成立，但忽略了第二个原因。","pos":[{"tag":"prep. phr.","zh":"介词短语：在一定程度上；部分地"}],"collocations":[{"phrase":"only to a certain extent","zh":"仅在一定程度上"},{"phrase":"true to a certain extent","zh":"在一定程度上正确"},{"phrase":"agree to a certain extent","zh":"一定程度上同意"},{"phrase":"to a certain extent dependent on","zh":"在一定程度上取决于"},{"phrase":"to a certain extent predictable","zh":"在一定程度上可预测"},{"phrase":"to a certain extent, yes","zh":"在一定程度上是这样"}],"forms":[{"label":"原形","form":"to a certain extent"},{"label":"句首形式","form":"To a certain extent,"},{"label":"句末形式","form":"to a certain extent"},{"label":"否定形式","form":"not to any great extent"}],"derivatives":[{"word":"extent","pos":"n.","zh":"程度；范围"},{"word":"extend","pos":"v.","zh":"延伸；扩展"},{"word":"extensive","pos":"adj.","zh":"广泛的；大规模的"},{"word":"extension","pos":"n.","zh":"延长；延伸部分"},{"word":"extended","pos":"adj.","zh":"延长的；长期的"},{"word":"extensively","pos":"adv.","zh":"广泛地"}],"senses":[{"no":"01","title":"Partly true","titleCN":"部分成立义：只对一部分","definition":"used to limit the strength of a statement so that it claims only partial truth","definitionCN":"用来限定陈述的力度，只主张部分成立","example":"The model fits the observations to a certain extent.","exampleCN":"这个模型在一定程度上符合观测。","why":"Extent is a stretch, and a stretch can stop before it covers the whole distance.","whyCN":"程度本是一段伸展，而伸展可以在走完全程之前停住。"},{"no":"02","title":"Beside the plain twin","titleCN":"近义辨析：与另一变体的量差","definition":"it suggests a limited but definite measure, while the shorter twin is vaguer about how much","definitionCN":"它暗示有限但确定的分量，而较短的近义说法对分量更含糊","example":"Costs fell to a certain extent, though not as much as promised.","exampleCN":"成本有一定程度下降，但没有承诺的那么多。","why":"Adding the article makes the measure sound counted rather than waved away.","whyCN":"加上冠词让这个分量听起来是被计过的，而不是随手一挥。"},{"no":"03","title":"On a scale of degree","titleCN":"梯度义：与更大程度说法对照","definition":"it sits low on a scale that runs from a limited degree through a large degree to the whole","definitionCN":"它处在一条由小程度经大程度到全体的尺度上的低处","example":"To a certain extent, the two explanations overlap.","exampleCN":"在一定程度上，两种解释有重叠。","why":"Degree words form a ladder, and this rung is deliberately low.","whyCN":"表程度的词构成一架梯子，这一级故意放得很低。"},{"no":"04","title":"Modifying an adjective","titleCN":"修饰义：直接限定形容词","definition":"it can qualify an adjective or a verb, softening an assessment without denying it","definitionCN":"可限定形容词或动词，软化评价而不否认它","example":"The report is reliable to a certain extent.","exampleCN":"这份报告在一定程度上可靠。","why":"A measure phrase at the end of a clause works like a dimmer switch on the judgement.","whyCN":"句末的表量短语像调光开关，把判断调暗一些。"},{"no":"05","title":"A concessive move","titleCN":"让步义：先退一步再补充","definition":"in argument it concedes a point partially before the speaker adds a reservation","definitionCN":"在论证中先部分承认对方观点，随后再补上保留","example":"I accept the criticism to a certain extent.","exampleCN":"我在一定程度上接受这一批评。","why":"Concession needs a stopper, and the limited measure stops the admission from becoming total.","whyCN":"让步需要一个限位器，有限的分量正好防止承认变成全盘接受。"},{"no":"06","title":"Not a spatial range","titleCN":"辨义：不表空间范围","definition":"it measures how far a statement holds, not how far a place or an area reaches","definitionCN":"它量的是说法成立的程度，而非某地或某区域延伸的范围","example":"The outcome depends to a certain extent on decisions made elsewhere.","exampleCN":"结果在一定程度上取决于别处作出的决定。","why":"The noun has a physical sense of area, but this phrase uses only the abstract sense of degree.","whyCN":"这个名词有具体面积的义，但这个短语只用抽象的程度义。"},{"no":"07","title":"A hedge in research","titleCN":"学术义：限定结论强度","definition":"in academic writing it keeps a conclusion from claiming more than the evidence supports","definitionCN":"在学术写作中，避免结论超出证据所能支撑的范围","example":"The finding supports the hypothesis to a certain extent.","exampleCN":"这一发现一定程度上支持该假设。","why":"Scholarship rewards caution, and a stated limit is a mark of care rather than weakness.","whyCN":"学术看重谨慎，写明限度是细致的表现而非软弱。"},{"no":"08","title":"A hedge in promises","titleCN":"日常义：给承诺留余地","definition":"in everyday talk it warns that a benefit or a repair will only go part of the way","definitionCN":"在日常谈话中，提醒某项好处或修理只能起到部分作用","example":"The medicine will ease the pain to a certain extent.","exampleCN":"这药会在一定程度上减轻疼痛。","why":"Promises sound safer when a limit is named, which is why the phrase appears in advice.","whyCN":"写明限度会让承诺听起来更稳妥，因此这个短语常出现在叮嘱里。"}],"etymology":{"intro":{"en":"Extent comes from Latin extentus, the participle of extendere, to stretch out, built on tendere, to stretch. Certain comes from Latin certus, settled or sure. Both sources are secure; the phrase is modern.","cn":"extent 来自拉丁语 extentus，是 extendere「向外伸展」的分词，其下为 tendere「拉」。certain 来自拉丁语 certus「已定的、确然的」。两处来源都清楚；短语属近代。"},"items":[{"era":"LATIN TENDERE","en":"Tendere meant to stretch or pull, and it supplies a large family of English tension words.","cn":"tendere 意为拉伸、牵引，构成英语中一大批表张力的词。"},{"era":"EXTENDERE","en":"The prefix for out plus the verb gave the sense of stretching something out to its full length.","cn":"表向外的前缀加动词，给出把某物拉伸到全长的意思。"},{"era":"EXTENTUS AND EXTENT","en":"The participle became a noun for the distance covered, hence range and degree.","cn":"分词转为名词，指所覆盖的距离，由此有范围与程度。"},{"era":"LATIN CERTUS","en":"Certus meant settled or decided, and English certain keeps both the sure and the unspecified senses.","cn":"certus 意为已定、已决，英语 certain 兼留确然与某一未指明两种义。"},{"era":"THE FIXED PHRASE","en":"The hedging frame belongs to modern written argument; first dates are approximate.","cn":"这个限定框架属于近代书面论证，首见年代为约数。"}]},"similar":{"note":{"en":"The first group varies the measure or the degree; the second group are one-word hedges with the same caution.","cn":"第一组替换分量或程度；第二组是同属谨慎语气的单词限定语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"to some extent","ipa":"/tuː sʌm ɪkˈstent/","tag":"vaguer measure","definition":"It limits a claim without suggesting a counted degree.","definitionCN":"限定主张，但不暗示被计过的分量。"},{"word":"to a large extent","ipa":"/tuː ə lɑːdʒ ɪkˈstent/","tag":"high on the scale","definition":"It concedes most of the claim, which is nearly the opposite force.","definitionCN":"承认主张的大部分，力度几乎相反。"},{"word":"to a degree","ipa":"/tuː ə dɪˈɡriː/","tag":"same frame, shorter noun","definition":"It sounds more conversational and slightly less precise.","definitionCN":"更口语，也略欠精确。"},{"word":"to that extent","ipa":"/tuː ðæt ɪkˈstent/","tag":"pointing back","definition":"It refers to a measure already named earlier in the text.","definitionCN":"回指上文已经提到的分量。"}]},{"heading":"NEAR MEANING","entries":[{"word":"partly","ipa":"/ˈpɑːtli/","tag":"one-word hedge","definition":"A single adverb for a partial claim.","definitionCN":"单个副词表部分成立。"},{"word":"somewhat","ipa":"/ˈsʌmwɒt/","tag":"softening","definition":"It softens an adjective rather than measuring a claim.","definitionCN":"用来软化形容词，而非给主张量度。"},{"word":"in part","ipa":"/ɪn pɑːt/","tag":"partial in composition","definition":"It often divides a whole into contributing parts.","definitionCN":"常把整体分成若干起作用的部分。"},{"word":"up to a point","ipa":"/ʌp tuː ə pɔɪnt/","tag":"with a hard limit","definition":"It grants a claim only as far as a stated point.","definitionCN":"只承认到某一明确限度为止。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real stretching root, the settled sense of certain, and the real hedging grammar of degree.","cn":"正常联想用真实的拉伸词根、已定的限定词，以及真实的程度限定语法。"},"normal":[{"en":"Extent is a stretch, so a claim can stretch only part of the way.","cn":"程度是一段伸展，因此主张只能伸展到半途。"},{"en":"Certain here means a fixed but unnamed measure, not a sure fact.","cn":"此处的限定词指固定但未指明的分量，不是确然的事实。"},{"en":"It sits low on a degree ladder that runs up to a large extent.","cn":"它位于一架通往大程度的梯子的低处。"},{"en":"At the end of a clause it works like a dimmer on the judgement.","cn":"放在句末时，它像给判断装了调光器。"},{"en":"It concedes a point without surrendering the argument.","cn":"它让出一小步，却不交出整个论点。"}],"abstract":[{"en":"Like a glass filled halfway, with the top half still empty.","cn":"像只倒了一半的杯子，上半截还空着。"},{"en":"Like a door opened a crack: enough to see through, not enough to walk in.","cn":"像门只开一条缝：够看见里面，不够走进去。"},{"en":"Like a dimmer turned low, so the light shows the room without flooding it.","cn":"像把调光器调低，照见房间却不至于晃眼。"}]},"examples":[{"en":"The two accounts agree to a certain extent.","cn":"两种说法在一定程度上是一致的。"},{"en":"Her prediction was right to a certain extent.","cn":"她的预测在一定程度上是对的。"},{"en":"The plan depends to a certain extent on the weather.","cn":"这个计划在一定程度上要看天气。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「图 阿 瑟顿 伊克斯滕特」——杯子只倒了一半，杯口还空着：在一定程度上","word":"to a certain extent"},"root":"核心名词意为程度，来自拉丁语 extentus「伸展」，出自动词 extendere「向外拉伸」；限定词出自拉丁语 certus「已定的」。该短语为近代书面语定型，首见年代不确定。","sensesIntro":{"en":"Eight senses separate partial truth, the contrast with the vaguer twin, the place on a degree ladder, adjectival modification, concession, the exclusion of spatial range, academic hedging and everyday promises.","cn":"八个义项区分：部分成立、与含糊近义说的对照、在程度梯度上的位置、修饰形容词、让步、排除空间范围、学术限定、日常承诺留余地。"},"semanticMap":{"core":{"en":"CORE IMAGE: a glass filled exactly halfway, the upper half still empty.","cn":"核心意象：一只只倒到一半的杯子，上半截仍空着。"},"chain":["STRETCH OUT","RANGE","DEGREE","PARTLY","HEDGE","LIMIT"],"branches":[{"senses":"01 · 05","en":"THE PART: a claim is granted only as far as the measure reaches.","cn":"部分：主张只在分量所及之处被承认。"},{"senses":"02 · 03","en":"THE SCALE: the same frame varies from a small to a large degree.","cn":"尺度：同一框架从小分量一直排到大分量。"},{"senses":"04","en":"THE MODIFIER: an adjective or a verb is softened rather than denied.","cn":"修饰：形容词或动词被软化，而不是被否定。"},{"senses":"06","en":"THE LIMIT: degree is meant, not the area a place covers.","cn":"边界：说的是程度，不是某地覆盖的面积。"},{"senses":"07 · 08","en":"THE REGISTER: research and advice both use the limit to stay honest.","cn":"语域：研究与叮嘱都用限度来保持诚实。"}]},"affixes":{"intro":{"en":"The phrase combines a Latin noun of stretching with a Latin adjective of settled measure.","cn":"这个短语把一个表伸展的拉丁语名词与一个表既定分量的拉丁语形容词结合在一起。"},"latinIntro":{"en":"The noun comes from extendere, to stretch out, on tendere, to stretch; the limiting word comes from certus, settled.","cn":"名词出自 extendere「向外拉伸」，其下为 tendere「拉」；限定词出自 certus「已定的」。"},"items":[{"word":"tendere","structure":"Latin verb","meaning":"to stretch; to pull","meaningCN":"拉伸；牵引","example":"The verb is the base of tension and extension alike.","exampleCN":"这个词是张力与延伸两族词的根。"},{"word":"extendere","structure":"ex- + tendere","meaning":"to stretch out","meaningCN":"向外伸展","example":"The prefix adds direction away from the centre.","exampleCN":"前缀加上离开中心的方向。"},{"word":"extentus","structure":"Latin participle","meaning":"stretched out","meaningCN":"被拉伸的","example":"The participle turned into a noun of range.","exampleCN":"分词转为表范围的名词。"},{"word":"extent","structure":"English noun","meaning":"degree; range","meaningCN":"程度；范围","example":"English keeps the abstract measure and the physical area.","exampleCN":"英语兼留抽象程度与具体面积。"},{"word":"extend","structure":"extendere through French","meaning":"to lengthen; to stretch","meaningCN":"延伸；扩展","example":"The verb restores the action behind the noun.","exampleCN":"这个动词恢复了名词背后的动作。"},{"word":"extensive","structure":"extend + -ive","meaning":"covering much","meaningCN":"广泛的","example":"The adjective describes wide coverage.","exampleCN":"形容词描述覆盖得广。"},{"word":"extension","structure":"extend + -ion","meaning":"a lengthening; an added part","meaningCN":"延长；延伸部分","example":"The noun names the result of stretching.","exampleCN":"这个名词指拉伸的结果。"},{"word":"certus","structure":"Latin adjective","meaning":"settled; sure","meaningCN":"已定的；确然的","example":"The adjective yields the limiting word in the phrase.","exampleCN":"这个形容词给出短语中的限定词。"},{"word":"to a certain extent","structure":"preposition + article + adjective + noun","meaning":"partly","meaningCN":"在一定程度上","example":"The frame is a standard hedge in argument.","exampleCN":"这个框架是论证中的标准限定语。"}],"latinEntries":[{"word":"tendere","structure":"tendere, tetendi, tensum (verb, third conjugation)","meaning":"to stretch; to pull","meaningCN":"拉伸；牵引"},{"word":"extendere","structure":"extendere, extendi, extensum (verb)","meaning":"to stretch out","meaningCN":"向外伸展"},{"word":"certus","structure":"certus, -a, -um (adjective)","meaning":"settled; sure","meaningCN":"已定的；确然的"}],"derivatives":[{"word":"extent","pos":"n.","zh":"程度；范围"},{"word":"extend","pos":"v.","zh":"延伸；扩展"},{"word":"extensive","pos":"adj.","zh":"广泛的"},{"word":"extension","pos":"n.","zh":"延长；延伸部分"},{"word":"extended","pos":"adj.","zh":"延长的"},{"word":"extensively","pos":"adv.","zh":"广泛地"}]}},{"word":"as a result","ipa_uk":"/æz ə rɪˈzʌlt/","ipa_us":"/æz ə rɪˈzʌlt/","definition_zh":"结果、因此；由于前面所说的情况，后面出现这样的后果（作衔接状语）","definition_en":"because of what has just been stated; consequently","core_image":"一排骨牌依次倒下，最后一块压住了地上的纸","scene":"仓库的通风口被纸箱堵住，温度一夜之间升高，冷藏的货物开始变质。As a result, half of the shipment had to be thrown away.","sceneCN":"这里取「结果、因此」（第 1 个义项：在句首承接前因、引出后果）；句意为结果有一半货物不得不丢弃。","pos":[{"tag":"adv. phr.","zh":"副词短语：结果；因此"}],"collocations":[{"phrase":"as a result of","zh":"由于；作为……的结果"},{"phrase":"as a direct result","zh":"作为直接结果"},{"phrase":"and as a result","zh":"因而"},{"phrase":"as a result of this","zh":"因此之故"},{"phrase":"partly as a result","zh":"部分由于这个原因"},{"phrase":"as a result, however","zh":"但结果是"}],"forms":[{"label":"原形","form":"as a result"},{"label":"带原因形式","form":"as a result of"},{"label":"句首形式","form":"As a result,"},{"label":"修饰形式","form":"as a direct result"}],"derivatives":[{"word":"result","pos":"n./v.","zh":"结果；导致"},{"word":"resultant","pos":"adj.","zh":"由此产生的"},{"word":"resulting","pos":"adj.","zh":"作为结果的"},{"word":"results","pos":"n.","zh":"成果；成绩"}],"senses":[{"no":"01","title":"The connector at the front","titleCN":"衔接义：句首引出后果","definition":"used at the beginning of a sentence to introduce the consequence of what was just said","definitionCN":"用在句首，引出刚才所述情况带来的后果","example":"The pipe froze, and as a result the whole floor was flooded.","exampleCN":"管子冻住了，结果整层楼都被水淹了。","why":"Result began as a springing back, and a consequence is what bounces out of an earlier event.","whyCN":"结果本指弹回，后果正是从先前事件中弹出来的东西。"},{"no":"02","title":"Why it takes no cause","titleCN":"结构边界：本身不接原因","definition":"the bare phrase states the effect only; the version with of is needed to name the cause","definitionCN":"光用这个短语只陈述结果；要说出原因，必须用带上该介词的形式","example":"As a result of the delay, the opening was moved to autumn.","exampleCN":"由于这次延误，开幕改到了秋天。","why":"English splits the job: one form points forward to the effect, the other backward to the cause.","whyCN":"英语把功能分开：一种形式指向后果，另一种回指原因。"},{"no":"03","title":"Register beside a single adverb","titleCN":"语域义：与单词副词的分工","definition":"it is the fuller, more explicit choice, while a single adverb such as consequently is tighter and more formal","definitionCN":"它是更完整、更明白的选择，而单个副词更紧凑、更正式","example":"The sample was too small; as a result, the finding is weak.","exampleCN":"样本太小，因此结论不够有力。","why":"A two-word frame slows the reader down at the hinge of an argument.","whyCN":"由两个词构成的框架会让读者在论证的铰接处放慢速度。"},{"no":"04","title":"Effect versus inference","titleCN":"辨义：事实结果不同于逻辑推导","definition":"it marks what actually followed, while an inference word marks what must be concluded","definitionCN":"它标出实际随之发生的事，而推论词标出必然得出的判断","example":"He missed the deadline and as a result lost the contract.","exampleCN":"他误了期限，结果丢掉了合同。","why":"A result is an event in the world; an inference is a move in an argument.","whyCN":"结果是世上发生的事，推论是论证中的一步。"},{"no":"05","title":"Mid-sentence and final position","titleCN":"位置义：可置于句末","definition":"it can close a clause as well as open a sentence, so the effect may come after the cause and then be labelled","definitionCN":"它既可开启句子，也可收束分句，因此后果可以先出现、再被标注","example":"The filter clogged and the pump failed as a result.","exampleCN":"滤芯堵了，水泵因此失灵。","why":"Placing the frame last makes the causal link feel discovered rather than announced.","whyCN":"把框架放在最后，因果关系像是被发现的，而不是被宣告的。"},{"no":"06","title":"The report habit","titleCN":"学术义：报告与论文中的衔接","definition":"in reports and papers it links a finding to its practical consequence without adding interpretation","definitionCN":"在报告与论文中，把一项发现与其实际后果连接起来，不添加解释","example":"Two variables were uncontrolled, and as a result the comparison is limited.","exampleCN":"有两个变量未受控，因此比较的结论有限。","why":"Research writing needs neutral connectors, and this one states causation without assigning blame.","whyCN":"研究写作需要中性衔接语，这个说法陈述因果而不归咎。"},{"no":"07","title":"Fact, not purpose","titleCN":"辨义：表因果不表目的","definition":"it reports what happened because of an earlier event, not what someone intended to achieve","definitionCN":"它陈述因先前事件而发生的事，而非某人打算达成的事","example":"The firm cut staff, and as a result output fell.","exampleCN":"公司裁减员工，结果产量下降。","why":"Cause and purpose point in opposite directions in time: one looks back, the other forward.","whyCN":"原因与目的在时间上指向相反：一个回望，一个前瞻。"},{"no":"08","title":"The spoken summary","titleCN":"口语义：日常叙事中的收束","definition":"in speech it often sums up a chain of small events with a single consequence","definitionCN":"在口语中，常用一个后果来收束一连串小事","example":"We left late, and as a result we missed the train.","exampleCN":"我们出门晚了，结果错过了火车。","why":"The phrase works at any scale, from a missed train to a failed policy.","whyCN":"这个短语适用于任何尺度，从错过火车到政策失败。"}],"etymology":{"intro":{"en":"Result comes from Latin resultare, to spring back, from re-, back, and saltare, to leap. The Latin chain is secure; the connector is modern English.","cn":"result 来自拉丁语 resultare「弹回」，由 re-「向后」与 saltare「跳」构成。拉丁语链条清楚；衔接用法是近代英语的发展。"},"items":[{"era":"LATIN SALIRE","en":"Salire meant to leap, and its family covers jumping, assault and a range of sudden movements.","cn":"salire 意为跳，其词族涵盖跳跃、冲击与多种突发动作。"},{"era":"SALTARE","en":"The repeated form described leaping again and again, closer to dancing than to a single bound.","cn":"这个反复形式描写一再跳跃，比单次跃起更接近舞蹈。"},{"era":"RESULTARE","en":"With the prefix for back, the verb pictured something bouncing off a surface.","cn":"加上表向后的前缀，动词描绘某物从表面弹回。"},{"era":"FROM REBOUND TO CONSEQUENCE","en":"The noun shifted from a physical rebound to whatever follows from an earlier event.","cn":"名词从物理弹回转为指由先前事件引出的一切。"},{"era":"THE CONNECTOR","en":"The adverbial frame becomes common in modern expository prose; first dates are approximate.","cn":"这个副词框架在近代说明文中通行，首见年代为约数。"}]},"similar":{"note":{"en":"The first group looks or works like a result marker but adds a cause or points elsewhere; the second group are one-word consequence words.","cn":"第一组外形或功能接近结果标记，但会带出原因或指向别处；第二组是单词形式的后果词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"as a consequence","ipa":"/æz ə ˈkɒnsɪkwəns/","tag":"formal twin","definition":"It is the formal equivalent, common in reports.","definitionCN":"这是正式对应说法，多用于报告。"},{"word":"as a result of","ipa":"/æz ə rɪˈzʌlt əv/","tag":"cause-taking","definition":"It takes the cause instead of stating the effect alone.","definitionCN":"它后接原因，而非只陈述结果。"},{"word":"resulting in","ipa":"/rɪˈzʌltɪŋ ɪn/","tag":"verb frame","definition":"It points forward from the cause to the effect.","definitionCN":"它从原因指向结果。"},{"word":"in the wake of","ipa":"/ɪn ðə weɪk əv/","tag":"following after","definition":"It means after and because of an event, often of trouble.","definitionCN":"意为某事之后、因其而起，常指麻烦。"}]},{"heading":"NEAR MEANING","entries":[{"word":"consequently","ipa":"/ˈkɒnsɪkwəntli/","tag":"formal adverb","definition":"A single word that marks the effect in formal prose.","definitionCN":"正式文字中标记后果的单词。"},{"word":"therefore","ipa":"/ˈðeəfɔː/","tag":"inference","definition":"It marks what follows logically, not necessarily what happened.","definitionCN":"标出逻辑上随之而来的结论，未必是实际发生的事。"},{"word":"hence","ipa":"/hens/","tag":"compact and formal","definition":"A short, slightly bookish marker of consequence.","definitionCN":"简短、略偏书面的后果标记。"},{"word":"thus","ipa":"/ðʌs/","tag":"manner and result","definition":"It can mean in this way as well as for this reason.","definitionCN":"既可表如此方式，也可表因此。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real leaping and rebounding root, the real split from the cause phrase, and the real difference from inference words.","cn":"正常联想用真实的跳跃、弹回词根，与带原因形式的分工，以及和推论词的差别。"},"normal":[{"en":"A result rebounds: something comes back off an earlier event.","cn":"结果会弹回：有东西从先前事件反弹出来。"},{"en":"The bare frame points forward; the form with of points back to the cause.","cn":"光用框架指向后果；带该介词的形式回指原因。"},{"en":"It reports what happened, not what must be concluded.","cn":"它陈述发生了什么，而非必然得出什么。"},{"en":"At the end of a clause the link sounds discovered.","cn":"放在分句末尾，因果关系像是被发现的。"},{"en":"It works at any scale, from a missed train to a failed policy.","cn":"它适用于任何尺度，从错过火车到政策失败。"}],"abstract":[{"en":"Like dominoes falling: the last tile lands on the paper, and the fall explains it.","cn":"像骨牌接连倒下：最后一块压在纸上，倒下的过程解释了它。"},{"en":"Like a billiard ball bouncing off the cushion and hitting a second ball.","cn":"像台球从库边弹回，又撞上第二颗球。"},{"en":"Like the last domino shown in a diagram, the visible end of a chain already set in motion.","cn":"像示意图里最后那张骨牌，是一条早已启动的链条可见的末端。"}]},"examples":[{"en":"The road was closed, and as a result traffic moved inland.","cn":"公路封闭，结果车流转向内陆。"},{"en":"Rainfall was low; as a result, the reservoir is half empty.","cn":"降雨稀少，因此水库空了一半。"},{"en":"He ignored the warning, and as a result the engine seized.","cn":"他忽视警告，结果发动机卡死了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「阿兹 阿 瑞造特」——骨牌一路倒下，最后压住那张纸：结果、因此","word":"as a result"},"root":"核心名词意为结果，来自拉丁语 resultare「弹回」，由 re-「向后」与 saltare「跳」构成；由弹回引申为由某事引出的后果。该短语为近代衔接用语定型，首见年代不确定。","sensesIntro":{"en":"Eight senses cover the sentence-opening connector, the ban on taking a cause, register beside single adverbs, effect against inference, final position, report usage, the exclusion of purpose and the spoken summary.","cn":"八个义项涵盖：句首衔接、不接原因的结构边界、与单词副词的语域分工、事实结果与逻辑推导之别、句末位置、报告用法、排除目的义，以及口语收束。"},"semanticMap":{"core":{"en":"CORE IMAGE: dominoes falling one after another until the last tile lands on a sheet of paper.","cn":"核心意象：骨牌一块接一块倒下，直到最后一块压在一张纸上。"},"chain":["LEAP","SPRING BACK","FOLLOW FROM","CONSEQUENCE","CONNECTOR","OUTCOME"],"branches":[{"senses":"01 · 05","en":"THE CONSEQUENCE: the effect may be announced first or labelled after it happens.","cn":"后果：既可以先宣告，也可以在发生后标注。"},{"senses":"02","en":"THE CAUSE FORM: only the version with of can name what produced the effect.","cn":"原因形式：只有带该介词的形式才能点出成因。"},{"senses":"03 · 06","en":"THE REGISTER: reports and papers need a neutral, explicit hinge.","cn":"语域：报告与论文需要一个中性、明白的铰接处。"},{"senses":"04","en":"THE CONTRAST: an event in the world differs from a step in an argument.","cn":"对照：世上发生的事不同于论证中的一步。"},{"senses":"07 · 08","en":"THE LIMIT: purpose is excluded, and everyday narration uses the same frame.","cn":"边界：目的义被排除，日常叙事也用同一框架。"}]},"affixes":{"intro":{"en":"The phrase rests on a Latin noun of rebounding, so the causal link keeps a physical bounce in its history.","cn":"这个短语建在一个表弹回的拉丁语名词上，因此因果联系在历史里留着一次物理弹跳。"},"latinIntro":{"en":"The base verb is salire, to leap, with its repeated form saltare; resultare adds the prefix for back.","cn":"基础动词是 salire「跳」，其反复形式为 saltare；resultare 加上了表向后的前缀。"},"items":[{"word":"salire","structure":"Latin verb","meaning":"to leap","meaningCN":"跳；跃","example":"The verb supplies the physical core of the family.","exampleCN":"这个词提供词族的物理内核。"},{"word":"saltare","structure":"Latin frequentative verb","meaning":"to leap repeatedly; to dance","meaningCN":"反复跳；舞蹈","example":"The repeated form pictures continued motion.","exampleCN":"反复形式描绘持续的运动。"},{"word":"resultare","structure":"re- + saltare","meaning":"to spring back","meaningCN":"弹回","example":"The prefix adds a backward direction.","exampleCN":"前缀加上向后的方向。"},{"word":"result","structure":"English noun and verb","meaning":"an outcome; to follow from","meaningCN":"结果；导致","example":"English keeps both the event and the relation.","exampleCN":"英语兼指事件与关系。"},{"word":"resultant","structure":"result + -ant","meaning":"arising as a consequence","meaningCN":"由此产生的","example":"The adjective labels what follows.","exampleCN":"形容词标出随之而来的东西。"},{"word":"resulting","structure":"result + -ing","meaning":"following as an effect","meaningCN":"作为结果的","example":"The participle attaches the effect to a noun.","exampleCN":"分词把后果挂到名词上。"},{"word":"as a consequence","structure":"preposition + article + noun","meaning":"consequently","meaningCN":"因此；结果","example":"The formal twin performs the same task.","exampleCN":"正式同义说法承担同样功能。"},{"word":"as a result of","structure":"preposition + article + noun + preposition","meaning":"because of","meaningCN":"由于","example":"Adding of turns the phrase towards the cause.","exampleCN":"加上该介词就把短语转向原因。"},{"word":"as a result","structure":"preposition + article + noun","meaning":"consequently","meaningCN":"结果；因此","example":"The frame is standard in modern expository prose.","exampleCN":"这个框架在近代说明文中是标准用法。"}],"latinEntries":[{"word":"salire","structure":"salire, salui, saltum (verb, fourth conjugation)","meaning":"to leap","meaningCN":"跳"},{"word":"saltare","structure":"saltare, saltavi, saltatum (verb, first conjugation)","meaning":"to leap repeatedly","meaningCN":"反复跳"},{"word":"resultare","structure":"resultare, resultavi, resultatum (verb)","meaning":"to spring back","meaningCN":"弹回"}],"derivatives":[{"word":"result","pos":"n./v.","zh":"结果；导致"},{"word":"resultant","pos":"adj.","zh":"由此产生的"},{"word":"resulting","pos":"adj.","zh":"作为结果的"},{"word":"results","pos":"n.","zh":"成果；成绩"}]}},{"word":"in turn","ipa_uk":"/ɪn ˈtɜːn/","ipa_us":"/ɪn ˈtɜːrn/","definition_zh":"依次、轮流；反过来、进而（表示按顺序相继，或一环引发一环）","definition_en":"one after another in order; or as a further consequence, one thing acting back on another","core_image":"一排人依次传递一只水桶，桶从第一双手传到最后一双手","scene":"夜班交接按工位顺序进行，前一岗记录完毕，后一岗才接手清点。Each shift briefed the next in turn, and the last one reported to the manager.","sceneCN":"这里取「依次、轮流」（第 1 个义项：按顺序相继进行）；句意为各班依次向下一班交接，最后一班向经理汇报。","pos":[{"tag":"adv. phr.","zh":"副词短语：依次；轮流；反过来"}],"collocations":[{"phrase":"each in turn","zh":"逐一；依次"},{"phrase":"and in turn","zh":"进而；而这又"},{"phrase":"which in turn","zh":"而这又……（定语从句）"},{"phrase":"in turn affect","zh":"反过来影响"},{"phrase":"taking each in turn","zh":"逐项依次处理"},{"phrase":"in turn for","zh":"依次轮到"}],"forms":[{"label":"原形","form":"in turn"},{"label":"定语从句形式","form":"which in turn"},{"label":"强调形式","form":"each in turn"},{"label":"对照形式","form":"by turns"}],"derivatives":[{"word":"turn","pos":"n./v.","zh":"转动；轮次；转弯"},{"word":"turning","pos":"n.","zh":"转弯处；转折点"},{"word":"turnover","pos":"n.","zh":"营业额；人员更替"},{"word":"turnout","pos":"n.","zh":"出席人数；产量"},{"word":"turnaround","pos":"n.","zh":"周转；好转"}],"senses":[{"no":"01","title":"One after another","titleCN":"顺序义：依次、按次序","definition":"used to say that members of a group do something one after another in a settled order","definitionCN":"表示一群人按既定次序一个接一个地做某事","example":"The applications were reviewed in turn by three readers.","exampleCN":"申请材料由三位审阅人依次看过。","why":"Turn is a rotation, and a rotation passes each position once before returning.","whyCN":"轮转就是旋转，而旋转让每个位置各经过一次再回到原处。"},{"no":"02","title":"One thing causing the next","titleCN":"递进义：反过来、进而","definition":"used to say that an effect becomes a cause in the next step of a chain","definitionCN":"表示某一后果在链条的下一步又成为原因","example":"Higher demand raised prices, which in turn reduced sales.","exampleCN":"需求升高推高了价格，这又反过来压低了销量。","why":"In a circle each point hands the motion to the next, which is why turn serves causation as well as order.","whyCN":"在一个圆环上，每一点把运动交给下一点，因此轮转既能表顺序，也能表因果。"},{"no":"03","title":"Not a repayment","titleCN":"辨义：不同于回报","definition":"it marks succession or consequence, while the look-alike phrase with return marks a response given in exchange","definitionCN":"它标相继或后果，而形近短语标作为交换给出的回应","example":"The bank raised rates, and borrowers cut spending in turn.","exampleCN":"银行提高了利率，借款人也随之削减开支。","why":"A return travels back to a giver; a turn passes forward along a chain.","whyCN":"回报是回到给予者那里，轮转则沿链条向前传递。"},{"no":"04","title":"Not alternation","titleCN":"辨义：不同于交替","definition":"it orders a sequence once through, while the phrase with the plural noun describes repeated alternation","definitionCN":"它把序列走一遍，而带复数名词的短语描述反复交替","example":"The lights flashed red and green in turn.","exampleCN":"两盏灯依次闪红与绿。","why":"A single pass through the positions differs from switching back and forth many times.","whyCN":"把各个位置走一遍，与来回反复切换并不相同。"},{"no":"05","title":"A line of work","titleCN":"流程义：工序依次传递","definition":"in production or administration it describes each station passing work to the next","definitionCN":"在生产或行政中，描述各道工序把工作交给下一道","example":"Each station passes the part to the next in turn.","exampleCN":"每道工位依次把零件交给下一道。","why":"Assembly is a physical circle of hands, the clearest picture behind the phrase.","whyCN":"装配正是一圈传递的手，这是短语背后最清楚的画面。"},{"no":"06","title":"A chain in an argument","titleCN":"学术义：论证中的连锁","definition":"in analysis it links a cause to a further effect, usually inside a relative clause","definitionCN":"在分析中把原因接到更远的后果上，通常出现在定语从句里","example":"Funding fell, which in turn slowed the repairs.","exampleCN":"经费削减，这又拖慢了维修。","why":"Research prose needs to show chains, and the frame keeps each link visible.","whyCN":"研究文字需要展示链条，这个框架让每一环都看得见。"},{"no":"07","title":"Taking the floor in order","titleCN":"程序义：依次发言或办理","definition":"in meetings and formal procedure it means each participant acts in an agreed order","definitionCN":"在会议与正式程序中，指每位参与者按约定次序行事","example":"The delegates spoke in turn, each for five minutes.","exampleCN":"代表们依次发言，每人五分钟。","why":"Procedure is a rotation of rights, and the phrase keeps the order neutral.","whyCN":"程序是权利的轮转，这个短语让次序保持中性。"},{"no":"08","title":"Not a physical spin","titleCN":"辨义：不表物体转动","definition":"the phrase orders events or effects; it does not describe a wheel or a handle going round","definitionCN":"这个短语排列事件或后果，不描述轮子或把手转动","example":"In turn marks order or consequence, never the physical spin of a wheel.","exampleCN":"依次与反过来标记的是顺序或后果，从不指轮子的物理旋转。","why":"The noun kept its rotation sense, but the fixed phrase froze only the ordering sense.","whyCN":"名词保留了旋转义，但固定短语只冻结了排序义。"}],"etymology":{"intro":{"en":"Turn reached English from Old French torner and Old English turnian, both going back to Latin tornare, to turn on a lathe, from Greek tornos, a lathe. The line is clear; the pre-Greek origin is uncertain.","cn":"turn 经古法语 torner 与古英语 turnian 两条线进入英语，两者都可回溯到拉丁语 tornare「在车床上旋削」，再往上为希腊语 tornos「车床」。脉络清楚；这个希腊词更早的来源不确定。"},"items":[{"era":"GREEK TORNOS","en":"Tornos named a lathe, the tool that makes a piece turn while a blade cuts it.","cn":"tornos 指车床，一种让工件旋转、同时用刀切削的工具。"},{"era":"PRE-GREEK ORIGIN UNCERTAIN","en":"Where the Greek noun itself came from is disputed, and the source is uncertain.","cn":"这个希腊名词本身从何而来尚有争议，来源不确定。"},{"era":"LATIN TORNARE","en":"The Latin verb meant to turn on a lathe and then to turn more generally.","cn":"拉丁语动词本指在车床上旋削，后泛指转动。"},{"era":"TWO ENGLISH STRANDS","en":"A native Old English verb and a French loan merged, giving English one strong turn.","cn":"古英语本族动词与法语借词合并，给英语留下一个强势的 turn。"},{"era":"THE FIXED PHRASE","en":"The ordering and consequence senses are modern developments; first dates are approximate.","cn":"依次与递进两义属近代发展，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the noun but means response, alternation or strict sequence; the second group are adverbs of succession and linkage.","cn":"第一组共用这个名词，却表回报、交替或严格序列；第二组是表相继与连接的副词性说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in return","ipa":"/ɪn rɪˈtɜːn/","tag":"reciprocity","definition":"It means as a response or a repayment.","definitionCN":"意为作为回应或回报。"},{"word":"by turns","ipa":"/baɪ ˈtɜːnz/","tag":"alternation","definition":"It describes alternating states, often repeatedly.","definitionCN":"描述交替出现的状态，常反复进行。"},{"word":"take turns","ipa":"/teɪk ˈtɜːnz/","tag":"verb phrase","definition":"It means people replace one another in doing something.","definitionCN":"指人们轮流做某事。"},{"word":"in sequence","ipa":"/ɪn ˈsiːkwəns/","tag":"strict order","definition":"It stresses a fixed order with no idea of effect.","definitionCN":"强调固定顺序，不含相互影响之意。"}]},{"heading":"NEAR MEANING","entries":[{"word":"successively","ipa":"/səkˈsesɪvli/","tag":"one after another","definition":"A single adverb for consecutive items.","definitionCN":"单个副词，表接连发生。"},{"word":"respectively","ipa":"/rɪˈspektɪvli/","tag":"matched order","definition":"It pairs two lists in the same order.","definitionCN":"把两份列表按同一顺序对应。"},{"word":"and then","ipa":"/ænd ðen/","tag":"sequence","definition":"It simply moves the narrative to the next step.","definitionCN":"只是把叙述推进到下一步。"},{"word":"which leads to","ipa":"/wɪtʃ liːdz tuː/","tag":"consequence","definition":"It turns the effect into a relative clause.","definitionCN":"把结果写成定语从句。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real lathe root, the real split from return and alternation, and the real chain grammar.","cn":"正常联想用真实的车床词根、与回报及交替的分工，以及真实的连锁语法。"},"normal":[{"en":"A lathe turns a piece so each side faces the blade once.","cn":"车床让工件转动，使每一面都各对着刀一次。"},{"en":"A circle hands motion to the next point, so order becomes cause.","cn":"圆环把运动交给下一点，于是顺序变成因果。"},{"en":"Return travels back to a giver; turn travels forward along a chain.","cn":"回报回到给予者，轮转沿链条向前。"},{"en":"One pass through the positions is not repeated alternation.","cn":"把位置走一遍，不等于反复交替。"},{"en":"The fixed phrase froze the ordering sense and dropped the spin.","cn":"固定短语冻结了排序义，丢掉了旋转义。"}],"abstract":[{"en":"Like a bucket passed hand to hand down a line of workers.","cn":"像水桶在工人队列里一双手一双手地传下去。"},{"en":"Like gears: each wheel moves the next, and the last moves the first.","cn":"像齿轮：每个轮带动下一个，最后一个又带动第一个。"},{"en":"Like speakers at a long table taking the floor in a fixed order.","cn":"像长桌旁的人按固定次序依次发言。"}]},"examples":[{"en":"The three witnesses were questioned in turn.","cn":"三名证人依次受到询问。"},{"en":"Cheaper parts cut costs, which in turn raised demand.","cn":"更便宜的零件降低了成本，这又反过来提升了需求。"},{"en":"Each member of the panel spoke in turn.","cn":"小组成员依次发言。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 特恩」——水桶一双手一双手往下传：依次、反过来","word":"in turn"},"root":"核心动词意为转动，经古法语 torner 与古英语 turnian 两条线汇合，最终出自拉丁语 tornare「在车床上旋削」，源自希腊语 tornos「车床」；该希腊词更早来源不确定。该短语的依次与递进义为近代发展，首见年代不确定。","sensesIntro":{"en":"Eight senses separate ordered succession, chained causation, the contrast with return, the contrast with alternation, production lines, argument chains, formal procedure and the exclusion of physical rotation.","cn":"八个义项区分：有序相继、连锁因果、与回报的对照、与交替的对照、生产线、论证链条、正式程序，以及排除物理旋转。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bucket passed from hand to hand down a line of workers until it reaches the last pair.","cn":"核心意象：一只水桶在工人队列里一双手传一双手，直到最后一双手。"},"chain":["LATHE","CIRCLE","ROTATE","SUCCESSION","RECIPROCAL EFFECT","ORDER"],"branches":[{"senses":"01 · 05","en":"THE SUCCESSION: a line of people or stations takes each position once.","cn":"相继：一列人或工位把每个位置各走一次。"},{"senses":"02 · 06","en":"THE CHAIN: an effect becomes the cause of the next step, and analysis shows every link.","cn":"连锁：一个后果成为下一步的原因，分析要显示每一环。"},{"senses":"03","en":"THE CONTRAST: a repayment returns to the giver, not forward along the line.","cn":"对照：回报回到给予者，而非沿队列向前。"},{"senses":"04","en":"THE CONTRAST: one pass through the positions differs from repeated alternation.","cn":"对照：走一遍位置不同于反复交替。"},{"senses":"07 · 08","en":"THE PROCEDURE AND THE LIMIT: meetings rotate the right to speak, and no wheel is spinning.","cn":"程序与边界：会议轮转发言权，且不指轮子旋转。"}]},"affixes":{"intro":{"en":"The phrase is built on a verb that came into English from two directions but from one Latin lathe-word.","cn":"这个短语建在一个动词上，该动词从两个方向进入英语，却同出一个拉丁语车床词。"},"latinIntro":{"en":"Latin tornare, to turn on a lathe, comes from Greek tornos, a lathe; the Latin verb reached English through French and through native development.","cn":"拉丁语 tornare「在车床上旋削」出自希腊语 tornos「车床」；这个拉丁动词经法语与本族发展两条路进入英语。"},"items":[{"word":"tornos","structure":"Greek noun","meaning":"a lathe","meaningCN":"车床","example":"The tool that rotates the work while a blade cuts.","exampleCN":"一种让工件旋转、同时用刀切削的工具。"},{"word":"tornare","structure":"Latin verb","meaning":"to turn on a lathe","meaningCN":"在车床上旋削","example":"The verb widened from craft to general turning.","exampleCN":"这个动词从手艺扩展到一般转动。"},{"word":"turn","structure":"English noun and verb","meaning":"to rotate; a rotation; a chance","meaningCN":"转动；轮次；机会","example":"English keeps rotation, order and opportunity in one word.","exampleCN":"英语用同一个词兼指旋转、次序与机会。"},{"word":"turning","structure":"turn + -ing","meaning":"a bend; a point of change","meaningCN":"转弯处；转折点","example":"The noun names where a path or an event changes direction.","exampleCN":"这个名词指路径或事件转向之处。"},{"word":"turnover","structure":"turn + over","meaning":"revenue; replacement of staff","meaningCN":"营业额；人员更替","example":"The compound pictures things turning over.","exampleCN":"这个复合词描绘东西翻过去。"},{"word":"turnout","structure":"turn + out","meaning":"attendance; output","meaningCN":"出席人数；产量","example":"It names how many come out to an event.","exampleCN":"它指有多少人出来参加活动。"},{"word":"turnaround","structure":"turn + around","meaning":"a reversal; a recovery","meaningCN":"周转；好转","example":"The compound marks a full change of direction.","exampleCN":"这个复合词标出方向的整体改变。"},{"word":"in turn","structure":"preposition + noun","meaning":"in order; conversely","meaningCN":"依次；反过来","example":"The frame is standard in process description.","exampleCN":"这个框架在流程描述中是标准用法。"},{"word":"by turns","structure":"preposition + plural noun","meaning":"alternately","meaningCN":"交替地","example":"The plural form marks repeated switching.","exampleCN":"复数形式标出反复切换。"}],"latinEntries":[{"word":"tornare","structure":"tornare, tornavi, tornatum (verb, first conjugation, from Greek)","meaning":"to turn on a lathe","meaningCN":"在车床上旋削"}],"derivatives":[{"word":"turn","pos":"n./v.","zh":"转动；轮次"},{"word":"turning","pos":"n.","zh":"转弯处"},{"word":"turnover","pos":"n.","zh":"营业额；人员更替"},{"word":"turnout","pos":"n.","zh":"出席人数"},{"word":"turnaround","pos":"n.","zh":"周转；好转"}]}},{"word":"in particular","ipa_uk":"/ɪn pəˈtɪkjələ/","ipa_us":"/ɪn pərˈtɪkjələr/","definition_zh":"尤其、特别是；具体来说（用于从整体中突出某一例或某一项）","definition_en":"especially; more than others; specifically","core_image":"一排同样的灯泡里，只有一只被手指点亮","scene":"检查组走过整条生产线，最后停在最旧的冲压机前，那里的油污最重。The inspectors found several faults, in particular a cracked guard on the oldest press.","sceneCN":"这里取「尤其、特别是」（第 1 个义项：从整体中挑出突出的一项）；句意为检查人员发现若干缺陷，尤其是最旧那台冲压机上开裂的护罩。","pos":[{"tag":"adv. phr.","zh":"副词短语：尤其；特别是"}],"collocations":[{"phrase":"and in particular","zh":"尤其是"},{"phrase":"in particular for","zh":"尤其对于"},{"phrase":"one in particular","zh":"其中特别的一个"},{"phrase":"nothing in particular","zh":"没什么特别的"},{"phrase":"in particular the case of","zh":"尤其是……的情形"},{"phrase":"in particular among","zh":"尤其在……之中"}],"forms":[{"label":"原形","form":"in particular"},{"label":"句首形式","form":"In particular,"},{"label":"强调形式","form":"and in particular"},{"label":"后置形式","form":"the one in particular"}],"derivatives":[{"word":"particular","pos":"adj.","zh":"特定的；讲究的；挑剔的"},{"word":"particularly","pos":"adv.","zh":"尤其；特别"},{"word":"particularity","pos":"n.","zh":"特殊性；细节"},{"word":"particularize","pos":"v.","zh":"具体说明"},{"word":"particulars","pos":"n.","zh":"细节；详细资料"}],"senses":[{"no":"01","title":"A singled-out example","titleCN":"突出例证义：从整体挑出一项","definition":"used to pick one member out of a group and give it special weight","definitionCN":"用来从一组中挑出一个成员，并给它额外的分量","example":"The region is dry, in particular in its eastern valleys.","exampleCN":"这个地区干燥，尤其是东部山谷。","why":"Particular names one part, so the phrase lifts one part out of the whole for attention.","whyCN":"这个词本指某一部分，因此短语把其中一部分从整体中提出来加以关注。"},{"no":"02","title":"Beside the single adverb","titleCN":"语法边界：与单词副词的分工","definition":"the phrase marks a noun phrase or a closing item, while the single adverb usually modifies an adjective or a verb","definitionCN":"这个短语标出名词短语或收束项，而单词副词通常修饰形容词或动词","example":"Tourism grew, in particular after the new road opened.","exampleCN":"旅游业增长了，尤其是在新路开通之后。","why":"A frame that takes a complement differs from an adverb that leans on another word.","whyCN":"带补语的框架不同于依附另一个词的副词。"},{"no":"03","title":"Against the broad view","titleCN":"对照义：与总体说法相对","definition":"it narrows a general statement to one case, which is why it often follows a summary","definitionCN":"把笼统陈述收窄到一个事例，因此常跟在概括之后","example":"In general the soil is poor, and in particular it lacks lime.","exampleCN":"土壤总体贫瘠，尤其缺石灰。","why":"A general claim invites an exception, and the phrase supplies the sharpest one.","whyCN":"笼统说法会引出例外，这个短语提供的正是最鲜明的例外。"},{"no":"04","title":"After a noun","titleCN":"后置义：直接限定名词","definition":"placed after a noun it means that this one, above the others, is the case meant","definitionCN":"放在名词之后，表示在所有当中所指的正是这一个","example":"One building in particular was damaged beyond repair.","exampleCN":"其中有一栋建筑损坏得无法修复。","why":"English can postpose the frame, making the singled-out noun stand first for emphasis.","whyCN":"英语可把这个框架后置，让被挑出的名词先出现以加强语气。"},{"no":"05","title":"Opening emphasis","titleCN":"句首义：在句首加重","definition":"at the start of a sentence it announces that the next detail matters most","definitionCN":"放在句首，预告接下来的细节最为要紧","example":"In particular, the panel asked about the missing receipts.","exampleCN":"小组尤其追问了那些缺失的收据。","why":"A front position changes the rhythm, slowing the reader before the key item.","whyCN":"前置改变节奏，在关键项之前让读者放慢。"},{"no":"06","title":"Naming the detail","titleCN":"具体化义：具体列举","definition":"it introduces a precise item after a plural or a category, functioning as a short list of one","definitionCN":"在复数或类别之后引出具体一项，相当于只有一项的清单","example":"Several costs rose, in particular fuel and freight.","exampleCN":"若干成本上升，尤其是燃料与运费。","why":"A category is vague until a member is named, and the phrase performs that naming.","whyCN":"类别在被点出成员之前是模糊的，这个短语完成那次点名。"},{"no":"07","title":"Not fussiness","titleCN":"辨义：不表讲究或挑剔","definition":"the noun can describe a person who insists on details, but the phrase only marks emphasis","definitionCN":"这个名词可形容对细节挑剔的人，但短语只表强调","example":"The report was praised, in particular for its clear tables.","exampleCN":"这份报告受到称赞，尤其是其清晰的表格。","why":"The adjective has an evaluative sense that the fixed phrase never carries.","whyCN":"形容词带有评价义，而固定短语从不承载它。"},{"no":"08","title":"The closing item","titleCN":"收束义：列举末项加重","definition":"in a list it often weights the last item, giving the sentence a deliberate finish","definitionCN":"在列举中常给最后一项加重，使句子有意收尾","example":"Three factors mattered: cost, timing, and in particular staffing.","exampleCN":"三个因素要紧：成本、时机，尤其是人员配备。","why":"End weight is natural in English, so the phrase fits the final slot without strain.","whyCN":"英语天然重心后置，因此这个短语放在末位毫不勉强。"}],"etymology":{"intro":{"en":"Particular comes from Latin particularis, relating to a single part, from particula, a small part, a diminutive of pars, part. The Latin chain is secure; the phrase is modern.","cn":"particular 来自拉丁语 particularis「关于某一部分的」，其词根 particula 是 pars「部分」的小称。拉丁语链条清楚；短语属近代。"},"items":[{"era":"LATIN PARS","en":"Pars meant a part or a share, and it is one of the most productive roots in English.","cn":"pars 意为部分、份额，是英语中构词能力最强的词根之一。"},{"era":"PARTICULA","en":"The diminutive named a small part, the unit into which a whole is divided.","cn":"这个指小形式指一小部分，即整体所分成的单元。"},{"era":"PARTICULARIS","en":"The adjective described what belongs to one part rather than to the whole.","cn":"这个形容词描述属于某一部分而非整体的东西。"},{"era":"THE FUSSY SENSE","en":"Later English added the sense of a person hard to please in small matters.","cn":"英语后来加上对小事难以取悦的人这一义。"},{"era":"THE FIXED PHRASE","en":"The emphasis frame belongs to modern prose; first dates are approximate.","cn":"这个强调框架属于近代文字，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the form or the emphasis but differs in grammar or sense; the second group are single words of emphasis.","cn":"第一组共用形式或强调功能，但语法或意义不同；第二组是表强调的单词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"particularly","ipa":"/pəˈtɪkjələli/","tag":"adverb","definition":"It modifies an adjective or verb instead of a noun phrase.","definitionCN":"它修饰形容词或动词，而非名词短语。"},{"word":"in detail","ipa":"/ɪn ˈdiːteɪl/","tag":"full treatment","definition":"It means thoroughly, not especially.","definitionCN":"意为详尽地，而非尤其。"},{"word":"in person","ipa":"/ɪn ˈpɜːsn/","tag":"bodily presence","definition":"It means physically present, with no idea of emphasis.","definitionCN":"指亲自到场，不含强调意味。"},{"word":"of note","ipa":"/əv nəʊt/","tag":"worth attention","definition":"It marks something worth noticing.","definitionCN":"标记值得注意的事物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"especially","ipa":"/ɪˈspesʃəli/","tag":"general emphasis","definition":"The commonest word for singling something out.","definitionCN":"最常用的突出单项的词。"},{"word":"notably","ipa":"/ˈnəʊtəbli/","tag":"worthy of note","definition":"It marks a case worth mentioning, often in reports.","definitionCN":"标出值得一提的案例，多用于报告。"},{"word":"specifically","ipa":"/spəˈsɪfɪkli/","tag":"precise identification","definition":"It narrows to an exact item rather than weighting it.","definitionCN":"收窄到确切项，而非加重它。"},{"word":"above all","ipa":"/əˈbʌv ɔːl/","tag":"highest priority","definition":"It ranks one item above every other.","definitionCN":"把一项排在其余一切之上。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real part-root, the later fussy sense, and the real grammar of noun phrase and adverb.","cn":"正常联想用真实的部分词根、后来的挑剔义，以及名词短语与副词的真实语法。"},"normal":[{"en":"A part is lifted out of the whole, and the phrase does the lifting.","cn":"一部分被从整体中提出来，这个短语完成提起的动作。"},{"en":"A noun phrase follows it; a single adverb leans on another word instead.","cn":"它后接名词短语；单词副词则依附另一个词。"},{"en":"After a summary, it supplies the sharpest exception.","cn":"跟在概括之后，它给出最鲜明的例外。"},{"en":"Placed after a noun, it makes that noun stand first.","cn":"放在名词之后，它让那个名词先站出来。"},{"en":"The fussy sense belongs to the adjective, never to the frame.","cn":"挑剔义属于形容词，从不属于这个框架。"}],"abstract":[{"en":"Like one bulb lit in a row of identical lamps.","cn":"像一排同样的灯里只点亮一只。"},{"en":"Like a finger pointing at one line in a long list.","cn":"像手指点在长清单的某一行上。"},{"en":"Like a magnifying glass held over a single word on a page.","cn":"像放大镜停在一页纸的某一个词上。"}]},"examples":[{"en":"The climate is mild, in particular near the coast.","cn":"气候温和，尤其近海一带。"},{"en":"One detail in particular caught the reviewer's eye.","cn":"有一个细节特别引起了审阅者的注意。"},{"en":"Costs rose, in particular in the second quarter.","cn":"成本上升，尤其在第二季度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 帕提扣勒」——一排灯里只点亮一只：尤其、特别是","word":"in particular"},"root":"核心形容词意为特定的，出自拉丁语 particularis「关于某一部分的」，其词根 particula 是 pars「部分」的小称。该短语表「尤其」为近代用法，首见年代不确定。","sensesIntro":{"en":"Eight senses cover a singled-out example, the boundary against the adverb, the contrast with a general claim, postposed emphasis, sentence-opening weight, concrete naming, the exclusion of fussiness and the closing item.","cn":"八个义项涵盖：突出例证、与副词的语法边界、与总体说法的对照、后置强调、句首加重、具体点名、排除挑剔义，以及列举收束项。"},"semanticMap":{"core":{"en":"CORE IMAGE: one bulb lit among a row of identical lamps, a finger resting on the switch.","cn":"核心意象：一排同样的灯里只点亮一只，手指停在开关上。"},"chain":["PART","SMALL PART","SINGLE ITEM","SELECTED CASE","EMPHASIS","DETAIL"],"branches":[{"senses":"01 · 05","en":"THE SELECTION: one member is lifted out and given the weight of the sentence.","cn":"挑选：一个成员被提出来，承担句子的分量。"},{"senses":"02 · 07","en":"THE FORM: a frame takes a noun phrase, and no fussiness is implied.","cn":"形式：框架后接名词短语，且不含挑剔义。"},{"senses":"03","en":"THE CONTRAST: a broad claim is narrowed to its sharpest exception.","cn":"对照：笼统主张被收窄到最鲜明的例外。"},{"senses":"04","en":"THE POSITION: after a noun, the singled-out item comes first.","cn":"位置：放在名词之后，被挑出的项先出现。"},{"senses":"06 · 08","en":"THE DETAIL: a category becomes concrete, and a list gains a weighted ending.","cn":"细节：类别变得具体，列举获得有分量的收尾。"}]},"affixes":{"intro":{"en":"The phrase rests on a Latin adjective of one part, whose root for part runs through a large English family.","cn":"这个短语建在一个表某一部分的拉丁语形容词上，其部分词根贯穿一大批英语词。"},"latinIntro":{"en":"Latin pars, part, gives the diminutive particula, small part, and the adjective particularis.","cn":"拉丁语 pars「部分」给出小称 particula「小部分」与形容词 particularis。"},"items":[{"word":"pars","structure":"Latin noun, third declension","meaning":"a part; a share","meaningCN":"部分；份额","example":"The root supplies part, partial and particle alike.","exampleCN":"这个词根给出部分、偏的、微粒等词。"},{"word":"particula","structure":"Latin diminutive noun","meaning":"a small part","meaningCN":"小部分；微粒","example":"The diminutive names the smallest unit of a whole.","exampleCN":"指小形式指整体中最小的单元。"},{"word":"particularis","structure":"Latin adjective","meaning":"of one part","meaningCN":"关于某一部分的","example":"The adjective limits attention to a single portion.","exampleCN":"这个形容词把注意力限到单独一份。"},{"word":"particular","structure":"English adjective and noun","meaning":"specific; fussy; a detail","meaningCN":"特定的；讲究的；细节","example":"English added the fussy sense later.","exampleCN":"英语后来加上挑剔义。"},{"word":"particularly","structure":"particular + -ly","meaning":"especially","meaningCN":"尤其","example":"The adverb carries the emphasis in ordinary prose.","exampleCN":"副词在普通文字中承担强调。"},{"word":"particularity","structure":"particular + -ity","meaning":"specific character","meaningCN":"特殊性","example":"The noun names what makes one case distinct.","exampleCN":"这个名词指使某案例独特之处。"},{"word":"particulars","structure":"plural noun","meaning":"details of a case","meaningCN":"细节；详细资料","example":"The plural gathers the small parts of a record.","exampleCN":"复数汇集一份记录的小部分。"},{"word":"in particular","structure":"preposition + adjective","meaning":"especially","meaningCN":"尤其","example":"The frame is standard in emphasis.","exampleCN":"这个框架是强调的标准形式。"},{"word":"nothing in particular","structure":"fixed negative phrase","meaning":"no special thing","meaningCN":"没什么特别的","example":"The negative frame cancels the selection.","exampleCN":"否定框架取消了挑选。"}],"latinEntries":[{"word":"pars","structure":"pars, partis (noun, third declension)","meaning":"a part; a share","meaningCN":"部分；份额"},{"word":"particula","structure":"particula, -ae (noun, first declension, diminutive)","meaning":"a small part","meaningCN":"小部分"},{"word":"particularis","structure":"particularis, -e (adjective)","meaning":"of one part","meaningCN":"关于某一部分的"}],"derivatives":[{"word":"particular","pos":"adj.","zh":"特定的；挑剔的"},{"word":"particularly","pos":"adv.","zh":"尤其"},{"word":"particularity","pos":"n.","zh":"特殊性"},{"word":"particularize","pos":"v.","zh":"具体说明"},{"word":"particulars","pos":"n.","zh":"细节"}]}},{"word":"in general","ipa_uk":"/ɪn ˈdʒenrəl/","ipa_us":"/ɪn ˈdʒenrəl/","definition_zh":"总体上、一般说来；就整体而言（允许个别例外）","definition_en":"usually; considering the whole rather than details or exceptions","core_image":"一只手掌摊开，五根手指整体朝上，指缝间还留有空隙","scene":"市场调查员翻完整本记录，说多数顾客满意，但也指出投诉集中在退换货。Customers are satisfied in general, though returns remain a sore point.","sceneCN":"这里取「总体上、一般说来」（第 1 个义项：就整体而言，允许例外）；句意为顾客总体满意，但退货仍是痛点。","pos":[{"tag":"adv. phr.","zh":"副词短语：总体上；一般说来"}],"collocations":[{"phrase":"in general terms","zh":"概括地说"},{"phrase":"people in general","zh":"一般人"},{"phrase":"the public in general","zh":"广大公众"},{"phrase":"in general, however","zh":"不过总体上"},{"phrase":"in general and in particular","zh":"总体与个别"},{"phrase":"matters in general","zh":"一般事务"}],"forms":[{"label":"原形","form":"in general"},{"label":"句首形式","form":"In general,"},{"label":"后置形式","form":"people in general"},{"label":"对照形式","form":"in general and in particular"}],"derivatives":[{"word":"general","pos":"adj./n.","zh":"总的；普遍的；将军"},{"word":"generally","pos":"adv.","zh":"通常；一般地"},{"word":"generalize","pos":"v.","zh":"概括；归纳"},{"word":"generalization","pos":"n.","zh":"概括；泛论"},{"word":"generality","pos":"n.","zh":"普遍性；概略"},{"word":"generalship","pos":"n.","zh":"将才；指挥才能"}],"senses":[{"no":"01","title":"The broad view","titleCN":"总体义：就整体而言","definition":"used to state what is true of a whole group, while allowing individual exceptions","definitionCN":"用来陈述对整个群体成立的情况，同时容许个别例外","example":"In general, the climate is mild, but winters can be harsh.","exampleCN":"总体而言气候温和，但冬季可能严寒。","why":"General belongs to the whole kind, so the phrase speaks for the group rather than for each member.","whyCN":"这个词属于整个类别，因此短语代表群体说话，而非逐个成员。"},{"no":"02","title":"Beside the single adverb","titleCN":"语法边界：与单词副词的分工","definition":"the frame stands as a sentence adverbial, while the single adverb often sits inside the clause","definitionCN":"这个框架作句子状语，而单词副词常位于小句内部","example":"Prices in general have risen faster than wages.","exampleCN":"物价总体上涨得比工资快。","why":"A sentence-level comment differs from a manner adverb attached to one verb.","whyCN":"句子层面的评述不同于依附单个动词的方式副词。"},{"no":"03","title":"Against one case","titleCN":"对照义：与个别突出相对","definition":"it states the wide pattern, and the contrasting phrase then selects the exception","definitionCN":"它陈述宽泛的格局，对照短语随后挑出例外","example":"In general the plan is sound; in particular the budget needs work.","exampleCN":"总体看方案稳妥，尤其是预算还需加工。","why":"A pattern needs a contrast to be useful, and the pair supplies both ends.","whyCN":"格局需要对照才有用，这一对短语正好提供两端。"},{"no":"04","title":"The sentence opener","titleCN":"句首义：开启概括","definition":"at the start of a sentence it warns the reader that a summary follows","definitionCN":"放在句首，提示读者接下来是概括","example":"In general, students prefer morning classes.","exampleCN":"一般说来，学生更喜欢上午的课。","why":"Opening position sets the frame before the detail arrives, which is why summaries begin this way.","whyCN":"前置位置在细节到来前先设好框架，因此概括常这样开头。"},{"no":"05","title":"True with exceptions","titleCN":"例外义：大体成立但有例外","definition":"it claims a tendency, not a law, and so leaves room for cases that do not fit","definitionCN":"它主张一种倾向而非定律，因此给不合的例子留了余地","example":"The machine is reliable in general, yet it fails in cold weather.","exampleCN":"这台机器总体可靠，却在寒冷天气里失灵。","why":"A tendency can be real without covering every instance, and the phrase marks exactly that strength.","whyCN":"倾向可以真实存在而不覆盖每一例，这个短语标的正是那种力度。"},{"no":"06","title":"Like a whole-view phrase","titleCN":"近义辨析：与整体评说相近","definition":"it resembles the phrase meaning on the whole, though it sounds slightly more formal and abstract","definitionCN":"它与表整体评说的短语相近，只是听来更正式、更抽象","example":"In general, the two accounts agree.","exampleCN":"总体而言，两种叙述是一致的。","why":"Both weigh the whole, but one sounds like a judgement and the other like a summary.","whyCN":"两者都权衡整体，但一个像判断，另一个像概述。"},{"no":"07","title":"A whole group of people","titleCN":"群体义：指某一类人的整体","definition":"placed after a plural noun it means the members of that group taken together","definitionCN":"放在复数名词之后，指该群体的成员合起来看","example":"People in general are wary of sudden changes.","exampleCN":"一般人对突然的变化都心存戒备。","why":"Here the phrase works inside a noun phrase, showing that general can attach to a group as well as to a clause.","whyCN":"此处短语位于名词短语内部，说明这个词既能挂在小句上，也能挂在群体上。"},{"no":"08","title":"Not the military rank","titleCN":"辨义：不表军衔","definition":"the noun can name an officer of high rank, but the phrase only makes a broad statement","definitionCN":"这个名词可指高级军官，但短语只作宽泛陈述","example":"In general marks a broad view, not a military rank.","exampleCN":"总体而言一语标的是宽泛视角，不是军衔。","why":"The rank sense grew from the adjective, and the fixed phrase kept only the adjective.","whyCN":"军衔义由形容词发展而来，固定短语只保留形容词义。"}],"etymology":{"intro":{"en":"General comes from Latin generalis, belonging to a whole kind, from genus, kind or stock. The Latin chain is secure; the phrase is modern.","cn":"general 来自拉丁语 generalis「属于整个类别的」，词根 genus 意为种类、族属。拉丁语链条清楚；短语属近代。"},"items":[{"era":"LATIN GENUS","en":"Genus named a kind, a race or a stock, and it stands behind generation and genre as well.","cn":"genus 指种类、族属或血统，也支撑着 generation 与 genre 等词。"},{"era":"GENERALIS","en":"The adjective marked what applies to the whole kind rather than to one member.","cn":"这个形容词标出适用于整个类别而非单个成员的东西。"},{"era":"OLD FRENCH GENERAL","en":"French used the word for common or universal before English borrowed it.","cn":"法语先用这个词表共同、普遍，英语随后借入。"},{"era":"THE RANK","en":"A commander of the whole force took the adjective as a title, giving the military noun.","cn":"统领全军者以这个形容词为称号，由此产生军衔名词。"},{"era":"THE FIXED PHRASE","en":"The summarising frame belongs to modern prose; first dates are approximate.","cn":"这个概括框架属于近代文字，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the root or the summarising job but differs in grammar or scope; the second group are adverbs and phrases of broad statement.","cn":"第一组共用词根或概括功能，但语法或范围不同；第二组是表宽泛陈述的副词与短语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"generally","ipa":"/ˈdʒenrəli/","tag":"adverb","definition":"It usually modifies a verb and means normally.","definitionCN":"通常修饰动词，意为一般地。"},{"word":"in general terms","ipa":"/ɪn ˈdʒenrəl tɜːmz/","tag":"summary register","definition":"It means stated broadly, without figures.","definitionCN":"意为笼统陈述，不给具体数字。"},{"word":"in the main","ipa":"/ɪn ðə meɪn/","tag":"mostly","definition":"It means for the most part, slightly literary.","definitionCN":"意为大体上，略偏书面。"},{"word":"as a whole","ipa":"/æz ə həʊl/","tag":"whole unit","definition":"It treats something as one unit rather than as members.","definitionCN":"把事物当作一个整体，而非各个成员。"}]},{"heading":"NEAR MEANING","entries":[{"word":"on the whole","ipa":"/ɒn ðə həʊl/","tag":"weighing everything","definition":"A judgement after balancing the parts.","definitionCN":"权衡各部分之后作出的判断。"},{"word":"broadly","ipa":"/ˈbrɔːdli/","tag":"wide statement","definition":"It marks a statement made at a wide angle.","definitionCN":"标出从宽泛角度作出的陈述。"},{"word":"usually","ipa":"/ˈjuːʒuəli/","tag":"frequency","definition":"It concerns how often, not how widely.","definitionCN":"说的是频次，而非覆盖面。"},{"word":"by and large","ipa":"/baɪ ænd ˈlɑːdʒ/","tag":"informal summary","definition":"A conversational way to say mostly.","definitionCN":"口语中表大体上。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real kind-root, the later military title and the real grammar of sentence adverbial and postposed group.","cn":"正常联想用真实的种类词根、后来的军衔称号，以及句子状语与后置群体的真实语法。"},"normal":[{"en":"A kind is a whole class, so the phrase speaks for the class, not each member.","cn":"种类是整个类别，因此短语为类别说话，而非逐个成员。"},{"en":"A sentence adverbial frames the claim, while a manner adverb touches one verb.","cn":"句子状语为陈述设框，方式副词只碰一个动词。"},{"en":"A tendency can be true without covering every case.","cn":"倾向可以成立，而不覆盖每一例。"},{"en":"After a plural noun, it gathers the members into one body.","cn":"放在复数名词后，它把成员聚成一个整体。"},{"en":"The rank came from the adjective, and the frame kept only the adjective.","cn":"军衔来自形容词，而这个框架只保留形容词。"}],"abstract":[{"en":"Like an open palm seen from above: five fingers counted as one hand.","cn":"像从上方看一只摊开的手掌：五根指头算作一只手。"},{"en":"Like a map at a wide zoom, where streets vanish and the shape of the country shows.","cn":"像缩小很多的地图：街道消失，国形显现。"},{"en":"Like a group photograph in which no single face is the subject.","cn":"像一张合影，其中没有哪张脸是主角。"}]},"examples":[{"en":"In general, the soil here drains quickly.","cn":"总体而言，这里的土壤排水很快。"},{"en":"The staff in general welcomed the change.","cn":"员工总体上欢迎这一变动。"},{"en":"In general, the older buildings need more repair.","cn":"一般说来，较旧的建筑需要更多维修。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 健若」——摊开的手掌，五根指头算作一只手：总体上","word":"in general"},"root":"核心形容词意为总体的，出自拉丁语 generalis「属于整个类别的」，词根 genus 意为种类、族属。该短语表总体上为近代定型，首见年代不确定。","sensesIntro":{"en":"Eight senses separate the broad view, the boundary against the adverb, the contrast with one case, the sentence opener, truth with exceptions, the near twin, a whole group of people and the exclusion of the military rank.","cn":"八个义项区分：总体视角、与副词的语法边界、与个别案例的对照、句首开篇、容许例外、近义整体评说、指群体整体，以及排除军衔义。"},"semanticMap":{"core":{"en":"CORE IMAGE: an open palm seen from above, five fingers counted together as one hand.","cn":"核心意象：从上方看一只摊开的手掌，五根指头合起来算一只手。"},"chain":["KIND","WHOLE CLASS","COMMON","BROAD VIEW","EXCEPTION ALLOWED","GROUP"],"branches":[{"senses":"01 · 04","en":"THE SUMMARY: a whole class is described before any detail arrives.","cn":"概括：在细节到来前先描述整个类别。"},{"senses":"02","en":"THE GRAMMAR: a sentence adverbial frames a claim, unlike an adverb on one verb.","cn":"语法：句子状语为陈述设框，不同于依附单个动词的副词。"},{"senses":"03 · 08","en":"THE CONTRASTS: an exception can be selected, and no military rank is meant.","cn":"对照：可以挑出例外，且不指军衔。"},{"senses":"05 · 06","en":"THE STRENGTH: a tendency holds without covering every case.","cn":"力度：倾向成立而不覆盖每一例。"},{"senses":"07","en":"THE GROUP: after a plural noun the phrase gathers the members together.","cn":"群体：放在复数名词后，把成员聚在一起。"}]},"affixes":{"intro":{"en":"The phrase rests on a Latin adjective of a whole kind, whose root for kind is shared across many English words.","cn":"这个短语建在一个表整个类别的拉丁语形容词上，其种类词根为许多英语词共用。"},"latinIntro":{"en":"Latin genus, kind, gives generalis, of the whole kind; English also took the noun as a military title.","cn":"拉丁语 genus「种类」给出 generalis「属于整个类别的」；英语还把这个名词用作军衔称号。"},"items":[{"word":"genus","structure":"Latin noun, third declension","meaning":"kind; race; stock","meaningCN":"种类；族属；血统","example":"The root also stands behind generation and genre.","exampleCN":"这个词根也支撑着世代与体裁等词。"},{"word":"generalis","structure":"Latin adjective","meaning":"of the whole kind","meaningCN":"属于整个类别的","example":"The adjective speaks for the class rather than one member.","exampleCN":"这个形容词为类别而非单个成员说话。"},{"word":"general","structure":"English adjective and noun","meaning":"broad; a high officer","meaningCN":"总的；将军","example":"English keeps the adjective and adds the rank.","exampleCN":"英语保留形容词，又加上军衔。"},{"word":"generally","structure":"general + -ly","meaning":"usually; in broad terms","meaningCN":"通常；一般地","example":"The adverb marks a normal pattern.","exampleCN":"副词标出通常的格局。"},{"word":"generalize","structure":"general + -ize","meaning":"to draw a broad rule","meaningCN":"概括；归纳","example":"The verb turns one case into a class.","exampleCN":"这个动词把一个案例变成一类。"},{"word":"generalization","structure":"generalize + -ation","meaning":"a broad statement","meaningCN":"概括；泛论","example":"The noun names the resulting broad claim.","exampleCN":"这个名词指由此产生的宽泛主张。"},{"word":"generality","structure":"general + -ity","meaning":"the quality of being broad","meaningCN":"普遍性；概略","example":"The noun measures how wide a statement is.","exampleCN":"这个名词衡量陈述有多宽。"},{"word":"generalship","structure":"general + -ship","meaning":"skill in command","meaningCN":"将才；指挥才能","example":"The suffix names the office or the skill.","exampleCN":"后缀指职位或才能。"},{"word":"in general","structure":"preposition + adjective","meaning":"broadly speaking","meaningCN":"总体上","example":"The frame is standard in summary.","exampleCN":"这个框架是概括的标准形式。"}],"latinEntries":[{"word":"genus","structure":"genus, generis (noun, third declension)","meaning":"kind; race; stock","meaningCN":"种类；族属"},{"word":"generalis","structure":"generalis, -e (adjective)","meaning":"of the whole kind","meaningCN":"属于整个类别的"}],"derivatives":[{"word":"general","pos":"adj./n.","zh":"总的；将军"},{"word":"generally","pos":"adv.","zh":"通常"},{"word":"generalize","pos":"v.","zh":"概括"},{"word":"generalization","pos":"n.","zh":"概括"},{"word":"generality","pos":"n.","zh":"普遍性"}]}},{"word":"in essence","ipa_uk":"/ɪn ɪˈsens/","ipa_us":"/ɪn ɪˈsens/","definition_zh":"本质上、实质上；概括地说（指撇开细节之后的根本性质）","definition_en":"fundamentally; in its true nature, once details are set aside","core_image":"一枚果子削去外皮与果肉，只剩中间那颗核","scene":"两个人争了半天条文措辞，旁人听完只说了一句：争的其实是同一件事。In essence, the two proposals ask for the same reform.","sceneCN":"这里取「本质上、实质上」（第 1 个义项：撇开细节后的根本性质）；句意为两个提案实质上要求的是同一项改革。","pos":[{"tag":"adv. phr.","zh":"副词短语：本质上；实质上；概括地说"}],"collocations":[{"phrase":"the same in essence","zh":"实质相同"},{"phrase":"in essence, yes","zh":"实质上是的"},{"phrase":"in essence a question of","zh":"本质上是……问题"},{"phrase":"different in form, same in essence","zh":"形式不同，本质相同"},{"phrase":"in essence, nothing changed","zh":"实质上什么也没变"},{"phrase":"in essence about","zh":"实质上是关于"}],"forms":[{"label":"原形","form":"in essence"},{"label":"句首形式","form":"In essence,"},{"label":"对照形式","form":"in form but not in essence"},{"label":"近形短语","form":"of the essence"}],"derivatives":[{"word":"essence","pos":"n.","zh":"本质；精华；香精"},{"word":"essential","pos":"adj./n.","zh":"必不可少的；要素"},{"word":"essentially","pos":"adv.","zh":"基本上；本质上"},{"word":"essentials","pos":"n.","zh":"要点；必需品"},{"word":"quintessence","pos":"n.","zh":"精髓；典范"}],"senses":[{"no":"01","title":"The true nature","titleCN":"本质义：根本性质","definition":"used to state what something really is once surface differences are removed","definitionCN":"用来陈述剥去表面差异之后某物真正的样子","example":"The two systems differ in form but agree in essence.","exampleCN":"两种制度形式不同，本质一致。","why":"Essence names the being of a thing, so the phrase reaches past appearance to what remains.","whyCN":"本质指事物的存在本身，因此短语越过表象，指向留下来的东西。"},{"no":"02","title":"Beside the single adverb","titleCN":"语法边界：与单词副词的分工","definition":"the frame stands as a sentence adverbial, while the single adverb can sit inside the clause","definitionCN":"这个框架作句子状语，而单词副词可位于小句内部","example":"In essence, the complaint is about pay, not hours.","exampleCN":"实质上，抱怨的是薪酬，不是工时。","why":"A comment on the whole statement differs from a modifier inside it.","whyCN":"对整句的评述不同于句内的修饰语。"},{"no":"03","title":"At bottom","titleCN":"归结义：归根结底","definition":"it reduces a complicated account to its single governing point","definitionCN":"把复杂的叙述归结到那个起支配作用的要点","example":"In essence, the change removes one layer of approval.","exampleCN":"归根结底，这项改变去掉了一层审批。","why":"Reduction is the work of the phrase: many details, one core.","whyCN":"归约正是这个短语的工作：许多细节，一个核心。"},{"no":"04","title":"A summary opener","titleCN":"概述义：句首作总结","definition":"at the start of a sentence it announces a compressed restatement of what came before","definitionCN":"放在句首，预告对前文的压缩重述","example":"In essence, the argument rests on a single assumption.","exampleCN":"实质上，这个论证只依赖一个假设。","why":"The front slot tells the reader that the next clause is the kernel, not a new detail.","whyCN":"前置位置告诉读者，接下来的小句是内核，而不是新细节。"},{"no":"05","title":"Not principle","titleCN":"辨义：本质不同于原则","definition":"it names what a thing is, while the look-alike phrase names what a rule allows in theory","definitionCN":"它指出事物是什么，而形近短语指出规则在理论上允许什么","example":"In principle the plan works; in essence it is a copy of the old one.","exampleCN":"原则上这个方案可行；本质上它只是旧方案的翻版。","why":"Being and permission are different questions, so the two phrases cannot be swapped.","whyCN":"存在与许可属于不同问题，因此两个短语不能互换。"},{"no":"06","title":"The philosophical use","titleCN":"哲学义：追问事物本身","definition":"in philosophy it asks what a thing is apart from its accidents and appearances","definitionCN":"在哲学中追问某物除去偶性与表象之后究竟是什么","example":"Philosophers ask what a thing is in essence.","exampleCN":"哲学家追问一物本质上是什么。","why":"The phrase inherits a technical history, which is why it can sound grave in ordinary prose.","whyCN":"这个短语继承了术语史，因此在普通文字里也会显得庄重。"},{"no":"07","title":"Not the extract","titleCN":"辨义：不表香精或精华液","definition":"the noun can name a concentrated substance, but the phrase speaks of abstract nature","definitionCN":"这个名词可指浓缩物，但短语说的是抽象性质","example":"The perfume is an essence, but the phrase in essence says something else.","exampleCN":"香水本身是一种香精，但实质上这个短语说的是另一回事。","why":"Chemistry gave the noun a concrete sense that the fixed phrase never uses.","whyCN":"化学给了这个名词具体义，而固定短语从不使用它。"},{"no":"08","title":"The closing summary","titleCN":"收束义：句末总结","definition":"it can also close a passage, labelling what the whole account amounted to","definitionCN":"也可用在段末，标出整段叙述归结为何","example":"Both sides want the same outcome in essence.","exampleCN":"双方实质上想要的是同一个结果。","why":"Final position makes the phrase sound like a verdict delivered after the evidence.","whyCN":"末位让这个短语像是听完证据后作出的裁断。"}],"etymology":{"intro":{"en":"Essence comes from Latin essentia, the abstract noun for being, generally attributed to Cicero as a rendering of Greek ousia, from esse, to be. The attribution is the usual one; the phrase is modern.","cn":"essence 来自拉丁语 essentia，即表存在的抽象名词，一般认为由西塞罗仿希腊语 ousia 所造，词根为 esse「存在」。这一归属是通行说法；短语属近代。"},"items":[{"era":"LATIN ESSE","en":"Esse, to be, is the most basic verb of existence and supplies the stem of the noun.","cn":"esse 意为存在，是最基本的存在动词，提供这个名词的词干。"},{"era":"ESSENTIA","en":"Latin needed a noun for what a thing is, and essentia was coined to fill the gap; the attribution to Cicero is the usual one.","cn":"拉丁语需要一个名词来指事物之所是，于是造出 essentia 填补空白；归于西塞罗是通行说法。"},{"era":"GREEK OUSIA","en":"The Greek model named being or substance, and the Latin coinage was meant to match it.","cn":"希腊语原型指存在或实体，拉丁语新造词正是为与之对应。"},{"era":"MEDIEVAL USE","en":"Scholastic writing fixed the word in arguments about substance and accident.","cn":"经院文字把这个词固定在关于实体与偶性的论证中。"},{"era":"THE EXTRACT","en":"Chemistry later applied the noun to a concentrated substance, a sense the phrase ignores.","cn":"化学后来用这个名词指浓缩物，短语并不采用这一义。"},{"era":"THE FIXED PHRASE","en":"The summarising frame belongs to modern prose; first dates are approximate.","cn":"这个概括框架属于近代文字，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the form or the abstract register but differs in what it names; the second group are one-word equivalents of the core sense.","cn":"第一组共用形式或抽象语域，但所指不同；第二组是核心意义的单词对应说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in substance","ipa":"/ɪn ˈsʌbstəns/","tag":"content, not being","definition":"It concerns the main content of a claim, often in legal prose.","definitionCN":"它指主张的主要内容，多用于法律文字。"},{"word":"of the essence","ipa":"/əv ði ɪˈsens/","tag":"essential, urgent","definition":"It means vitally important, often of timing in a contract.","definitionCN":"意为至关重要，常指合同中的时限。"},{"word":"in effect","ipa":"/ɪn ɪˈfekt/","tag":"actual result","definition":"It means in practice or as good as, not in nature.","definitionCN":"意为实际上、等于，而非本质上。"},{"word":"in name","ipa":"/ɪn neɪm/","tag":"label only","definition":"It marks something that exists as a label rather than in fact.","definitionCN":"标出只在名目上而非事实上存在的东西。"}]},{"heading":"NEAR MEANING","entries":[{"word":"essentially","ipa":"/ɪˈsenʃəli/","tag":"one-word form","definition":"A single adverb with the same reduction to the core.","definitionCN":"单词副词，同样归结到核心。"},{"word":"at bottom","ipa":"/æt ˈbɒtəm/","tag":"underneath it all","definition":"It means fundamentally, with an image of depth.","definitionCN":"意为根本上，带深浅意象。"},{"word":"fundamentally","ipa":"/ˌfʌndəˈmentəli/","tag":"foundation","definition":"It points to the base on which a thing rests.","definitionCN":"指向事物所依托的根基。"},{"word":"basically","ipa":"/ˈbeɪsɪkli/","tag":"conversational","definition":"The everyday word for reducing a matter to essentials.","definitionCN":"把问题归到要点的日常说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real verb of being, the coined Latin noun, and the real split from principle and from the chemical extract.","cn":"正常联想用真实的存在动词、拉丁语新造名词，以及与原则义、化学浓缩物义的分工。"},"normal":[{"en":"The root is simply to be, so the phrase asks what a thing is.","cn":"词根就是存在，因此短语追问事物是什么。"},{"en":"Latin coined the noun to name being, and the coinage is usually credited to Cicero.","cn":"拉丁语造出这个名词来指存在，通常归功于西塞罗。"},{"en":"It stands as a comment on the whole sentence, not on one word.","cn":"它评述整句，而非某一个词。"},{"en":"Principle concerns what is allowed in theory; essence concerns what a thing is.","cn":"原则关心理论上允许什么，本质关心事物是什么。"},{"en":"The chemical sense of a concentrated extract never enters the phrase.","cn":"化学上的浓缩物义从不进入这个短语。"}],"abstract":[{"en":"Like a fruit pared down to the stone at its centre.","cn":"像果子削到只剩中间那颗核。"},{"en":"Like a long letter reduced to the one sentence that mattered.","cn":"像一封长信压缩成唯一要紧的那句话。"},{"en":"Like a building stripped of its paint, showing only the frame.","cn":"像剥去漆面的建筑，只剩骨架。"}]},"examples":[{"en":"In essence, the two plans are the same.","cn":"实质上，两个方案是一样的。"},{"en":"The dispute is in essence about water rights.","cn":"这场争端实质上是关于水权。"},{"en":"In essence, nothing in the procedure has changed.","cn":"实质上，程序没有任何改变。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 伊森斯」——果子削到只剩中间那颗核：本质上","word":"in essence"},"root":"核心名词意为本质，出自拉丁语 essentia「存在、本质」，一般认为由西塞罗仿希腊语 ousia 所造，词根为 esse「存在」。该短语为近代书面语定型，首见年代不确定。","sensesIntro":{"en":"Eight senses cover the true nature, the boundary against the single adverb, reduction to the governing point, the summary opener, the contrast with principle, the philosophical use, the exclusion of the extract and the closing verdict.","cn":"八个义项涵盖：根本性质、与单词副词的语法边界、归结到支配要点、概述开篇、与原则的对照、哲学用法、排除浓缩物义，以及句末裁断。"},"semanticMap":{"core":{"en":"CORE IMAGE: a fruit pared of skin and flesh until only the stone at its centre remains.","cn":"核心意象：一枚果子削去皮与肉，只剩中间那颗核。"},"chain":["BE","BEING","NATURE","CORE","SUMMARY","TRUE POINT"],"branches":[{"senses":"01 · 06","en":"THE NATURE: what a thing is, once appearances and accidents are removed.","cn":"性质：剥去表象与偶性之后，事物之所是。"},{"senses":"02","en":"THE GRAMMAR: a comment on the whole clause differs from a modifier inside it.","cn":"语法：评述整句不同于句内修饰语。"},{"senses":"03 · 04","en":"THE REDUCTION: many details are compressed into one kernel, announced at the front.","cn":"归约：许多细节压缩成一个内核，并在句首先行宣告。"},{"senses":"05","en":"THE CONTRAST: a thing's being is not the permission a rule gives.","cn":"对照：事物的存在不同于规则给出的许可。"},{"senses":"07 · 08","en":"THE LIMIT AND THE VERDICT: the chemical extract is excluded, and the phrase may close a passage.","cn":"边界与裁断：排除化学浓缩物，且可用于段末收束。"}]},"affixes":{"intro":{"en":"The phrase rests on a Latin noun coined from the verb to be, so its core is existence rather than appearance.","cn":"这个短语建在一个由存在动词造出的拉丁语名词上，因此其核心是存在而非表象。"},"latinIntro":{"en":"Latin esse, to be, produced essentia, a coinage usually credited to Cicero for rendering Greek ousia.","cn":"拉丁语 esse「存在」造出 essentia，这一新造词通常归功于西塞罗，用来对应希腊语 ousia。"},"items":[{"word":"esse","structure":"Latin verb","meaning":"to be","meaningCN":"存在；是","example":"The verb is the root of the whole family.","exampleCN":"这个词是整族词的根。"},{"word":"essentia","structure":"Latin coined noun","meaning":"being; nature","meaningCN":"存在；本质","example":"The noun was made to name what a thing is.","exampleCN":"这个名词被造来指事物之所是。"},{"word":"essence","structure":"English noun through French","meaning":"nature; extract","meaningCN":"本质；香精","example":"English keeps both the abstract and the chemical senses.","exampleCN":"英语兼留抽象义与化学义。"},{"word":"essential","structure":"essence + -ial","meaning":"necessary to the nature","meaningCN":"本质的；必不可少的","example":"The adjective marks what the nature cannot lack.","exampleCN":"这个形容词标出性质所不能缺少的东西。"},{"word":"essentially","structure":"essential + -ly","meaning":"fundamentally","meaningCN":"基本上；本质上","example":"The adverb reduces a matter to its core.","exampleCN":"副词把问题归到核心。"},{"word":"essentials","structure":"plural noun","meaning":"the basic items","meaningCN":"要点；必需品","example":"The plural gathers what cannot be dropped.","exampleCN":"复数汇集不能省略的东西。"},{"word":"quintessence","structure":"quinta + essence","meaning":"the fifth essence; the purest form","meaningCN":"精髓；典范","example":"The compound adds a fifth element to the four of older physics.","exampleCN":"这个复合词在旧物理的四元素之外加上第五种。"},{"word":"in essence","structure":"preposition + noun","meaning":"fundamentally","meaningCN":"本质上","example":"The frame is standard in summary and verdict.","exampleCN":"这个框架是概括与裁断的标准形式。"},{"word":"of the essence","structure":"preposition + article + noun","meaning":"vitally important","meaningCN":"至关重要的","example":"The other frame turns essence into urgency.","exampleCN":"另一个框架把本质转为紧迫。"}],"latinEntries":[{"word":"esse","structure":"esse, fui (verb, irregular)","meaning":"to be","meaningCN":"存在；是"},{"word":"essentia","structure":"essentia, -ae (noun, first declension, coined)","meaning":"being; nature","meaningCN":"存在；本质"}],"derivatives":[{"word":"essence","pos":"n.","zh":"本质；香精"},{"word":"essential","pos":"adj./n.","zh":"必不可少的；要素"},{"word":"essentially","pos":"adv.","zh":"基本上"},{"word":"essentials","pos":"n.","zh":"要点"},{"word":"quintessence","pos":"n.","zh":"精髓"}]}},{"word":"in principle","ipa_uk":"/ɪn ˈprɪnsəpl/","ipa_us":"/ɪn ˈprɪnsəpl/","definition_zh":"原则上、理论上；大体上（表示道理上成立，但实际未必照此实行）","definition_en":"as a matter of theory or general rule; in the main, though practice may differ","core_image":"图纸上画出一条笔直的线，工地上却要绕开一块巨石","scene":"设计图上那条通道可以直穿山体，施工队到了现场才发现岩层太硬，只能改走侧坡。In principle the tunnel could be driven straight through, but the rock refused.","sceneCN":"这里取「原则上、理论上」（第 1 个义项：道理上可行，实际未必）；句意为原则上隧道可以直穿过去，但岩层不允许。","pos":[{"tag":"adv. phr.","zh":"副词短语：原则上；理论上；大体上"}],"collocations":[{"phrase":"agree in principle","zh":"原则同意"},{"phrase":"in principle and in practice","zh":"理论上与实际中"},{"phrase":"possible in principle","zh":"原则上可行"},{"phrase":"in principle at least","zh":"至少在原则上"},{"phrase":"acceptable in principle","zh":"原则上可接受"},{"phrase":"in principle subject to","zh":"原则上但须视……而定"}],"forms":[{"label":"原形","form":"in principle"},{"label":"句首形式","form":"In principle,"},{"label":"对照形式","form":"in principle but not in practice"},{"label":"近形短语","form":"on principle"}],"derivatives":[{"word":"principle","pos":"n.","zh":"原则；原理；准则"},{"word":"principal","pos":"adj./n.","zh":"主要的；校长（同根不同义）"},{"word":"principally","pos":"adv.","zh":"主要地"},{"word":"principled","pos":"adj.","zh":"有原则的"},{"word":"unprincipled","pos":"adj.","zh":"无原则的"}],"senses":[{"no":"01","title":"True in theory","titleCN":"理论义：道理上成立","definition":"used to say that something is possible or correct as a matter of theory, whether or not it happens","definitionCN":"表示某事在道理上可行或正确，不论实际是否发生","example":"In principle, the two networks can be linked.","exampleCN":"原则上，这两个网络可以互联。","why":"A principle is a starting point, and from a starting point a conclusion may follow without being carried out.","whyCN":"原则是起点，从起点可以推出结论，却未必真的去做。"},{"no":"02","title":"Beside theory talk","titleCN":"近义辨析：与理论说法相近","definition":"it resembles the phrase about theory, though it points to a rule or a foundation rather than to a model","definitionCN":"它与表理论的说法相近，只是指向规则或根基，而非模型","example":"In principle the method is sound; in practice it is too slow.","exampleCN":"这个方法在理论上站得住；实际做起来太慢。","why":"Theory suggests a model of how things work, while principle suggests a rule that governs them.","whyCN":"理论暗示事物运作的模型，原则暗示支配事物的规则。"},{"no":"03","title":"Not on principle","titleCN":"辨义：不同于出于原则","definition":"the phrase states what is possible in theory, while the look-alike with on states what a person refuses or accepts on moral grounds","definitionCN":"这个短语陈述理论上可能的事，而形近短语陈述某人基于道义理由拒绝或接受什么","example":"In principle she accepted the rule, though she disliked it.","exampleCN":"原则上她接受了这条规定，尽管并不喜欢。","why":"One frame is about feasibility, the other about conviction, and the prepositions keep them apart.","whyCN":"一个框架谈可行性，另一个谈信念，介词把两者分开。"},{"no":"04","title":"Agreement with a reserve","titleCN":"会议义：原则同意但留保留","definition":"in committee language it records approval of an idea while details or costs remain to be settled","definitionCN":"在委员会语言中，记录对想法的认可，而细节或费用仍待敲定","example":"The board agreed in principle to the merger.","exampleCN":"董事会原则上同意这次合并。","why":"Approval of a principle is cheaper than approval of a budget, which is why the phrase is so useful in meetings.","whyCN":"认可一项原则比批准一笔预算便宜，因此这个短语在会议上十分好用。"},{"no":"05","title":"A rule of law or policy","titleCN":"原则义：法律与政策准则","definition":"it can state that a right or a duty exists as a general rule, subject to conditions","definitionCN":"可说明某项权利或义务作为通则存在，但须受条件限制","example":"In principle, every citizen may apply for the grant.","exampleCN":"原则上，每位公民都可以申请这项补助。","why":"A general rule covers everyone on paper, and conditions decide what happens in fact.","whyCN":"通则在纸面上覆盖所有人，条件决定事实上如何。"},{"no":"06","title":"The level of a law of nature","titleCN":"原理义：科学原理层面","definition":"in science it marks what follows from a law or a mechanism, before engineering limits are counted","definitionCN":"在科学中，标出由定律或机理推出的事，尚未计入工程限制","example":"In principle the reaction releases energy at room temperature.","exampleCN":"原则上该反应在室温下就释放能量。","why":"A mechanism may allow something that a real apparatus cannot deliver, and the phrase keeps that gap open.","whyCN":"机理允许的事，真实装置未必做得到，这个短语把那个差距留着。"},{"no":"07","title":"Concession, then caveat","titleCN":"让步义：先认可再提条件","definition":"it concedes the general case before the speaker adds a condition or a cost","definitionCN":"先承认一般情形，随后补上条件或代价","example":"The plan is acceptable in principle, subject to cost review.","exampleCN":"这个方案原则上可以接受，但须视成本评审而定。","why":"The frame makes a concession sound generous while keeping a door open for refusal.","whyCN":"这个框架让让步显得大度，同时为拒绝留着一扇门。"},{"no":"08","title":"Not the head of a school","titleCN":"辨义：不表校长或负责人","definition":"the related adjective and noun can name a school head, but the phrase states feasibility only","definitionCN":"相关形容词与名词可指校长，但短语只陈述可行性","example":"In principle marks a theoretical stand, not a school head.","exampleCN":"原则上这一说法标的是理论立场，不是学校校长。","why":"English split the two spellings, and only the noun with the narrower meaning entered this phrase.","whyCN":"英语把两种拼写分了工，只有词义较窄的那个名词进入了这个短语。"}],"etymology":{"intro":{"en":"Principle comes from Latin principium, a beginning or foundation, from princeps, first or chief, built on primus, first, and capere, to take. The Latin chain is secure; the phrase is modern.","cn":"principle 出自拉丁语 principium「开端、基础」，源于 princeps「居首者」，由 primus「第一」与 capere「取」构成。拉丁语链条清楚；短语属近代。"},"items":[{"era":"LATIN PRIMUS","en":"Primus meant first in order, and it stands behind primary and prime as well.","cn":"primus 意为次序上的第一，也支撑着 primary 与 prime 等词。"},{"era":"LATIN CAPERE","en":"Capere meant to take or seize, and its compounds cover capture, reception and acceptance.","cn":"capere 意为拿取、抓取，其复合词涵盖捕获、接收与接受。"},{"era":"PRINCEPS","en":"The compound named the one who takes the first place, hence a chief or a leader.","cn":"这个复合词指占据首位的人，因此指首领。"},{"era":"PRINCIPIUM","en":"The noun moved from a beginning in time to a foundation on which reasoning rests.","cn":"这个名词从时间上的开端转为推理所依托的基础。"},{"era":"TWO ENGLISH WORDS","en":"English keeps principle for a rule and principal for a chief or a school head.","cn":"英语用前者指原则，用后者指首领或校长。"},{"era":"THE FIXED PHRASE","en":"The theoretical qualifier belongs to modern discussion; first dates are approximate.","cn":"这个理论性限定语属于近代讨论，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the form or the root but means a rule, a refusal or a head; the second group are phrases of theory and feasibility.","cn":"第一组共用形式或词根，却指规则、拒绝或负责人；第二组是表理论与可行性的短语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"on principle","ipa":"/ɒn ˈprɪnsəpl/","tag":"moral ground","definition":"It means because of a conviction, not because something is possible.","definitionCN":"意为出于信念，而非因为某事可行。"},{"word":"principal","ipa":"/ˈprɪnsəpl/","tag":"chief; school head","definition":"The look-alike noun names a person or a main sum.","definitionCN":"形近名词指负责人或本金。"},{"word":"in theory","ipa":"/ɪn ˈθɪəri/","tag":"model, not rule","definition":"It contrasts a model with actual practice.","definitionCN":"把模型与实际做法相对。"},{"word":"in practice","ipa":"/ɪn ˈpræktɪs/","tag":"actual doing","definition":"It names what really happens, the usual partner of the frame.","definitionCN":"它指真正发生的情况，常与本短语配对。"}]},{"heading":"NEAR MEANING","entries":[{"word":"theoretically","ipa":"/θiəˈretɪkli/","tag":"one-word form","definition":"A single adverb for what follows from theory.","definitionCN":"由理论推出的单词副词。"},{"word":"on paper","ipa":"/ɒn ˈpeɪpə/","tag":"not yet real","definition":"It means as recorded or planned, before reality tests it.","definitionCN":"意为按记录或计划，尚未经现实检验。"},{"word":"as a rule","ipa":"/æz ə ruːl/","tag":"general habit","definition":"It states what normally happens, not what is possible.","definitionCN":"陈述通常发生的事，而非可能的事。"},{"word":"broadly speaking","ipa":"/ˈbrɔːdli ˈspiːkɪŋ/","tag":"wide summary","definition":"It marks a statement made at a general level.","definitionCN":"标出在一般层面作出的陈述。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real first-taker root, the split between principle and principal, and the real pairing with practice.","cn":"正常联想用真实的居首取位词根、原则与校长的分工，以及与实践的真实配对。"},"normal":[{"en":"The root is the first taker, so a principle is where reasoning starts.","cn":"词根是居首取位者，因此原则是推理起步之处。"},{"en":"Two spellings split the work: a rule on one side, a chief on the other.","cn":"两种拼写分担功能：一边是规则，一边是首领。"},{"en":"Theory gives a model, while principle gives a governing rule.","cn":"理论给出模型，原则给出支配规则。"},{"en":"The phrase usually faces its partner, practice, across a semicolon.","cn":"这个短语常与搭档「实践」隔一个分号相望。"},{"en":"In meetings it records approval of an idea before the bill arrives.","cn":"在会议上，它在账单到来前先记下对想法的认可。"}],"abstract":[{"en":"Like a straight line drawn on a plan, before the boulder on site is seen.","cn":"像图纸上画的直线，工地上的巨石尚未看见。"},{"en":"Like a rule written at the top of a page, with conditions pencilled below.","cn":"像写在页首的规则，条件用铅笔注在下面。"},{"en":"Like a door marked open on a map, which may still be locked in fact.","cn":"像地图上标着开启的门，实际上可能仍锁着。"}]},"examples":[{"en":"In principle, the two systems can share one database.","cn":"原则上，两个系统可以共用一个数据库。"},{"en":"The committee approved the idea in principle.","cn":"委员会原则上同意了这个想法。"},{"en":"In principle the repair is simple, though it needs a crane.","cn":"原则上这次修理很简单，只是需要一台吊车。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 普林塞泼」——图纸上的直线，工地上的巨石：原则上","word":"in principle"},"root":"核心名词意为原则，出自拉丁语 principium「开端、基础」，源于 princeps「居首者」，由 primus「第一」与 capere「取」构成。该短语表原则上为近代用法，首见年代不确定。","sensesIntro":{"en":"Eight senses separate feasibility in theory, the near twin about theory, the contrast with a moral stance, committee approval with a reserve, legal and policy rules, scientific mechanism, concession with a condition, and the exclusion of a school head.","cn":"八个义项区分：理论可行性、与理论说的近义辨析、与道义立场的对照、会议中的保留式同意、法律政策准则、科学机理、带条件的让步，以及排除校长义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a straight line drawn on a plan, while a boulder on the site forces a detour.","cn":"核心意象：图纸上画出的一条直线，而工地上的巨石逼出一条绕行。"},"chain":["FIRST","CHIEF","BEGINNING","FOUNDATION","RULE","THEORY"],"branches":[{"senses":"01 · 06","en":"THE THEORY: what follows from a rule or a mechanism before limits are counted.","cn":"理论：由规则或机理推出的事，尚未计入限制。"},{"senses":"02","en":"THE NEAR TWIN: a model of how things work differs from a rule that governs them.","cn":"近义辨析：事物运作的模型不同于支配它们的规则。"},{"senses":"03","en":"THE CONTRAST: feasibility is not a moral conviction.","cn":"对照：可行性不同于道义信念。"},{"senses":"04 · 07","en":"THE RESERVE: approval of an idea can be given before details or costs are settled.","cn":"保留：在细节或费用敲定前先认可想法。"},{"senses":"05 · 08","en":"THE RULE AND THE LIMIT: general rights are stated, and no school head is meant.","cn":"规则与边界：陈述普遍权利，且不指校长。"}]},"affixes":{"intro":{"en":"The phrase rests on a Latin noun of beginning and foundation built from the words for first and to take.","cn":"这个短语建在一个表开端与基础的拉丁语名词上，该名词由「第一」与「取」两个词构成。"},"latinIntro":{"en":"Latin primus, first, plus capere, to take, gave princeps, the first taker, and principium, a beginning.","cn":"拉丁语 primus「第一」加 capere「取」，给出 princeps「居首取位者」与 principium「开端」。"},"items":[{"word":"primus","structure":"Latin adjective","meaning":"first","meaningCN":"第一的","example":"The adjective supplies the first element.","exampleCN":"这个形容词提供第一个成分。"},{"word":"capere","structure":"Latin verb","meaning":"to take; to seize","meaningCN":"拿取；抓取","example":"The verb supplies the second element.","exampleCN":"这个动词提供第二个成分。"},{"word":"princeps","structure":"Latin noun and adjective","meaning":"first taker; chief","meaningCN":"居首者；首领","example":"The compound names the one who takes first place.","exampleCN":"这个复合词指占据首位的人。"},{"word":"principium","structure":"Latin noun","meaning":"beginning; foundation","meaningCN":"开端；基础","example":"The noun shifts from time to reasoning.","exampleCN":"这个名词从时间转向推理。"},{"word":"principle","structure":"English noun through French","meaning":"a rule; a law of nature","meaningCN":"原则；原理","example":"English narrows it to a governing rule.","exampleCN":"英语把它收窄为支配性规则。"},{"word":"principal","structure":"Latin principalis","meaning":"chief; a school head","meaningCN":"主要的；校长","example":"The doublet kept the personal and the leading senses.","exampleCN":"这个同源异形词保留人身与首要两义。"},{"word":"principled","structure":"principle + -ed","meaning":"acting by rules","meaningCN":"有原则的","example":"The suffix marks a person who follows a rule.","exampleCN":"后缀标出依规则行事的人。"},{"word":"unprincipled","structure":"un- + principled","meaning":"without rules","meaningCN":"无原则的","example":"The negative prefix removes the rule.","exampleCN":"否定前缀去掉了规则。"},{"word":"on principle","structure":"preposition + noun","meaning":"from conviction","meaningCN":"出于原则","example":"The other frame marks a moral ground.","exampleCN":"另一个框架标出道义依据。"},{"word":"in principle","structure":"preposition + noun","meaning":"in theory","meaningCN":"原则上","example":"The frame is standard in feasibility talk.","exampleCN":"这个框架是可行性讨论的标准形式。"}],"latinEntries":[{"word":"primus","structure":"primus, -a, -um (adjective)","meaning":"first","meaningCN":"第一的"},{"word":"capere","structure":"capere, cepi, captum (verb, third conjugation)","meaning":"to take; to seize","meaningCN":"拿取；抓取"},{"word":"principium","structure":"principium, -i (noun, second declension)","meaning":"a beginning; a foundation","meaningCN":"开端；基础"}],"derivatives":[{"word":"principle","pos":"n.","zh":"原则；原理"},{"word":"principal","pos":"adj./n.","zh":"主要的；校长"},{"word":"principally","pos":"adv.","zh":"主要地"},{"word":"principled","pos":"adj.","zh":"有原则的"},{"word":"unprincipled","pos":"adj.","zh":"无原则的"}]}},{"word":"on the other hand","ipa_uk":"/ɒn ði ˈʌðə hænd/","ipa_us":"/ɑːn ði ˈʌðər hænd/","definition_zh":"另一方面；不过话说回来（用于对比前文，或补充第二项考虑）","definition_en":"used to introduce a contrasting point, or a second consideration after the first","core_image":"同一枚硬币翻到背面，图案与正面完全不同","scene":"买房的人算完价格又算通勤，价格低的那套每天要多花两个小时。The flat is cheap; on the other hand, the commute would wear anyone down.","sceneCN":"这里取「另一方面」（第 1 个义项：引出与前文相对的第二项考虑）；句意为这套房便宜，另一方面通勤会让人吃不消。","pos":[{"tag":"adv. phr.","zh":"副词短语：另一方面；不过话说回来"}],"collocations":[{"phrase":"but on the other hand","zh":"但另一方面"},{"phrase":"on the one hand and on the other hand","zh":"一方面与另一方面"},{"phrase":"on the other hand, however","zh":"然而另一方面"},{"phrase":"on the other hand the cost","zh":"另一方面，成本"},{"phrase":"carried on the other hand","zh":"另一方面所承担的"}],"forms":[{"label":"原形","form":"on the other hand"},{"label":"配对形式","form":"on the one hand ... on the other hand"},{"label":"句首形式","form":"On the other hand,"},{"label":"让步形式","form":"on the other hand, though"}],"derivatives":[{"word":"hand","pos":"n./v.","zh":"手；递交"},{"word":"handle","pos":"v./n.","zh":"处理；把手"},{"word":"handy","pos":"adj.","zh":"方便的；手边的"},{"word":"handful","pos":"n.","zh":"一把；少数"},{"word":"handmade","pos":"adj.","zh":"手工制作的"},{"word":"handily","pos":"adv.","zh":"便利地；轻易地"}],"senses":[{"no":"01","title":"The second consideration","titleCN":"对比义：引出第二项考虑","definition":"used to add a point that weighs against or differs from the one just made","definitionCN":"用来补上一个与刚才那点相抗衡或不同的看法","example":"The job pays well; on the other hand, it leaves no time for family.","exampleCN":"这份工作报酬不错；另一方面，它让人没时间陪家人。","why":"Two hands hold two sides of one object, so the image naturally sets a second view beside the first.","whyCN":"两只手各持一物的一面，这个意象自然把第二种看法摆在第一种旁边。"},{"no":"02","title":"The paired frame","titleCN":"配对义：与一方面呼应","definition":"it answers a first phrase that has already opened one side of the comparison","definitionCN":"用来回应前文已经打开比较一侧的那个短语","example":"On the one hand the offer is generous; on the other hand the terms are strict.","exampleCN":"一方面这份报价很慷慨；另一方面条款却很严。","why":"A hand needs its partner, and the pair keeps the reader oriented in a two-sided account.","whyCN":"一只手需要另一只手配，这对短语让读者在双面叙述中不迷失方向。"},{"no":"03","title":"Not the contrast phrase","titleCN":"辨义：不同于强对比说法","definition":"it adds a second side, while the phrase with contrast sets two things sharply against each other","definitionCN":"它补上第二面，而表强对比的短语把两物尖锐对立起来","example":"The first plan is cheaper; on the other hand, the second is faster.","exampleCN":"第一个方案更便宜；另一方面，第二个更快。","why":"Adding a side is gentler than staging a clash, which is why business prose prefers this frame.","whyCN":"补上一面比制造冲突温和，因此商务文字偏爱这个框架。"},{"no":"04","title":"Not the opposite","titleCN":"辨义：不同于截然相反","definition":"it introduces a different consideration, not a denial of what was just said","definitionCN":"它引出另一项考虑，而不是否认刚才所说的话","example":"The weather was bad; on the other hand, the hotel was excellent.","exampleCN":"天气很糟；另一方面，旅馆却很好。","why":"A contrary phrase says the previous claim is false, while this one merely adds weight elsewhere.","whyCN":"表相反的说法断言前一主张为假，而这个短语只是把分量加到别处。"},{"no":"05","title":"Concession after admission","titleCN":"让步义：先承认再转折","definition":"after an admitted weakness it brings in a compensating strength, or the reverse","definitionCN":"在承认某一弱点之后，引入可补偿的长处，或反之","example":"The evidence is thin. On the other hand, no one has offered a better account.","exampleCN":"证据确实单薄。不过另一方面，也没有人提出更好的解释。","why":"Balancing is the everyday work of the phrase, and it often repairs a concession.","whyCN":"权衡是这个短语的日常功能，它常把一次让步修补回来。"},{"no":"06","title":"Two sides of an argument","titleCN":"列举义：并列双方观点","definition":"in discussion it marks the second camp, keeping both positions visible without judging them","definitionCN":"在讨论中标出第二方，让两种立场都可见而不作评判","example":"Supporters stress growth; on the other hand, critics point to the debt.","exampleCN":"支持者强调增长；另一方面，批评者指向债务。","why":"A neutral connector lets a writer report a debate without taking a side.","whyCN":"中性衔接语让作者报道争论而不选边。"},{"no":"07","title":"The spoken turn-back","titleCN":"口语义：话说回来","definition":"in conversation it softens a reversal, as if the speaker has just thought of the other side","definitionCN":"在对话中软化一次转折，仿佛说话人刚想到另一面","example":"It is a long journey. On the other hand, the scenery is worth it.","exampleCN":"路程是远。不过话说回来，风景值得。","why":"A spoken reversal needs a cushion, and the phrase supplies one.","whyCN":"口语中的转折需要缓冲，这个短语正好提供。"},{"no":"08","title":"Not a second hand","titleCN":"辨义：不表另一只手","definition":"the phrase contrasts arguments and never describes a second physical hand","definitionCN":"这个短语对比的是论点，从不描述另一只实际的手","example":"On the other hand introduces a contrast, not a second physical hand.","exampleCN":"另一方面引出的是对比，不是另一只实实在在的手。","why":"The body-part image faded into a metaphor of two sides long ago.","whyCN":"身体部位的意象早已淡化为两面的比喻。"}],"etymology":{"intro":{"en":"Hand is Old English, from a reconstructed Germanic form, with no Latin etymon; other is also native. The phrase grew from the image of holding two sides of one thing.","cn":"hand 属古英语，源自日耳曼语系的重构形式，无拉丁语词源；other 亦为本族词。短语由「一手各持一面」的意象发展而来。"},"items":[{"era":"OLD ENGLISH HAND","en":"Hand named the body part and also possession, control and a side of a bargain.","cn":"这个词指身体部位，也指持有、掌控与交易的一方。"},{"era":"GERMANIC FORM RECONSTRUCTED","en":"The earlier Germanic noun is reconstructed rather than recorded, so its exact shape is not attested.","cn":"更早的日耳曼语名词是重构形式而非有记录的，确切形态无实证。"},{"era":"OLD ENGLISH OTHER","en":"The word for the second of two is native and supplies the contrasting element.","cn":"表两者中另一个的词是本族词，提供对比成分。"},{"era":"THE PAIRED IMAGE","en":"One hand and the other hand picture two sides of one matter held at once.","cn":"一只手与另一只手，描绘同一件事的两面被同时持握。"},{"era":"THE MODERN CONNECTOR","en":"The fixed adverbial phrase belongs to modern argument and correspondence; first dates are approximate.","cn":"这个固定副词短语属于近代论证与书信，首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the hand image or the contrast job but differs in strength; the second group are connectors of contrast and reversal.","cn":"第一组共用手的意象或对比功能，但力度不同；第二组是表对比与转折的衔接语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"on the one hand","ipa":"/ɒn ði wʌn hænd/","tag":"the opening half","definition":"It opens the first side and expects this phrase to follow.","definitionCN":"它打开第一面，并期待本短语随后出现。"},{"word":"on the contrary","ipa":"/ɒn ði ˈkɒntrəri/","tag":"denial","definition":"It asserts that the previous statement is wrong.","definitionCN":"它断言前一陈述是错的。"},{"word":"on the other side","ipa":"/ɒn ði ˈʌðə saɪd/","tag":"spatial or party","definition":"It often refers to a physical side or an opposing party.","definitionCN":"常指实际一侧或对立一方。"},{"word":"on the flip side","ipa":"/ɒn ðə flɪp saɪd/","tag":"informal benefit","definition":"It introduces a compensating advantage in speech.","definitionCN":"口语中引出可补偿的好处。"}]},{"heading":"NEAR MEANING","entries":[{"word":"however","ipa":"/haʊˈevə/","tag":"one-word hinge","definition":"A single adverb for a contrast, usable in mid-sentence.","definitionCN":"单词副词表转折，可用于句中。"},{"word":"in contrast","ipa":"/ɪn ˈkɒntrɑːst/","tag":"sharp difference","definition":"It sets two things against each other explicitly.","definitionCN":"明确把两物对立起来。"},{"word":"conversely","ipa":"/kənˈvɜːsli/","tag":"reversed relation","definition":"It marks the reversed version of the same relation.","definitionCN":"标出同一关系的反向表述。"},{"word":"then again","ipa":"/ðen əˈɡen/","tag":"spoken reconsideration","definition":"It means on second thought, in conversation.","definitionCN":"口语中表示转念一想。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the native origin, the paired-hand image and the real difference from contrary and contrast.","cn":"正常联想用本族词来源、双手配对的意象，以及与相反、强对比的真实差别。"},"normal":[{"en":"Two hands hold two sides of one thing, so the phrase adds a side rather than denies one.","cn":"两只手各持一面，因此短语是补上一面，而非否认一面。"},{"en":"It expects its partner to have opened the other side earlier.","cn":"它期待搭档已在前文打开另一面。"},{"en":"A contrary word calls the first claim false; this one only adds weight elsewhere.","cn":"表相反的词说前一主张为假；这个只把分量加到别处。"},{"en":"In conversation it cushions a reversal.","cn":"在对话中它为转折提供缓冲。"},{"en":"The body-part image is long dead; no actual hand is meant.","cn":"身体部位的意象早已消亡，并不指实际的手。"}],"abstract":[{"en":"Like a coin turned over: the same object, a different face.","cn":"像硬币翻面：同一枚，另一张脸。"},{"en":"Like a balance held in two hands, one pan rising as the other falls.","cn":"像两手托着天平，一盘升另一盘落。"},{"en":"Like a debate table with speakers seated on opposite sides.","cn":"像辩论桌，发言者分坐两侧。"}]},"examples":[{"en":"The train is faster; on the other hand, the bus is cheaper.","cn":"火车更快；另一方面，公共汽车更便宜。"},{"en":"On the other hand, the second candidate has more experience.","cn":"另一方面，第二位候选人经验更丰富。"},{"en":"The work is hard. On the other hand, it pays well.","cn":"这活很辛苦。不过话说回来，报酬不错。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「昂 则 阿泽 汉德」——一枚硬币翻到背面：另一方面","word":"on the other hand"},"root":"核心名词意为手，来自古英语 hand，源自日耳曼语系的 handuz（重构形式），无拉丁语同源；该短语由一手与另一手的对称意象发展而来，首见年代不确定。","sensesIntro":{"en":"Eight senses separate the second consideration, the paired frame, the contrast with sharper connectors, the contrast with denial, concession after admission, two camps in a debate, the spoken reversal and the exclusion of a literal hand.","cn":"八个义项区分：第二项考虑、配对框架、与更强对比语的差别、与否认的差别、承认后的让步、辩论中的两方、口语转折，以及排除字面上的手。"},"semanticMap":{"core":{"en":"CORE IMAGE: the same coin turned over, the reverse face showing a different pattern.","cn":"核心意象：同一枚硬币翻过来，背面显出不同的图案。"},"chain":["HAND","SIDE","SECOND SIDE","CONTRAST","BALANCE","QUALIFICATION"],"branches":[{"senses":"01 · 03","en":"THE SECOND SIDE: another consideration is added beside the first.","cn":"第二面：在第一项旁边补上另一项考虑。"},{"senses":"02","en":"THE PAIR: the frame answers an opening phrase that has already taken one side.","cn":"配对：这个框架回应已经取了一面的前文短语。"},{"senses":"04","en":"THE CONTRAST: adding a side is not denying the previous claim.","cn":"对照：补一面不等于否认前一主张。"},{"senses":"05 · 07","en":"THE BALANCE: a weakness is repaired by a strength, in writing or in speech.","cn":"权衡：无论书面还是口语，弱点由长处补回。"},{"senses":"06 · 08","en":"THE TWO CAMPS AND THE LIMIT: a debate shows both sides, and no body part is meant.","cn":"两方与边界：辩论呈现双方，且不指身体部位。"}]},"affixes":{"intro":{"en":"The phrase is wholly native in its nouns, so its affix section records Germanic forms rather than Latin roots.","cn":"这个短语的两个名词都是本族词，因此词缀部分记录日耳曼语形式而非拉丁词根。"},"latinIntro":{"en":"There is no Latin etymon for either noun: hand and other are native Germanic words, and the earlier forms are reconstructed.","cn":"两个名词都没有拉丁语词源：它们都是日耳曼语本族词，更早的形式为重构形式。"},"items":[{"word":"hand","structure":"Old English noun","meaning":"the body part; control","meaningCN":"手；掌控","example":"English keeps the limb and the possession senses.","exampleCN":"英语兼留肢体与持有两义。"},{"word":"other","structure":"Old English adjective and pronoun","meaning":"the second of two","meaningCN":"两者中的另一个","example":"The word supplies the contrasting half.","exampleCN":"这个词提供对比的另一半。"},{"word":"handle","structure":"hand + -le","meaning":"to manage; a grip","meaningCN":"处理；把手","example":"The verb pictures taking something in hand.","exampleCN":"这个动词描绘把东西拿在手里。"},{"word":"handy","structure":"hand + -y","meaning":"close at hand; useful","meaningCN":"手边的；方便的","example":"The adjective keeps the idea of being within reach.","exampleCN":"这个形容词保留伸手可及的意思。"},{"word":"handful","structure":"hand + -ful","meaning":"as much as one hand holds","meaningCN":"一把；少量","example":"The suffix measures a quantity by the hand.","exampleCN":"后缀以手为单位量取分量。"},{"word":"handmade","structure":"hand + made","meaning":"made by hand","meaningCN":"手工制作的","example":"The compound contrasts with machine production.","exampleCN":"这个复合词与机器生产相对。"},{"word":"handily","structure":"handy + -ly","meaning":"easily; conveniently","meaningCN":"便利地","example":"The adverb marks ease of handling.","exampleCN":"副词标出处理的容易。"},{"word":"on the one hand","structure":"preposition + article + numeral + noun","meaning":"the first side","meaningCN":"一方面","example":"The partner opens the comparison.","exampleCN":"搭档短语打开比较。"},{"word":"on the other hand","structure":"preposition + article + adjective + noun","meaning":"the second side","meaningCN":"另一方面","example":"The frame is standard in balanced argument.","exampleCN":"这个框架在平衡论证中是标准用法。"}],"latinEntries":[],"derivatives":[{"word":"hand","pos":"n./v.","zh":"手；递交"},{"word":"handle","pos":"v./n.","zh":"处理；把手"},{"word":"handy","pos":"adj.","zh":"方便的"},{"word":"handful","pos":"n.","zh":"一把；少量"},{"word":"handmade","pos":"adj.","zh":"手工制作的"}]}},{"word":"in other words","ipa_uk":"/ɪn ˈʌðə wɜːdz/","ipa_us":"/ɪn ˈʌðər wɜːrdz/","definition_zh":"换句话说；也就是说（用另一种说法重述前文，使之更清楚）","definition_en":"expressed differently; that is to say, restating the same point more clearly","core_image":"同一段话被抄到另一张纸上，字句换了，意思没变","scene":"讲师写完一长串术语，看学生一脸茫然，便把整句话换成日常说法又讲了一遍。In other words, the machine learns by trial and error.","sceneCN":"这里取「换句话说」（第 1 个义项：用另一种说法重述同一意思）；句意为换句话说，这台机器靠反复试错来学习。","pos":[{"tag":"adv. phr.","zh":"副词短语：换句话说；也就是说"}],"collocations":[{"phrase":"or in other words","zh":"或者换句话说"},{"phrase":"put in other words","zh":"换种说法表达"},{"phrase":"in other words, that is","zh":"换句话说也就是"},{"phrase":"said in other words","zh":"用另一种说法讲"},{"phrase":"in other words, the opposite","zh":"换句话说，正相反"},{"phrase":"in other words, a failure","zh":"换言之，一次失败"}],"forms":[{"label":"原形","form":"in other words"},{"label":"句首形式","form":"In other words,"},{"label":"变体","form":"or in other words"},{"label":"变体","form":"put it in other words"}],"derivatives":[{"word":"word","pos":"n.","zh":"词；话语；消息"},{"word":"wording","pos":"n.","zh":"措辞；用词"},{"word":"wordy","pos":"adj.","zh":"啰嗦的；冗长的"},{"word":"wordless","pos":"adj.","zh":"无言的"},{"word":"wordplay","pos":"n.","zh":"双关；文字游戏"}],"senses":[{"no":"01","title":"The restatement","titleCN":"重述义：换一种说法说同一件事","definition":"used to repeat a statement in different language so that its meaning becomes clearer","definitionCN":"用不同的说法重复同一陈述，使其意思更清楚","example":"The filter removes particles; in other words, it cleans the air.","exampleCN":"滤芯去除颗粒；换句话说，它清洁空气。","why":"Two sets of words can carry one thought, and the phrase announces the second set.","whyCN":"两套词可以承载同一个想法，这个短语宣告第二套词登场。"},{"no":"02","title":"Plain language","titleCN":"通俗义：用更简单的话说","definition":"it often introduces a simpler version for readers who did not follow the first wording","definitionCN":"常引出更简单的版本，供没听懂第一种说法的人使用","example":"The process is irreversible; in other words, you cannot undo it.","exampleCN":"这个过程不可逆；换句话说，你无法撤销。","why":"Technical wording excludes readers, and a plain restatement brings them back in.","whyCN":"技术措辞把读者挡在门外，通俗重述把他们请回来。"},{"no":"03","title":"Beside the short formula","titleCN":"辨义：与简短等同说法不同","definition":"the frame restates in full sentences, while the short formula usually equates two terms inside one","definitionCN":"这个框架用完整句子重述，而简短的等同说法通常在一句之内把两个术语相等","example":"The two terms are equal; in other words, either may be used.","exampleCN":"这两个术语相等；换句话说，用哪一个都行。","why":"An equation names two items; a restatement repeats a whole claim.","whyCN":"等同说法点出两个项目；重述则重复整个主张。"},{"no":"04","title":"Not a list","titleCN":"辨义：不同于列举","definition":"it rephrases a claim, while the look-alike word introduces a list of the very things meant","definitionCN":"它改写一项主张，而形近的词引出所指的若干具体项目","example":"The report covers three areas; in other words, it is a full survey.","exampleCN":"报告涵盖三个方面；换句话说，它是一次全面调查。","why":"Listing expands a category; restating translates it.","whyCN":"列举展开一个类别，重述则把它翻译一遍。"},{"no":"05","title":"The conclusion restated","titleCN":"结论义：把推论换成白话","definition":"after an argument it states the conclusion in words that carry no technical weight","definitionCN":"在论证之后，用不带术语分量的说法把结论说出来","example":"Costs exceed income; in other words, the project is running at a loss.","exampleCN":"支出超过收入；换句话说，这个项目在亏损。","why":"A conclusion often needs translation before it can be acted on.","whyCN":"结论往往要翻译成白话才能据以行动。"},{"no":"06","title":"The academic gloss","titleCN":"学术义：论文中的释义","definition":"in scholarly prose it glosses a technical result for readers outside the specialty","definitionCN":"在学术文字中，为专业外的读者解释一项技术结论","example":"The sample is biased; in other words, it does not represent the whole.","exampleCN":"样本有偏；换句话说，它不能代表整体。","why":"Specialists write for each other, and a gloss keeps the wider audience included.","whyCN":"专家彼此写作，释义把更广的读者留在场内。"},{"no":"07","title":"The spoken clarification","titleCN":"口语义：日常澄清","definition":"in conversation it repairs a misunderstanding by saying the same thing a second way","definitionCN":"在对话中用第二种说法修补误解","example":"He is late again; in other words, we start without him.","exampleCN":"他又迟到了；换句话说，我们不等他先开始。","why":"Speech is easily misheard, so a second version acts as a safety net.","whyCN":"口语容易听漏，第二种说法就像一张安全网。"},{"no":"08","title":"Clarifying, not swapping words","titleCN":"辨义：不是逐词替换","definition":"the phrase explains a meaning and does not mean replacing one word with a synonym","definitionCN":"这个短语解释意义，并非指把一个词换成同义词","example":"She is not wrong; in other words, she is right about the main point.","exampleCN":"她并没有错；换句话说，她在要点上是对的。","why":"A thesaurus swaps labels, while this frame swaps the whole sentence around one meaning.","whyCN":"同义词词典换标签，这个框架则围绕同一意义换掉整句。"}],"etymology":{"intro":{"en":"Word is Old English, from a reconstructed Germanic noun, with no Latin etymon; other is native too. The restating formula is modern.","cn":"word 属古英语，源自日耳曼语系的重构名词，无拉丁语词源；other 亦为本族词。这个重述句式属近代。"},"items":[{"era":"OLD ENGLISH WORD","en":"Word named a spoken unit and also a saying, a promise or news.","cn":"这个词指口语单位，也指说法、诺言或消息。"},{"era":"GERMANIC FORM RECONSTRUCTED","en":"The earlier Germanic noun is reconstructed rather than attested, so its exact shape is inferred.","cn":"更早的日耳曼语名词是重构而非有记录的，确切形态属推断。"},{"era":"OLD ENGLISH OTHER","en":"The native word for another supplies the contrasting element in the frame.","cn":"表另一个的本族词提供框架中的对比成分。"},{"era":"THE RESTATING FORMULA","en":"The phrase settles into modern expository and teaching prose.","cn":"这个句式在近代说明文与教学文字中定型。"},{"era":"REGISTER","en":"Speech and academic writing both use it, which keeps it unusually flexible; first dates are approximate.","cn":"口语与学术写作都使用它，因此它格外灵活；首见年代为约数。"}]},"similar":{"note":{"en":"The first group shares the word element or looks similar but means something else; the second group are other restating and naming formulas.","cn":"第一组共用词这一成分或外形相近，但另有他义；第二组是其他重述与点名句式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"in a word","ipa":"/ɪn ə wɜːd/","tag":"summary in one word","definition":"It means briefly, summing everything up in a single term.","definitionCN":"意为简言之，用一个词概括全部。"},{"word":"word for word","ipa":"/wɜːd fɔː wɜːd/","tag":"exact copying","definition":"It means with every word reproduced, as in a translation.","definitionCN":"意为逐字复制，如逐字翻译。"},{"word":"in so many words","ipa":"/ɪn səʊ ˈmæni wɜːdz/","tag":"explicitly stated","definition":"It means put plainly, often of something blunt.","definitionCN":"意为明白说出，常指直白的话。"},{"word":"by word of mouth","ipa":"/baɪ wɜːd əv maʊθ/","tag":"spoken transmission","definition":"It means passed on in speech rather than in writing.","definitionCN":"意为靠口头而非书面传递。"}]},{"heading":"NEAR MEANING","entries":[{"word":"that is","ipa":"/ðæt ɪz/","tag":"equating formula","definition":"It equates a term with its explanation, often mid-sentence.","definitionCN":"把术语与其解释相等，常用于句中。"},{"word":"namely","ipa":"/ˈneɪmli/","tag":"naming a list","definition":"It introduces the specific items meant, not a restatement.","definitionCN":"引出所指的具体项目，而非重述。"},{"word":"to put it another way","ipa":"/tuː pʊt ɪt əˈnʌðə weɪ/","tag":"fuller variant","definition":"A longer spoken formula with the same restating job.","definitionCN":"更长的口语说法，功能相同。"},{"word":"i.e.","ipa":"/ˌaɪˈiː/","tag":"written abbreviation","definition":"A compact written marker used in technical text.","definitionCN":"技术文字中紧凑的书面标记。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the native origin, the real difference from listing and word-swapping, and the real teaching function.","cn":"正常联想用本族词来源、与列举及换词的真实差别，以及真实的教学功能。"},"normal":[{"en":"Two sets of words can hold one thought, and the frame brings in the second set.","cn":"两套词可装同一个想法，这个框架把第二套请进来。"},{"en":"A list expands a category; a restatement translates it.","cn":"列举展开类别，重述翻译类别。"},{"en":"A thesaurus swaps labels, while this frame swaps the whole sentence.","cn":"同义词词典换标签，这个框架换整句。"},{"en":"Plain wording brings excluded readers back into the room.","cn":"通俗措辞把被挡在门外的读者请回屋里。"},{"en":"In speech it works as a safety net against mishearing.","cn":"在口语中它像防听漏的安全网。"}],"abstract":[{"en":"Like the same passage copied onto a second sheet in different handwriting.","cn":"像同一段话用另一种笔迹抄到第二张纸上。"},{"en":"Like a phrase said twice, once to the specialist and once to the child.","cn":"像同一句话讲两遍，一遍给专家，一遍给孩子。"},{"en":"Like a label translated on a package so both buyers can read it.","cn":"像包装上的标签译成两种文字，让两类买家都读得懂。"}]},"examples":[{"en":"The scheme costs too much; in other words, it is not viable.","cn":"这个方案花费太高；换句话说，它不可行。"},{"en":"He was absent; in other words, the vote was lost.","cn":"他缺席了；换句话说，表决输了。"},{"en":"In other words, the two designs serve the same purpose.","cn":"换句话说，这两个设计服务于同一目的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「因 阿泽 沃兹」——同一段话抄到另一张纸上：换句话说","word":"in other words"},"root":"核心名词意为词，来自古英语 word，源自日耳曼语系的 wurdą（重构形式），无拉丁语同源。该短语为近代重述性衔接语，首见年代不确定。","sensesIntro":{"en":"Eight senses cover the restatement, plain language, the boundary against the short equating formula, the boundary against listing, the restated conclusion, the academic gloss, the spoken clarification and the exclusion of word-swapping.","cn":"八个义项涵盖：重述、通俗化、与简短等同句式的边界、与列举的边界、结论重述、学术释义、口语澄清，以及排除逐词替换。"},"semanticMap":{"core":{"en":"CORE IMAGE: the same passage copied onto a second sheet in different handwriting.","cn":"核心意象：同一段话用另一种笔迹抄到第二张纸上。"},"chain":["WORD","SAYING","RESTATEMENT","SIMPLER FORM","CLARITY","CONCLUSION"],"branches":[{"senses":"01 · 02","en":"THE RESTATEMENT: a second wording carries the first meaning into clearer light.","cn":"重述：第二种措辞把原意带到更亮处。"},{"senses":"03 · 04","en":"THE BOUNDARIES: an equation names two terms, and a list names items.","cn":"边界：等同句式点两个术语，列举点名项目。"},{"senses":"05","en":"THE CONCLUSION: an argument's end is translated into words that can be acted on.","cn":"结论：论证的终点被译成可据以行动的话。"},{"senses":"06","en":"THE GLOSS: scholarship explains a result to readers outside the field.","cn":"释义：学术把结论解释给领域外的读者。"},{"senses":"07 · 08","en":"THE SPOKEN NET AND THE LIMIT: a second version guards against mishearing, and no synonym swap is meant.","cn":"口语安全网与边界：第二版本防听漏，且不指换同义词。"}]},"affixes":{"intro":{"en":"The phrase is native in both nouns, so its affix section records Germanic forms and the modern pattern rather than Latin roots.","cn":"这个短语的两个名词都是本族词，因此词缀部分记录日耳曼语形式与现代句式，而非拉丁词根。"},"latinIntro":{"en":"Neither noun has a Latin etymon: word and other are native Germanic words whose earlier forms are reconstructed.","cn":"两个名词都没有拉丁语词源：它们都是日耳曼语本族词，更早的形式为重构形式。"},"items":[{"word":"word","structure":"Old English noun","meaning":"a word; a saying","meaningCN":"词；话语","example":"English keeps the unit and the promise senses.","exampleCN":"英语兼留单位与诺言两义。"},{"word":"other","structure":"Old English adjective","meaning":"another","meaningCN":"另一个","example":"The word supplies the alternative in the frame.","exampleCN":"这个词提供框架中的替代项。"},{"word":"wording","structure":"word + -ing","meaning":"the way something is phrased","meaningCN":"措辞；用词","example":"The noun names the arrangement of words.","exampleCN":"这个名词指词语的安排。"},{"word":"wordy","structure":"word + -y","meaning":"using too many words","meaningCN":"啰嗦的","example":"The adjective criticises excess wording.","exampleCN":"这个形容词批评用词过多。"},{"word":"wordless","structure":"word + -less","meaning":"without speech","meaningCN":"无言的","example":"The suffix removes speech altogether.","exampleCN":"后缀把言语整个去掉。"},{"word":"wordplay","structure":"word + play","meaning":"clever use of words","meaningCN":"双关；文字游戏","example":"The compound names play with meanings.","exampleCN":"这个复合词指对意义的戏耍。"},{"word":"that is","structure":"demonstrative + verb","meaning":"that is to say","meaningCN":"也就是说","example":"The short formula equates two expressions.","exampleCN":"简短说法把两个表达相等。"},{"word":"in other words","structure":"preposition + adjective + plural noun","meaning":"restated differently","meaningCN":"换句话说","example":"The frame is standard in explanation.","exampleCN":"这个框架是解释中的标准形式。"},{"word":"to put it another way","structure":"infinitive + pronoun + noun","meaning":"restated differently","meaningCN":"换一种说法","example":"The longer spoken variant performs the same task.","exampleCN":"较长的口语变体承担同样功能。"}],"latinEntries":[],"derivatives":[{"word":"word","pos":"n.","zh":"词；话语"},{"word":"wording","pos":"n.","zh":"措辞"},{"word":"wordy","pos":"adj.","zh":"啰嗦的"},{"word":"wordless","pos":"adj.","zh":"无言的"},{"word":"wordplay","pos":"n.","zh":"双关"}]}}]);
